window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["LEV"]={"book":"LEV","editions":{"fin-biblia1776":[[1,1,"Ja Herra kutsui Moseksen, ja puhui hänelle seurakunnan majasta, sanoen:","Ja Herra kutsui Moseksen, ja puhui hänelle seurakunnan majasta, sanoen:"],[1,2,"Puhu Israelin lapsille, ja sano heille: joka teistä tahtoo uhrata Herralle, niin tehkäät teidän uhrinne eläimistä, karjasta ja lampaista.","Puhu Israelin lapsille, ja sano heille: joka teistä tahtoo uhrata Herralle, niin tehkäät teidän uhrinne eläimistä, karjasta ja lampaista."],[1,3,"Jos hän tahtoo Herralle polttouhria karjasta tehdä, niin uhratkaan virheettömän härkyisen: seurakunnan majan oven edessä hän sen uhratkaan, että se olis Herralle otollinen häneltä.","Jos hän tahtoo Herralle polttouhria karjasta tehdä, niin uhratkaan virheettömän härkyisen: seurakunnan majan oven edessä hän sen uhratkaan, että se olis Herralle otollinen häneltä."],[1,4,"Ja pankaan kätensä sen polttouhrin pään päälle, niin se on otollinen häntä sovittamaan.","Ja pankaan kätensä sen polttouhrin pään päälle, niin se on otollinen häntä sovittamaan."],[1,5,"Ja hänen pitää teurastaman mullin Herran edessä; ja papit, Aaronin pojat, pitää tuoman veren ja priiskottaman alttarille ympärinsä, joka on seurakunnan majan oven edessä.","Ja hänen pitää teurastaman mullin Herran edessä; ja papit, Aaronin pojat, pitää tuoman veren ja priiskottaman alttarille ympärinsä, joka on seurakunnan majan oven edessä."],[1,6,"Ja vuota pitää polttouhrista nyljettämän ja pitää kappaleiksi hakattaman.","Ja vuota pitää polttouhrista nyljettämän ja pitää kappaleiksi hakattaman."],[1,7,"Ja papin Aaronin pojat pitää tekemän tulen alttarille ja halvot tulen päälle paneman.","Ja papin Aaronin pojat pitää tekemän tulen alttarille ja halvot tulen päälle paneman."],[1,8,"Ja papit Aaronin pojat pitää sovittaman kappaleet, pään ja lihavuuden, halkoin päälle, jotka ovat alttarilla tulen päällä.","Ja papit Aaronin pojat pitää sovittaman kappaleet, pään ja lihavuuden, halkoin päälle, jotka ovat alttarilla tulen päällä."],[1,9,"Mutta sisällykset ja jalat pitää vedellä pestämän, ja papin pitää kaikki nämät polttaman alttarilla: polttouhriksi, ja lepytyshajun tuleksi Herralle.","Mutta sisällykset ja jalat pitää vedellä pestämän, ja papin pitää kaikki nämät polttaman alttarilla: polttouhriksi, ja lepytyshajun tuleksi Herralle."],[1,10,"Ja jos hän tahtoo tehdä polttouhria pienistä eläimistä, lampaista eli vuohista, niin uhratkaan virheettömän oinaan eli kauriin.","Ja jos hän tahtoo tehdä polttouhria pienistä eläimistä, lampaista eli vuohista, niin uhratkaan virheettömän oinaan eli kauriin."],[1,11,"Ja teurastakaan sen Herran edessä pohjan puolella alttaria, ja papit, Aaronin pojat, pitää priiskottaman hänen verensä alttarille ympärinsä.","Ja teurastakaan sen Herran edessä pohjan puolella alttaria, ja papit, Aaronin pojat, pitää priiskottaman hänen verensä alttarille ympärinsä."],[1,12,"Ja se pitää hakattaman kappaleiksi, sekä pää että lihavuus, ja papin pitää ne sovittaman halkoin päälle, jotka ovat alttarilla tulen päällä.","Ja se pitää hakattaman kappaleiksi, sekä pää että lihavuus, ja papin pitää ne sovittaman halkoin päälle, jotka ovat alttarilla tulen päällä."],[1,13,"Mutta sisällykset ja jalat pitää vedellä pestämän, ja papin pitää sen kaiken uhraaman ja polttaman alttarillla: se on polttouhri, tuliuhri ja lepytyshaju Herralle.","Mutta sisällykset ja jalat pitää vedellä pestämän, ja papin pitää sen kaiken uhraaman ja polttaman alttarillla: se on polttouhri, tuliuhri ja lepytyshaju Herralle."],[1,14,"Jos hän tahtoo taas tehdä polttouhria Herralle linnuista, niin tehkään sen mettisistä, elikkä kyhkyläisten pojista.","Jos hän tahtoo taas tehdä polttouhria Herralle linnuista, niin tehkään sen mettisistä, elikkä kyhkyläisten pojista."],[1,15,"Ja papin pitää sen alttarille tuoman, ja niskan poikki vääntämän, ja alttarilla polttaman, ja antaman veren vuotaa alttarin seinään.","Ja papin pitää sen alttarille tuoman, ja niskan poikki vääntämän, ja alttarilla polttaman, ja antaman veren vuotaa alttarin seinään."],[1,16,"Ja ottakaan hänen kupunsa höyheninensä ulos, ja heittäkään ne alttarin viereen itään päin, tuhka-ko'on päälle.","Ja ottakaan hänen kupunsa höyheninensä ulos, ja heittäkään ne alttarin viereen itään päin, tuhka-ko'on päälle."],[1,17,"Ja pitää sen siipinensä halkaiseman, mutta ei erinänsä repäisemän. Ja niin papin pitää sillänsä sen polttaman halkoin päällä, jotka ovat alttarilla tulen päällä: tämä on polttouhri, tuliuhri ja lepytyshaju Herralle.","Ja pitää sen siipinensä halkaiseman, mutta ei erinänsä repäisemän. Ja niin papin pitää sillänsä sen polttaman halkoin päällä, jotka ovat alttarilla tulen päällä: tämä on polttouhri, tuliuhri ja lepytyshaju Herralle."],[2,1,"Ja jos joku henki tahtoo tehdä Herralle ruokauhria, niin sen pitää oleman sämpyläjauhoista, ja hänen pitää öljyä sen päälle vuodattaman ja pyhää savua sen päälle paneman,","Ja jos joku henki tahtoo tehdä Herralle ruokauhria, niin sen pitää oleman sämpyläjauhoista, ja hänen pitää öljyä sen päälle vuodattaman ja pyhää savua sen päälle paneman,"],[2,2,"Ja sitte sen papeille Aaronin pojille viemän: niin pitää papin ottaman pivonsa täyden niistä sämpyläjauhoista, ja öljyä kaiken pyhän savun kanssa, ja sen polttaman alttarilla muistoksi. Tämä on tuliuhri ja lepytyshaju Herralle.","Ja sitte sen papeille Aaronin pojille viemän: niin pitää papin ottaman pivonsa täyden niistä sämpyläjauhoista, ja öljyä kaiken pyhän savun kanssa, ja sen polttaman alttarilla muistoksi. Tämä on tuliuhri ja lepytyshaju Herralle."],[2,3,"Se kuin jää ruokauhrista, pitää oleman Aaronin ja hänen poikainsa oman: sen pitää oleman kaikkein pyhimmän Herran tulista.","Se kuin jää ruokauhrista, pitää oleman Aaronin ja hänen poikainsa oman: sen pitää oleman kaikkein pyhimmän Herran tulista."],[2,4,"Mutta jos sinä tahdot tehdä ruokauhria pätsissä kypsytetystä, niin ota happamattomia kyrsiä sämpyläjauhoista öljyyn sekoitettuna, ja happamattomia ohukaisia kyrsiä öljyllä voideltuita.","Mutta jos sinä tahdot tehdä ruokauhria pätsissä kypsytetystä, niin ota happamattomia kyrsiä sämpyläjauhoista öljyyn sekoitettuna, ja happamattomia ohukaisia kyrsiä öljyllä voideltuita."],[2,5,"Vaan jos sinun ruokauhris on pannussa kypsetystä, niin sen pitää oleman happamattomista sämpyläjauhoista öljyyn sekoitettuna.","Vaan jos sinun ruokauhris on pannussa kypsetystä, niin sen pitää oleman happamattomista sämpyläjauhoista öljyyn sekoitettuna."],[2,6,"Sen sinun pitää jakaman kappaleiksi, ja vuodattaman öljyä sen päälle: niin se on ruokauhri.","Sen sinun pitää jakaman kappaleiksi, ja vuodattaman öljyä sen päälle: niin se on ruokauhri."],[2,7,"Ja jos sinun ruokauhris on halstarilla kypsetystä, niin sinun pitää tekemän sen sämpyläjauhoista öljyn kanssa.","Ja jos sinun ruokauhris on halstarilla kypsetystä, niin sinun pitää tekemän sen sämpyläjauhoista öljyn kanssa."],[2,8,"Ja sen ruokauhrin, jonka sinä tahdot senkaltaisista tehdä Herralle, pitää sinun tuoman papille, ja kantaman sen alttarin tykö.","Ja sen ruokauhrin, jonka sinä tahdot senkaltaisista tehdä Herralle, pitää sinun tuoman papille, ja kantaman sen alttarin tykö."],[2,9,"Ja papin pitää ylentämän sen ruokauhrin muistoksi ja polttaman alttarilla. Se on tuliuhri ja lepytyshaju Herralle.","Ja papin pitää ylentämän sen ruokauhrin muistoksi ja polttaman alttarilla. Se on tuliuhri ja lepytyshaju Herralle."],[2,10,"Tähteet ruokauhrista tulee oleman Aaronin ja hänen poikainsa omat: sen pitää oleman kaikkein pyhimmän Herran tulista.","Tähteet ruokauhrista tulee oleman Aaronin ja hänen poikainsa omat: sen pitää oleman kaikkein pyhimmän Herran tulista."],[2,11,"Kaiken ruokauhrin, kuin te uhraatte Herralle, pitää teidän tekemän ilman hapatusta: sillä ei yhtään hapatusta eli hunajaa pidä siinä poltettaman uhriksi Herralle.","Kaiken ruokauhrin, kuin te uhraatte Herralle, pitää teidän tekemän ilman hapatusta: sillä ei yhtään hapatusta eli hunajaa pidä siinä poltettaman uhriksi Herralle."],[2,12,"Mutta uutisten uhrissa pitää teidän ne uhraaman Herralle; vaan ei ne pidä tuleman alttarille makiaksi hajuksi.","Mutta uutisten uhrissa pitää teidän ne uhraaman Herralle; vaan ei ne pidä tuleman alttarille makiaksi hajuksi."],[2,13,"Kaiken sinun ruokauhris pitää sinun suolaaman, ja sinun ruokauhris ei pidä ikänänsä ilman sinun Jumalas liittosuolata oleman; sillä kaikissa sinun uhreissas pitää sinun suolaa uhraaman.","Kaiken sinun ruokauhris pitää sinun suolaaman, ja sinun ruokauhris ei pidä ikänänsä ilman sinun Jumalas liittosuolata oleman; sillä kaikissa sinun uhreissas pitää sinun suolaa uhraaman."],[2,14,"Mutta jos sinä tahdot tehdä uutisesta ruokauhrin Herralle, niin sinun pitää kuivaaman viheriäiset tähkäpäät tulella, ja survoman ne pieniksi, ja sitten uhraaman ruokauhrin sinun uutisestas.","Mutta jos sinä tahdot tehdä uutisesta ruokauhrin Herralle, niin sinun pitää kuivaaman viheriäiset tähkäpäät tulella, ja survoman ne pieniksi, ja sitten uhraaman ruokauhrin sinun uutisestas."],[2,15,"Ja sinun pitää paneman öljyä siihen ja pyhää savua, niin on se ruokauhri.","Ja sinun pitää paneman öljyä siihen ja pyhää savua, niin on se ruokauhri."],[2,16,"Ja papin pitää ottaman niistä survotuista jyvistä ja öljystä, ynnä kaiken pyhän savun kanssa, ja polttaman sen muistoksi. Se on tuliuhri Herralle.","Ja papin pitää ottaman niistä survotuista jyvistä ja öljystä, ynnä kaiken pyhän savun kanssa, ja polttaman sen muistoksi. Se on tuliuhri Herralle."],[3,1,"Ja jos hänen uhrinsa on kiitosuhri karjasta, niin pitää hänen uhraaman härjän eli lehmän, ja virheettömän uhrin tuoman Herran eteen.","Ja jos hänen uhrinsa on kiitosuhri karjasta, niin pitää hänen uhraaman härjän eli lehmän, ja virheettömän uhrin tuoman Herran eteen."],[3,2,"Ja pitää laskeman kätensä uhrinsa pään päälle, ja teurastaman seurakunnan majan oven edessä: ja papit Aaronin pojat pitää priiskottaman veren alttarille ympärinsä.","Ja pitää laskeman kätensä uhrinsa pään päälle, ja teurastaman seurakunnan majan oven edessä: ja papit Aaronin pojat pitää priiskottaman veren alttarille ympärinsä."],[3,3,"Ja pitää uhraaman siitä kiitosuhrista polttouhrin Herralle: lihavuuden, kuin sisällykset peittää, ja kaiken sisällysten lihavuuden,","Ja pitää uhraaman siitä kiitosuhrista polttouhrin Herralle: lihavuuden, kuin sisällykset peittää, ja kaiken sisällysten lihavuuden,"],[3,4,"Ja kaksi munaskuuta sen lihavuuden kanssa, kuin niiden päällä on lanteissa, ja maksan kalvon munaskuiden kanssa eroittaman.","Ja kaksi munaskuuta sen lihavuuden kanssa, kuin niiden päällä on lanteissa, ja maksan kalvon munaskuiden kanssa eroittaman."],[3,5,"Aaronin pojat pitää polttaman sen alttarilla polttouhriksi puiden päällä, jotka ovat tulessa, tuliuhriksi ja lepytyshajuksi Herralle.","Aaronin pojat pitää polttaman sen alttarilla polttouhriksi puiden päällä, jotka ovat tulessa, tuliuhriksi ja lepytyshajuksi Herralle."],[3,6,"Mutta jos hän tekee Herralle kiitosuhria pienistä eläimistä, oinaista eli uuhista, niin sen pitää oleman ilman virheetä.","Mutta jos hän tekee Herralle kiitosuhria pienistä eläimistä, oinaista eli uuhista, niin sen pitää oleman ilman virheetä."],[3,7,"Jos hän uhraa karitsan, niin hänen pitää sen tuoman Herran eteen,","Jos hän uhraa karitsan, niin hänen pitää sen tuoman Herran eteen,"],[3,8,"Ja pitää laskeman kätensä uhrinsa pään päälle, ja teurastaman sen seurakunnan majan oven edessä. Ja Aaronin pojat pitää priiskottaman sen veren alttarille ympärinsä,","Ja pitää laskeman kätensä uhrinsa pään päälle, ja teurastaman sen seurakunnan majan oven edessä. Ja Aaronin pojat pitää priiskottaman sen veren alttarille ympärinsä,"],[3,9,"Ja kiitosuhrista uhraaman Herralle polttouhrin, sen lihavuuden: koko saparon eroitetun selkäpiistä: lihavuuden, kuin sisällykset peittää, ja kaiken sisällysten lihavuuden,","Ja kiitosuhrista uhraaman Herralle polttouhrin, sen lihavuuden: koko saparon eroitetun selkäpiistä: lihavuuden, kuin sisällykset peittää, ja kaiken sisällysten lihavuuden,"],[3,10,"Ja kaksi munaskuuta sen lihavuuden kanssa kuin lanteissa niiden päällä on, ja eroittaman maksan kalvon munaskuiden kanssa.","Ja kaksi munaskuuta sen lihavuuden kanssa kuin lanteissa niiden päällä on, ja eroittaman maksan kalvon munaskuiden kanssa."],[3,11,"Ja papin pitää sen polttaman alttarilla, tulen ruaksi Herralle.","Ja papin pitää sen polttaman alttarilla, tulen ruaksi Herralle."],[3,12,"Jos hänen uhrinsa on vuohi ja hän tuo sen Herran eteen,","Jos hänen uhrinsa on vuohi ja hän tuo sen Herran eteen,"],[3,13,"Niin hänen pitää laskeman kätensä sen pään päälle, ja teurastaman seurakunnan majan oven edessä. Ja Aaronin pojat pitää priiskottaman hänen verensä alttarille ympärinsä,","Niin hänen pitää laskeman kätensä sen pään päälle, ja teurastaman seurakunnan majan oven edessä. Ja Aaronin pojat pitää priiskottaman hänen verensä alttarille ympärinsä,"],[3,14,"Ja pitää siitä uhraaman polttouhrin Herralle: lihavuuden, kuin sisällykset peittää, ja kaiken sisällysten lihavuuden.","Ja pitää siitä uhraaman polttouhrin Herralle: lihavuuden, kuin sisällykset peittää, ja kaiken sisällysten lihavuuden."],[3,15,"Ja kaksi munaskuuta lihavuuden kanssa, joka niiden päällä on lanteissa, ja maksan kalvon munaskuiden kanssa eroittaman.","Ja kaksi munaskuuta lihavuuden kanssa, joka niiden päällä on lanteissa, ja maksan kalvon munaskuiden kanssa eroittaman."],[3,16,"Ja papin pitää polttaman sen alttarilla, tulen ruaksi, makiaksi hajuksi. Kaikki lihavuus on Herran oma.","Ja papin pitää polttaman sen alttarilla, tulen ruaksi, makiaksi hajuksi. Kaikki lihavuus on Herran oma."],[3,17,"Sen pitää oleman ijankaikkisen säädyn teidän sukukunnissanne, kaikissa tiedän asuinsioissanne: ettette yhtään lihavuutta eli mitään verta söisi.","Sen pitää oleman ijankaikkisen säädyn teidän sukukunnissanne, kaikissa tiedän asuinsioissanne: ettette yhtään lihavuutta eli mitään verta söisi."],[4,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[4,2,"Puhu Israelin lapsille, ja sano: jos joku sielu rikkoo tietämätä jotakuta Herran käskyä vastaan, jota ei hänen pitäis tekemän, niin että hän tekis yhtäkin vastaan niistä:","Puhu Israelin lapsille, ja sano: jos joku sielu rikkoo tietämätä jotakuta Herran käskyä vastaan, jota ei hänen pitäis tekemän, niin että hän tekis yhtäkin vastaan niistä:"],[4,3,"Jos pappi, joka voideltu on, rikkoo kansan pahennukseksi, niin hänen pitää rikoksensa edestä, kuin hän tehnyt on, tuoman virheettömän nuoren mullin Herralle rikosuhriksi,","Jos pappi, joka voideltu on, rikkoo kansan pahennukseksi, niin hänen pitää rikoksensa edestä, kuin hän tehnyt on, tuoman virheettömän nuoren mullin Herralle rikosuhriksi,"],[4,4,"Ja pitää tuoman mullin Herran eteen, seurakunnan majan oven tykö, ja laskeman kätensä mullin pään päälle, ja teurastaman mullin Herran edessä.","Ja pitää tuoman mullin Herran eteen, seurakunnan majan oven tykö, ja laskeman kätensä mullin pään päälle, ja teurastaman mullin Herran edessä."],[4,5,"Ja pappi kuin voideltu on, pitää ottaman mullin verestä, ja kantaman seurakunnan majaan.","Ja pappi kuin voideltu on, pitää ottaman mullin verestä, ja kantaman seurakunnan majaan."],[4,6,"Ja papin pitää kastaman sormensa vereen ja priiskottaman sitä verta seitsemän kertaa Herran ja pyhän esiripun edessä.","Ja papin pitää kastaman sormensa vereen ja priiskottaman sitä verta seitsemän kertaa Herran ja pyhän esiripun edessä."],[4,7,"Ja papin pitää siitä verestä paneman suitsutusalttarin sarvein päälle, joka on Herran edessä seurakunnan majassa, ja kaiken muun veren kaataman polttouhrin alttarin pohjalle, joka on seurakunnan majan oven edessä.","Ja papin pitää siitä verestä paneman suitsutusalttarin sarvein päälle, joka on Herran edessä seurakunnan majassa, ja kaiken muun veren kaataman polttouhrin alttarin pohjalle, joka on seurakunnan majan oven edessä."],[4,8,"Ja kaiken rikosuhrin mullin lihavuuden pitää hänen ylentämän: nimittäin sen lihavuuden joka sisällykset peittää, ja kaiken sisällysten lihavuuden,","Ja kaiken rikosuhrin mullin lihavuuden pitää hänen ylentämän: nimittäin sen lihavuuden joka sisällykset peittää, ja kaiken sisällysten lihavuuden,"],[4,9,"Ja kaksi munaskuuta sen lihavuuden kanssa, joka niiden päällä on lanteissa, ja maksan kalvon munaskuiden kanssa eroittaman,","Ja kaksi munaskuuta sen lihavuuden kanssa, joka niiden päällä on lanteissa, ja maksan kalvon munaskuiden kanssa eroittaman,"],[4,10,"Niinkuin ylennetään kiitosuhri härjästä: ja papin pitää sen polttaman polttouhrialttarilla.","Niinkuin ylennetään kiitosuhri härjästä: ja papin pitää sen polttaman polttouhrialttarilla."],[4,11,"Mutta mullin vuodan, kaiken lihan, pään ja jalkain kanssa, ja sisällykset ja ravan,","Mutta mullin vuodan, kaiken lihan, pään ja jalkain kanssa, ja sisällykset ja ravan,"],[4,12,"Niin myös koko mullin pitää hänen leiristä viemän ulos puhtaaseen paikkaan, johonka tuhkat heitetään, ja se pitää poltettaman puiden päällä tulessa: juuri siinä paikassa, johon tuhka heitetään, pitää se poltettaman.","Niin myös koko mullin pitää hänen leiristä viemän ulos puhtaaseen paikkaan, johonka tuhkat heitetään, ja se pitää poltettaman puiden päällä tulessa: juuri siinä paikassa, johon tuhka heitetään, pitää se poltettaman."],[4,13,"Jos koko Israelin seurakunta eksyis, ja se olis heidän silmäinsä edessä peitetty, niin että he olisivat tehneet jotakuta Herran käskyä vastaan, jota ei heidän tulisi tehdä, ja niin tulisivat vikapääksi,","Jos koko Israelin seurakunta eksyis, ja se olis heidän silmäinsä edessä peitetty, niin että he olisivat tehneet jotakuta Herran käskyä vastaan, jota ei heidän tulisi tehdä, ja niin tulisivat vikapääksi,"],[4,14,"Ja sitte ymmärtäisivät rikoksensa, jonka he olivat tehneet, niin pitää heidän tuoman nuoren mullin rikosuhriksi, ja asettaman sen seurakunnan majan eteen.","Ja sitte ymmärtäisivät rikoksensa, jonka he olivat tehneet, niin pitää heidän tuoman nuoren mullin rikosuhriksi, ja asettaman sen seurakunnan majan eteen."],[4,15,"Ja seurakunnan vanhimmat pitää laskeman kätensä mullin pään päälle Herran edessä, ja teurastaman mullin Herran edessä.","Ja seurakunnan vanhimmat pitää laskeman kätensä mullin pään päälle Herran edessä, ja teurastaman mullin Herran edessä."],[4,16,"Ja pappi, joka voideltu on, pitää kantaman mullin veren seurakunnan majaan.","Ja pappi, joka voideltu on, pitää kantaman mullin veren seurakunnan majaan."],[4,17,"Ja papin pitää kastaman sormensa vereen ja seitsemän kertaa priiskottaman Herran eteen, esiripun edessä,","Ja papin pitää kastaman sormensa vereen ja seitsemän kertaa priiskottaman Herran eteen, esiripun edessä,"],[4,18,"Ja pitää siitä verestä paneman altarin sarvein päälle, joka on Herran edessä seurakunnan majassa, ja kaiken sen muun veren kaataman polttouhrin alttarin pohjaan, joka on seurakunnan majan edessä.","Ja pitää siitä verestä paneman altarin sarvein päälle, joka on Herran edessä seurakunnan majassa, ja kaiken sen muun veren kaataman polttouhrin alttarin pohjaan, joka on seurakunnan majan edessä."],[4,19,"Kaiken hänen lihavuutensa pitää hänen ylentämän ja polttaman alttarilla,","Kaiken hänen lihavuutensa pitää hänen ylentämän ja polttaman alttarilla,"],[4,20,"Ja pitää tekemän tämän mullin kanssa niinkuin hän teki rikosuhrin mullin kanssa: ja niin pitää papin heidät sovittaman, ja se heille annetaan anteeksi.","Ja pitää tekemän tämän mullin kanssa niinkuin hän teki rikosuhrin mullin kanssa: ja niin pitää papin heidät sovittaman, ja se heille annetaan anteeksi."],[4,21,"Ja hänen pitää viemän mullin leiristä ulos, ja polttaman hänen, niinkuin hän poltti sen entisen mullin: sen pitää oleman rikosuhri seurakunnan edestä.","Ja hänen pitää viemän mullin leiristä ulos, ja polttaman hänen, niinkuin hän poltti sen entisen mullin: sen pitää oleman rikosuhri seurakunnan edestä."],[4,22,"Mutta jos päämies rikkoo ja tekee jotakuta Herran Jumalansa käskyä vastaan, jota ei hänen tekemän pitäisi, ja tulee tietämätä vikapääksi,","Mutta jos päämies rikkoo ja tekee jotakuta Herran Jumalansa käskyä vastaan, jota ei hänen tekemän pitäisi, ja tulee tietämätä vikapääksi,"],[4,23,"Ja osotetaan hänelle sitte hänen rikoksensa, jolla hän on rikkonut: hänen pitää tuoman uhriksi virheettömän kauriin.","Ja osotetaan hänelle sitte hänen rikoksensa, jolla hän on rikkonut: hänen pitää tuoman uhriksi virheettömän kauriin."],[4,24,"Ja laskeman kätensä kauriin pään päälle, ja teurastaman siinä paikassa, kussa Herralle polttouhria teurastetaan: se pitää oleman hänen rikosuhrinsa.","Ja laskeman kätensä kauriin pään päälle, ja teurastaman siinä paikassa, kussa Herralle polttouhria teurastetaan: se pitää oleman hänen rikosuhrinsa."],[4,25,"Sitte pitää papin ottaman rikosuhrin verta sormellansa, ja paneman sen polttouhrin alttarin sarvein päälle, ja sen muun veren kaataman polttouhrin alttarin pohjalle.","Sitte pitää papin ottaman rikosuhrin verta sormellansa, ja paneman sen polttouhrin alttarin sarvein päälle, ja sen muun veren kaataman polttouhrin alttarin pohjalle."],[4,26,"Mutta kaiken hänen lihavuutensa pitää hänen polttaman alttarilla, niinkuin sen lihavuuden kiitosuhrista. Ja niin papin pitää sovittaman hänen rikoksensa, ja se hänelle annetaan anteeksi.","Mutta kaiken hänen lihavuutensa pitää hänen polttaman alttarilla, niinkuin sen lihavuuden kiitosuhrista. Ja niin papin pitää sovittaman hänen rikoksensa, ja se hänelle annetaan anteeksi."],[4,27,"Jos joku sielu yhteisestä kansasta rikkoo tietämätä, niin että hän tekee jotakuta Herran käskyä vastaan, jota ei hänen tekemän pitäis, ja tulee niin vikapääksi,","Jos joku sielu yhteisestä kansasta rikkoo tietämätä, niin että hän tekee jotakuta Herran käskyä vastaan, jota ei hänen tekemän pitäis, ja tulee niin vikapääksi,"],[4,28,"Ja sitte saatetaan ymmärtämään rikoksensa, jolla hän on rikkonut: hänen pitää tuoman uhriksi virheettömän vuohen, sen rikoksen edestä, jolla hän rikkonut on,","Ja sitte saatetaan ymmärtämään rikoksensa, jolla hän on rikkonut: hänen pitää tuoman uhriksi virheettömän vuohen, sen rikoksen edestä, jolla hän rikkonut on,"],[4,29,"Ja pitää laskeman kätensä rikosuhrin pään päälle ja teurastaman sen rikosuhrin polttouhrin paikalla.","Ja pitää laskeman kätensä rikosuhrin pään päälle ja teurastaman sen rikosuhrin polttouhrin paikalla."],[4,30,"Ja papin pitää sormellansa ottaman sen verta, ja paneman sen polttouhrin alttarin sarvein päälle, ja kaiken veren kaataman altarin pohjaan.","Ja papin pitää sormellansa ottaman sen verta, ja paneman sen polttouhrin alttarin sarvein päälle, ja kaiken veren kaataman altarin pohjaan."],[4,31,"Ja kaiken hänen lihavuutensa pitää hänen eroittaman, niinkuin hän eroitti kiitosuhrin lihavuuden: ja papin pitää sen polttaman alttarilla makiaksi hajuksi Herralle. Ja niin pitää papin häntä sovittaman, ja se annetaan anteeksi hänelle.","Ja kaiken hänen lihavuutensa pitää hänen eroittaman, niinkuin hän eroitti kiitosuhrin lihavuuden: ja papin pitää sen polttaman alttarilla makiaksi hajuksi Herralle. Ja niin pitää papin häntä sovittaman, ja se annetaan anteeksi hänelle."],[4,32,"Mutta jos hän tuo lampaansa rikosuhriksi, niin tuokaan virheettömän uuhen.","Mutta jos hän tuo lampaansa rikosuhriksi, niin tuokaan virheettömän uuhen."],[4,33,"Ja laskekaan kätensä rikosuhrin pään päälle ja teurastakaan sen rikosuhriksi siinä paikassa, missä polttouhri teurastetaan.","Ja laskekaan kätensä rikosuhrin pään päälle ja teurastakaan sen rikosuhriksi siinä paikassa, missä polttouhri teurastetaan."],[4,34,"Ja papin pitää sormellansa ottaman rikosuhrin verta, ja paneman polttouhrin alttarin sarvein päälle, ja kaataman kaiken muun veren alttarin pohjaan.","Ja papin pitää sormellansa ottaman rikosuhrin verta, ja paneman polttouhrin alttarin sarvein päälle, ja kaataman kaiken muun veren alttarin pohjaan."],[4,35,"Mutta kaiken lihavuuden pitää hänen eroittaman niinkuin kiitosuhrin lampaan lihavuus eroitettiin, ja papin pitää polttaman sen alttarilla Herran tuleksi. Ja niin pitää papin hänen rikoksensa sovittaman, jolla hän on rikkonut, ja se hänelle annetaan anteeksi.","Mutta kaiken lihavuuden pitää hänen eroittaman niinkuin kiitosuhrin lampaan lihavuus eroitettiin, ja papin pitää polttaman sen alttarilla Herran tuleksi. Ja niin pitää papin hänen rikoksensa sovittaman, jolla hän on rikkonut, ja se hänelle annetaan anteeksi."],[5,1,"Jos joku sielu rikkoo, niin että hän kuulee jonkun kiroilevan, ja hän on sen todistaja, eli on sen nähnyt taikka tietänyt, ja ei ilmoita siitä, hän on vikapää vääryyteen.","Jos joku sielu rikkoo, niin että hän kuulee jonkun kiroilevan, ja hän on sen todistaja, eli on sen nähnyt taikka tietänyt, ja ei ilmoita siitä, hän on vikapää vääryyteen."],[5,2,"Eli jos joku sielu rupee johonkuhun saastaiseen kappaleeseen, taikka saastaisen metsän eläimen raatoon, eli saastaisen karjan raatoon eli saastaisen madon raatoon, ja se olis hänelle tietämätöin: hän on saastainen ja vikapää.","Eli jos joku sielu rupee johonkuhun saastaiseen kappaleeseen, taikka saastaisen metsän eläimen raatoon, eli saastaisen karjan raatoon eli saastaisen madon raatoon, ja se olis hänelle tietämätöin: hän on saastainen ja vikapää."],[5,3,"Eli jos hän rupee saastaiseen ihmiseen, millä ikänänsä saastaisuudella ihminen taitaa saastaiseksi tulla, tietämätä, ja sen sitte ymmärtää, se on vikapää.","Eli jos hän rupee saastaiseen ihmiseen, millä ikänänsä saastaisuudella ihminen taitaa saastaiseksi tulla, tietämätä, ja sen sitte ymmärtää, se on vikapää."],[5,4,"Eli jos joku sielu vannoo, niin että hänen suustansa käy ajattelemata pahoin eli hyvin tehdä, kaikki kuin ihminen vannoo huomaitsemata, ja sen sitte ymmärtää: hän on vikapää yhteen näistä.","Eli jos joku sielu vannoo, niin että hänen suustansa käy ajattelemata pahoin eli hyvin tehdä, kaikki kuin ihminen vannoo huomaitsemata, ja sen sitte ymmärtää: hän on vikapää yhteen näistä."],[5,5,"Koska hän on vikapää johonkuhun näistä, ja tunnustaa, että hän siinä rikkonut on:","Koska hän on vikapää johonkuhun näistä, ja tunnustaa, että hän siinä rikkonut on:"],[5,6,"Niin pitää hänen tämän rikoksensa vian edestä, kuin hän rikkonut on, tuoman laumasta Herralle uuhen eli vuohen rikosuhriksi: niin pitää papin sovittaman hänen rikoksensa.","Niin pitää hänen tämän rikoksensa vian edestä, kuin hän rikkonut on, tuoman laumasta Herralle uuhen eli vuohen rikosuhriksi: niin pitää papin sovittaman hänen rikoksensa."],[5,7,"Jollei hänellä ole lammasta, niin tuokaan Herralle rikoksensa edestä, jolla hän rikkonut on, kaksi mettistä eli kaksi kyhkyläisen poikaa: yhden rikosuhriksi, ja toisen polttouhriksi.","Jollei hänellä ole lammasta, niin tuokaan Herralle rikoksensa edestä, jolla hän rikkonut on, kaksi mettistä eli kaksi kyhkyläisen poikaa: yhden rikosuhriksi, ja toisen polttouhriksi."],[5,8,"Ja viekään ne papille: hänen pitää sen ensimäisen uhraaman rikosuhriksi ja vääntämän sen niskat ja ei kuitenkaan päätä erinänsä repäisemän,","Ja viekään ne papille: hänen pitää sen ensimäisen uhraaman rikosuhriksi ja vääntämän sen niskat ja ei kuitenkaan päätä erinänsä repäisemän,"],[5,9,"Ja pitää priiskottaman alttarin seinän rikosuhrin verellä, ja antaman sen veren, joka jää, vuotaa alttarin pohjaan. Se on rikosuhri.","Ja pitää priiskottaman alttarin seinän rikosuhrin verellä, ja antaman sen veren, joka jää, vuotaa alttarin pohjaan. Se on rikosuhri."],[5,10,"Toisen pitää hänen uhraaman polttouhriksi tavan jälkeen. Ja niin pitää papin sovittaman hänen rikoksensa, jolla hän rikkonut on, ja se annetaan hänelle anteeksi.","Toisen pitää hänen uhraaman polttouhriksi tavan jälkeen. Ja niin pitää papin sovittaman hänen rikoksensa, jolla hän rikkonut on, ja se annetaan hänelle anteeksi."],[5,11,"Jollei hänelle ole kahta mettistä eli kahta kyhkyläisen poikaa, niin tuokaan uhrinsa, rikoksensa edestä, kymmenennen osan ephaa sämpyläjauhoja rikosuhriksi. Mutta ei hänen pidä öljyä sen päälle paneman, eikä pyhää savua; sillä se on rikosuhri.","Jollei hänelle ole kahta mettistä eli kahta kyhkyläisen poikaa, niin tuokaan uhrinsa, rikoksensa edestä, kymmenennen osan ephaa sämpyläjauhoja rikosuhriksi. Mutta ei hänen pidä öljyä sen päälle paneman, eikä pyhää savua; sillä se on rikosuhri."],[5,12,"Ja hänen pitää sen viemän papille, ja papin pitää siitä ottaman pivon täyden muistoksi, ja polttaman sen alttarilla Herralle tuliuhriksi: tämä on rikosuhri.","Ja hänen pitää sen viemän papille, ja papin pitää siitä ottaman pivon täyden muistoksi, ja polttaman sen alttarilla Herralle tuliuhriksi: tämä on rikosuhri."],[5,13,"Ja papin pitää niin sovittaman hänelle hänen rikoksensa, jolla hän rikkonut on, ja se annetaan anteeksi hänelle. Ja sen pitää oleman papin oman niinkuin ruokauhrinkin.","Ja papin pitää niin sovittaman hänelle hänen rikoksensa, jolla hän rikkonut on, ja se annetaan anteeksi hänelle. Ja sen pitää oleman papin oman niinkuin ruokauhrinkin."],[5,14,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[5,15,"Jos joku sielu kovasti rikkoo ja erehdyksestä syntiä tekee jossakussa joka Herralle pyhitetty on, hänen pitää Herralle tuoman vikauhrin, virheettömän oinaan laumasta, sinun arvios jälkeen hopiapainoon, pyhän siklin jälkee, vikauhriksi.","Jos joku sielu kovasti rikkoo ja erehdyksestä syntiä tekee jossakussa joka Herralle pyhitetty on, hänen pitää Herralle tuoman vikauhrin, virheettömän oinaan laumasta, sinun arvios jälkeen hopiapainoon, pyhän siklin jälkee, vikauhriksi."],[5,16,"Siihen myös, mitä hän on rikkonut pyhitetyssä, pitää hänen sen antaman jällensä, ja pitää sen tykö antaman viidennen osan, ja antaman sen papille: ja papin pitää sovittaman hänen vikauhrin oinaalla, niin se hänelle annetaan anteeksi.","Siihen myös, mitä hän on rikkonut pyhitetyssä, pitää hänen sen antaman jällensä, ja pitää sen tykö antaman viidennen osan, ja antaman sen papille: ja papin pitää sovittaman hänen vikauhrin oinaalla, niin se hänelle annetaan anteeksi."],[5,17,"Ja jos joku sielu rikkoo ja tekee vastoin jotakuta Herran käskyä, jota ei hänen pitänyt tekemän, ja ei sitä tietänyt: hän on vikapää vääryyteen,","Ja jos joku sielu rikkoo ja tekee vastoin jotakuta Herran käskyä, jota ei hänen pitänyt tekemän, ja ei sitä tietänyt: hän on vikapää vääryyteen,"],[5,18,"Ja pitää tuoman papille virheettömän oinaan laumasta, sinun arvios jälkeen vikauhriksi: ja papin pitää sovittaman hänelle hänen tietämättömyytensä, kun hän tehnyt on tietämätä, niin se hänelle annetaan anteeksi.","Ja pitää tuoman papille virheettömän oinaan laumasta, sinun arvios jälkeen vikauhriksi: ja papin pitää sovittaman hänelle hänen tietämättömyytensä, kun hän tehnyt on tietämätä, niin se hänelle annetaan anteeksi."],[5,19,"Se on vikauhri: sillä vikaan hän kaiketikin Herran edessä joutunut on.","Se on vikauhri: sillä vikaan hän kaiketikin Herran edessä joutunut on."],[6,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[6,2,"Jos joku sielu tekee syntiä ja rikkoo kovasti Herraa vastaan, kieltäen lähimmäiseltänsä sen, minkä hän hänen haltuunsa antanut on, eli sen, jonka hän hänelle (muutoin) käteen antanut on, taikka jonka hän väkivallalla ottanut on, eli vääryydellä on saattanut allensa:","Jos joku sielu tekee syntiä ja rikkoo kovasti Herraa vastaan, kieltäen lähimmäiseltänsä sen, minkä hän hänen haltuunsa antanut on, eli sen, jonka hän hänelle (muutoin) käteen antanut on, taikka jonka hän väkivallalla ottanut on, eli vääryydellä on saattanut allensa:"],[6,3,"Eli sen joka kadotettu oli, löytänyt on, ja kieltää sen väärällä valalla, eli mikä ikänänsä se olis, jossa ihminen lähimmäistänsä vastaan rikkoo;","Eli sen joka kadotettu oli, löytänyt on, ja kieltää sen väärällä valalla, eli mikä ikänänsä se olis, jossa ihminen lähimmäistänsä vastaan rikkoo;"],[6,4,"Koska hän niin rikkoo ja tulee vikapääksi, niin pitää hänen antaman jällensä, mitä hän väkivallalla ottanut on ja vääryydellä on saattanut allensa eli sen mikä hänen haltuunsa annettu oli, eli kadotetun kuin hän löytänyt on,","Koska hän niin rikkoo ja tulee vikapääksi, niin pitää hänen antaman jällensä, mitä hän väkivallalla ottanut on ja vääryydellä on saattanut allensa eli sen mikä hänen haltuunsa annettu oli, eli kadotetun kuin hän löytänyt on,"],[6,5,"Eli jonka tähden hän väärän valan tehnyt on, sen pitää hänen kaikki tyynni antaman jällensä ja vielä sitte viidennen osan päälliseksi: sille, jonka se oma oli, pitää hänen sen antaman vikauhrinsa päivänä.","Eli jonka tähden hän väärän valan tehnyt on, sen pitää hänen kaikki tyynni antaman jällensä ja vielä sitte viidennen osan päälliseksi: sille, jonka se oma oli, pitää hänen sen antaman vikauhrinsa päivänä."],[6,6,"Mutta vikauhrinsa pitää hänen tuoman Herralle: virheettömän oinaan laumasta, sinun arvios jälkeen vikauhriksi, papin tykö.","Mutta vikauhrinsa pitää hänen tuoman Herralle: virheettömän oinaan laumasta, sinun arvios jälkeen vikauhriksi, papin tykö."],[6,7,"Ja papin pitää sovittaman hänen Herran edessä, niin hänelle annetaan anteeksi, mitä ikänänsä se olis, kaikista niistä mitä hän tehnyt on, jossa hän itsensä vikapääksi saatti.","Ja papin pitää sovittaman hänen Herran edessä, niin hänelle annetaan anteeksi, mitä ikänänsä se olis, kaikista niistä mitä hän tehnyt on, jossa hän itsensä vikapääksi saatti."],[6,8,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[6,9,"Käske Aaronille ja hänen pojillensa sanoen: tämä on polttouhrin sääty: polttouhrin pitää palaman alttarilla kaiken yötä aamuun asti. Ja alttarilla tulen pitää sen päällä palaman.","Käske Aaronille ja hänen pojillensa sanoen: tämä on polttouhrin sääty: polttouhrin pitää palaman alttarilla kaiken yötä aamuun asti. Ja alttarilla tulen pitää sen päällä palaman."],[6,10,"Ja papin pitää yllensä pukeman liinahameen, ja vetämän liinaisen alusvaatteen ihonsa päälle, ja korjaaman tuhan alttarilta, sitte kuin tuli polttouhrin kuluttanut on, ja paneman sen alttarin viereen.","Ja papin pitää yllensä pukeman liinahameen, ja vetämän liinaisen alusvaatteen ihonsa päälle, ja korjaaman tuhan alttarilta, sitte kuin tuli polttouhrin kuluttanut on, ja paneman sen alttarin viereen."],[6,11,"Ja sitte pitää riisuman vaatteensa, ja toisiin vaatteisiin itsensä pukeman, ja sitte tuhan viemän ulos leiristä puhtaaseen paikkaan.","Ja sitte pitää riisuman vaatteensa, ja toisiin vaatteisiin itsensä pukeman, ja sitte tuhan viemän ulos leiristä puhtaaseen paikkaan."],[6,12,"Tuli pitää palaman alttarilla, ja ei koskaan sammuman. Ja papin pitää halot sen päällä joka aamu sytyttämän, ja hänen pitää asettaman polttouhrin sen päälle, ja polttaman kiitosuhrin lihavuuden sen päällä.","Tuli pitää palaman alttarilla, ja ei koskaan sammuman. Ja papin pitää halot sen päällä joka aamu sytyttämän, ja hänen pitää asettaman polttouhrin sen päälle, ja polttaman kiitosuhrin lihavuuden sen päällä."],[6,13,"Tuli pitää alinomaa palaman alttarilla, ja ei koskaan sammutettaman.","Tuli pitää alinomaa palaman alttarilla, ja ei koskaan sammutettaman."],[6,14,"Ja tämä on ruokauhrin sääty, jonka Aaronin pojat uhraaman pitää alttarilla, Herran eteen:","Ja tämä on ruokauhrin sääty, jonka Aaronin pojat uhraaman pitää alttarilla, Herran eteen:"],[6,15,"Papin pitää ottaman pivon täyden sämpyläjauhoja ruokauhrista, ja öljystä, ja kaiken pyhän savun, joka ruokauhrin päällä on, ja sen polttaman alttarilla lepytyshajuksi ja muistoksi Herralle.","Papin pitää ottaman pivon täyden sämpyläjauhoja ruokauhrista, ja öljystä, ja kaiken pyhän savun, joka ruokauhrin päällä on, ja sen polttaman alttarilla lepytyshajuksi ja muistoksi Herralle."],[6,16,"Ja sen tähteet pitää Aaronin poikinensa syömän: happamatoinna pitää se syötämän, pyhässä siassa, seurakunnan majan pihassa pitää heidän sen syömän.","Ja sen tähteet pitää Aaronin poikinensa syömän: happamatoinna pitää se syötämän, pyhässä siassa, seurakunnan majan pihassa pitää heidän sen syömän."],[6,17,"Ja ei heidän pidä leipoman sitä hapatuksen kanssa; sillä se on heidän osansa, jonka minä heille minun tuliuhristani antanut olen: se pitää oleman kaikkein pyhin, niinkuin rikosuhri ja niinkuin vikauhri.","Ja ei heidän pidä leipoman sitä hapatuksen kanssa; sillä se on heidän osansa, jonka minä heille minun tuliuhristani antanut olen: se pitää oleman kaikkein pyhin, niinkuin rikosuhri ja niinkuin vikauhri."],[6,18,"Jokainen miehenpuoli Aaronin lapsista pitää sen syömän. Se olkoon alinomainen sääty teidän sukukunnissanne Herran tuliuhrista. Jokainen kuin niihin rupee, se pitää pyhitetty oleman.","Jokainen miehenpuoli Aaronin lapsista pitää sen syömän. Se olkoon alinomainen sääty teidän sukukunnissanne Herran tuliuhrista. Jokainen kuin niihin rupee, se pitää pyhitetty oleman."],[6,19,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[6,20,"Tämän pitää oleman Aaronin ja hänen poikainsa uhri, jonka heidän pitää uhraaman Herralle voidelluspäivänänsä: kymmenennen osan ephaa sämpyläjauhoja alinomaiseksi ruokauhriksi, puolen aamulla ja puolen ehtoolla.","Tämän pitää oleman Aaronin ja hänen poikainsa uhri, jonka heidän pitää uhraaman Herralle voidelluspäivänänsä: kymmenennen osan ephaa sämpyläjauhoja alinomaiseksi ruokauhriksi, puolen aamulla ja puolen ehtoolla."],[6,21,"Pannussa sinun sen tekemän pitää öljyn kanssa, ja sen kypsettynä tuoman: ja leivottuina kappaleina sinun sen uhraaman pitää, lepytyshajuksi Herralle.","Pannussa sinun sen tekemän pitää öljyn kanssa, ja sen kypsettynä tuoman: ja leivottuina kappaleina sinun sen uhraaman pitää, lepytyshajuksi Herralle."],[6,22,"Ja papin, joka hänen pojistansa hänen siaansa voideltu on, pitää sen tekemän. Tämä on ijankaikkinen sääty Herralle, se pitää kaikki poltettaman.","Ja papin, joka hänen pojistansa hänen siaansa voideltu on, pitää sen tekemän. Tämä on ijankaikkinen sääty Herralle, se pitää kaikki poltettaman."],[6,23,"Sillä kaikki papin ruokauhri pitää kokonansa poltettaman, ei sitä pidä syötämän.","Sillä kaikki papin ruokauhri pitää kokonansa poltettaman, ei sitä pidä syötämän."],[6,24,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[6,25,"Puhu Aaronille ja hänen pojillensa, ja sano: tämä on rikosuhrin sääty: kussa paikassa polttouhri teurastetaan, siinä pitää myös rikosuhri teurastettaman Herran edessä, ja se on kaikkein pyhin.","Puhu Aaronille ja hänen pojillensa, ja sano: tämä on rikosuhrin sääty: kussa paikassa polttouhri teurastetaan, siinä pitää myös rikosuhri teurastettaman Herran edessä, ja se on kaikkein pyhin."],[6,26,"Pappi, joka rikosuhria uhraa, pitää sen syömän: pyhällä sialla sen syötämän pitää, seurakunnan majan pihalla.","Pappi, joka rikosuhria uhraa, pitää sen syömän: pyhällä sialla sen syötämän pitää, seurakunnan majan pihalla."],[6,27,"Kuka ikänänsä hänen lihaansa rupee, se pitää pyhitetty oleman, ja vaatteen, jonka päälle se veri priiskotetaan, pitää sinun pesemän pyhässä siassa.","Kuka ikänänsä hänen lihaansa rupee, se pitää pyhitetty oleman, ja vaatteen, jonka päälle se veri priiskotetaan, pitää sinun pesemän pyhässä siassa."],[6,28,"Ja se saviastia, jossa se keitetään, pitää rikottaman. Jos se on vaskisessa padassa keitetty, niin se pitää hivutettaman, ja vedellä virutettaman.","Ja se saviastia, jossa se keitetään, pitää rikottaman. Jos se on vaskisessa padassa keitetty, niin se pitää hivutettaman, ja vedellä virutettaman."],[6,29,"Kaikki miehenpuolet papeista pitää syömän sen; sillä se on kaikkein pyhin.","Kaikki miehenpuolet papeista pitää syömän sen; sillä se on kaikkein pyhin."],[6,30,"Mutta kaikki se rikosuhri, jonka veri viedään seurakunnan majaan, sovinnoksi pyhään siaan, sitä ei pidä syötämän, vaan tulella poltettaman.","Mutta kaikki se rikosuhri, jonka veri viedään seurakunnan majaan, sovinnoksi pyhään siaan, sitä ei pidä syötämän, vaan tulella poltettaman."],[7,1,"Ja tämä on vikauhrin sääty: se on kaikkein pyhin.","Ja tämä on vikauhrin sääty: se on kaikkein pyhin."],[7,2,"Siinä paikassa, kussa polttouhri teurastetaan, pitää myös teurastettaman vikauhri, ja sen veri pitää priiskotettaman alttarille ympärinsä.","Siinä paikassa, kussa polttouhri teurastetaan, pitää myös teurastettaman vikauhri, ja sen veri pitää priiskotettaman alttarille ympärinsä."],[7,3,"Ja kaikki sen lihavuus pitää uhrattaman, sekä häntä että lihavuus, joka sisällykset peittää.","Ja kaikki sen lihavuus pitää uhrattaman, sekä häntä että lihavuus, joka sisällykset peittää."],[7,4,"Ja ne kaksi munaskuuta sen lihavuuden kanssa, joka niiden päällä on lanteissa: ja maksan kalvon munaskuiden kanssa pitää hänen eroittaman.","Ja ne kaksi munaskuuta sen lihavuuden kanssa, joka niiden päällä on lanteissa: ja maksan kalvon munaskuiden kanssa pitää hänen eroittaman."],[7,5,"Niin pitää papin sen polttaman alttarilla tuliuhriksi Herralle; se on vikauhri.","Niin pitää papin sen polttaman alttarilla tuliuhriksi Herralle; se on vikauhri."],[7,6,"Jokainen miehenpuoli papeista pitää syömän sen; pyhässä siassa pitää se syötämän; sillä se on kaikkein pyhin.","Jokainen miehenpuoli papeista pitää syömän sen; pyhässä siassa pitää se syötämän; sillä se on kaikkein pyhin."],[7,7,"Niinkuin rikosuhri on, niin pitää myös vikauhrin oleman; sillä yhtäläinen pitää heidän molempain säätynsä oleman: ja se pitää sen papin oma oleman, joka sillä sovittaa.","Niinkuin rikosuhri on, niin pitää myös vikauhrin oleman; sillä yhtäläinen pitää heidän molempain säätynsä oleman: ja se pitää sen papin oma oleman, joka sillä sovittaa."],[7,8,"Sen papin, joka polttouhrin uhraa, pitää polttouhrin vuota oma oleman, jonka hän uhrannut on.","Sen papin, joka polttouhrin uhraa, pitää polttouhrin vuota oma oleman, jonka hän uhrannut on."],[7,9,"Ja kaikkinainen ruokauhri, joka pätsissä kypsetty on, ja kaikki kuin pannussa eli halstarilla valmistettu on, sen pitää papin oman oleman, joka sen uhraa.","Ja kaikkinainen ruokauhri, joka pätsissä kypsetty on, ja kaikki kuin pannussa eli halstarilla valmistettu on, sen pitää papin oman oleman, joka sen uhraa."],[7,10,"Ja kaikkinainen ruokauhri, joka öljyllä sekoitettu, taikka kuiva on, sen pitää kaikkein Aaronin lasten oman oleman, yhden niinkuin toisenkin.","Ja kaikkinainen ruokauhri, joka öljyllä sekoitettu, taikka kuiva on, sen pitää kaikkein Aaronin lasten oman oleman, yhden niinkuin toisenkin."],[7,11,"Ja tämä on kiitosuhrin sääty, joka Herralle uhrataan:","Ja tämä on kiitosuhrin sääty, joka Herralle uhrataan:"],[7,12,"Jos he tahtovat tehdä ylistysuhria, niin heidän pitää uhraaman ylistysuhrin sivussa happamattomia leipiä, sekoitettuja öljyllä, ja happamattomia ohukaisia kyrsiä, voidelluita öljyllä, ja pannussa kypsetyitä sämpyläleipiä sekoitettuja öljyllä.","Jos he tahtovat tehdä ylistysuhria, niin heidän pitää uhraaman ylistysuhrin sivussa happamattomia leipiä, sekoitettuja öljyllä, ja happamattomia ohukaisia kyrsiä, voidelluita öljyllä, ja pannussa kypsetyitä sämpyläleipiä sekoitettuja öljyllä."],[7,13,"Mutta senkaltaisia uhreja pitää heidän tekemän hapanneen kyrsän päälle, heidän kiitosuhrinsa ylistysuhriksi.","Mutta senkaltaisia uhreja pitää heidän tekemän hapanneen kyrsän päälle, heidän kiitosuhrinsa ylistysuhriksi."],[7,14,"Ja yksi kaikista niistä pitää uhrattaman Herralle ylennysuhriksi, ja sen pitää papin oman oleman, joka priiskottaa kiitosuhrin vereen.","Ja yksi kaikista niistä pitää uhrattaman Herralle ylennysuhriksi, ja sen pitää papin oman oleman, joka priiskottaa kiitosuhrin vereen."],[7,15,"Ja ylistysuhrin liha hänen kiitosuhrissansa pitää sinä päivänä syötämän, jona se uhrattu on, ja ei mitään pidä tähteeksi jätettämän huomeneksi.","Ja ylistysuhrin liha hänen kiitosuhrissansa pitää sinä päivänä syötämän, jona se uhrattu on, ja ei mitään pidä tähteeksi jätettämän huomeneksi."],[7,16,"Mutta jos joku lupauksesta taikka hyvästä tahdosta uhraa, niin se pitää sinä päivänä syötämän, jona se uhrattu on; mutta jos jotakin tähteeksi jää uhrista toiseksi päiväksi, niin pitää se myös syötämän.","Mutta jos joku lupauksesta taikka hyvästä tahdosta uhraa, niin se pitää sinä päivänä syötämän, jona se uhrattu on; mutta jos jotakin tähteeksi jää uhrista toiseksi päiväksi, niin pitää se myös syötämän."],[7,17,"Mutta se mikä tähteeksi jää siitä uhrin lihasta, niin se kolmantena päivänä pitää poltettaman tulessa.","Mutta se mikä tähteeksi jää siitä uhrin lihasta, niin se kolmantena päivänä pitää poltettaman tulessa."],[7,18,"Mutta jos joku syö kolmantena päivänä siitä uhratusta lihasta, joka on hänen kiitosuhristansa, niin ei ole hän otollinen, joka sen on uhrannut, eikä se hänelle pidä luettaman, mutta se on kauhistus; ja jokainen sielu, joka sitä syö, on vikapää pahaan tekoon.","Mutta jos joku syö kolmantena päivänä siitä uhratusta lihasta, joka on hänen kiitosuhristansa, niin ei ole hän otollinen, joka sen on uhrannut, eikä se hänelle pidä luettaman, mutta se on kauhistus; ja jokainen sielu, joka sitä syö, on vikapää pahaan tekoon."],[7,19,"Mutta se liha, joka sattuu johonkuhun saastaisuuteen, ei pidä syötämän, mutta tulessa poltettaman. Joka puhdas on, se pitää syömän lihasta.","Mutta se liha, joka sattuu johonkuhun saastaisuuteen, ei pidä syötämän, mutta tulessa poltettaman. Joka puhdas on, se pitää syömän lihasta."],[7,20,"Ja se sielu, joka syö kiitosuhrin lihasta, siitä mikä Herran oma on, ja hänen saastaisuutensa on hänen päällänsä, se sielu pitää hävitettämän kansoistansa.","Ja se sielu, joka syö kiitosuhrin lihasta, siitä mikä Herran oma on, ja hänen saastaisuutensa on hänen päällänsä, se sielu pitää hävitettämän kansoistansa."],[7,21,"Jos joku sielu rupee johonkuhun saastaisuuteen, olkoon se saastainen ihminen eli saastainen eläin eli joku muu saastainen kauhistus, ja syö kiitosuhrin lihasta siitä mikä Herran oma on, se pitää hävitettämän kansoistansa.","Jos joku sielu rupee johonkuhun saastaisuuteen, olkoon se saastainen ihminen eli saastainen eläin eli joku muu saastainen kauhistus, ja syö kiitosuhrin lihasta siitä mikä Herran oma on, se pitää hävitettämän kansoistansa."],[7,22,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[7,23,"Puhu Israelin lapsille, sanoen: ei teidän pidä mitään lihavuutta syömän härjistä, lampaista ja vuohista.","Puhu Israelin lapsille, sanoen: ei teidän pidä mitään lihavuutta syömän härjistä, lampaista ja vuohista."],[7,24,"Raadon eli haaskan lihavuus pantakoon kaikkinaisiin tarpeisiin: mutta ei teidän pidä sitä kaiketikaan syömän.","Raadon eli haaskan lihavuus pantakoon kaikkinaisiin tarpeisiin: mutta ei teidän pidä sitä kaiketikaan syömän."],[7,25,"Sillä joka syö lihavuutta siitä eläimestä, joka Herralle tuliuhriksi annettu on, se sielu pitää hävitettämän kansoistansa.","Sillä joka syö lihavuutta siitä eläimestä, joka Herralle tuliuhriksi annettu on, se sielu pitää hävitettämän kansoistansa."],[7,26,"Ei teidän pidä myös verta syömän kaikissa teidän asumasioissanne, ei linnuista, eikä eläimistä.","Ei teidän pidä myös verta syömän kaikissa teidän asumasioissanne, ei linnuista, eikä eläimistä."],[7,27,"Jokainen sielu, joka syö jotain verta, se pitää hävitettämän kansoistansa.","Jokainen sielu, joka syö jotain verta, se pitää hävitettämän kansoistansa."],[7,28,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[7,29,"Puhu Israelin lapsille, sanoen: se joka Herralle kiitosuhrinsa uhraa, hänen pitää tuoman, mikä Herralle kiitosuhriksi tulee.","Puhu Israelin lapsille, sanoen: se joka Herralle kiitosuhrinsa uhraa, hänen pitää tuoman, mikä Herralle kiitosuhriksi tulee."],[7,30,"Mutta hänen pitää sen kantaman kädessänsä Herran tuliuhriksi: rinnan lihavuuden pitää hänen tuoman rinnan kanssa, että ne pitää oleman häälytysuhriksi Herralle.","Mutta hänen pitää sen kantaman kädessänsä Herran tuliuhriksi: rinnan lihavuuden pitää hänen tuoman rinnan kanssa, että ne pitää oleman häälytysuhriksi Herralle."],[7,31,"Mutta papin pitää polttaman lihavuuden alttarilla, ja rinnan pitää Aaronin ja hänen poikainsa oleman.","Mutta papin pitää polttaman lihavuuden alttarilla, ja rinnan pitää Aaronin ja hänen poikainsa oleman."],[7,32,"Ja oikian lavan pitää teidän antaman papille ylennysuhriksi, teidän kiitosuhristanne.","Ja oikian lavan pitää teidän antaman papille ylennysuhriksi, teidän kiitosuhristanne."],[7,33,"Ja joka uhraa kiitosuhrin verta ja lihavuutta Aaronin pojista, hänen pitää saaman oikian lavan osaksensa.","Ja joka uhraa kiitosuhrin verta ja lihavuutta Aaronin pojista, hänen pitää saaman oikian lavan osaksensa."],[7,34,"Sillä häälytysrinnan ja ylennyslavan olen minä ottanut Israelin lapsilta heidän kiitosuhristansa, ja olen sen antanut papille Aaronille ja hänen pojillensa ijankaikkiseksi säädyksi, Israelin lapsilta.","Sillä häälytysrinnan ja ylennyslavan olen minä ottanut Israelin lapsilta heidän kiitosuhristansa, ja olen sen antanut papille Aaronille ja hänen pojillensa ijankaikkiseksi säädyksi, Israelin lapsilta."],[7,35,"Tämä on Aaronin ja hänen poikainsa voitelus Herran tuliuhrista, siitä päivästä, jona he Herralle papiksi annettiin.","Tämä on Aaronin ja hänen poikainsa voitelus Herran tuliuhrista, siitä päivästä, jona he Herralle papiksi annettiin."],[7,36,"Jotka Herra käski sinä päivänä, jona hän heidän voiteli, annettaa heille Israelin lapsilta, ijankaikkiseksi säädyksi heidän sukukunnissansa.","Jotka Herra käski sinä päivänä, jona hän heidän voiteli, annettaa heille Israelin lapsilta, ijankaikkiseksi säädyksi heidän sukukunnissansa."],[7,37,"Ja tämä on sääty polttouhrista, ruokauhrista, rikosuhrista, vikauhrista, niin myös täytösuhrista ja kiitosuhrista.","Ja tämä on sääty polttouhrista, ruokauhrista, rikosuhrista, vikauhrista, niin myös täytösuhrista ja kiitosuhrista."],[7,38,"Jonka Herra Mosekselle käski Sinain vuorella; sinä päivänä, jona hän käskyn antoi hänelle Israelin lasten tykö, että heidän pitää uhraaman uhrinsa Herralle Sinain korvessa.","Jonka Herra Mosekselle käski Sinain vuorella; sinä päivänä, jona hän käskyn antoi hänelle Israelin lasten tykö, että heidän pitää uhraaman uhrinsa Herralle Sinain korvessa."],[8,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[8,2,"Ota Aaron poikinensa ja vaatteet, ja voidellusöljy: niin myös mulli rikosuhriksi, ja kaksi oinasta, ja myös kori happamattomia leipiä.","Ota Aaron poikinensa ja vaatteet, ja voidellusöljy: niin myös mulli rikosuhriksi, ja kaksi oinasta, ja myös kori happamattomia leipiä."],[8,3,"Ja kokoo kaikki kansa, seurakunnan majan oven eteen.","Ja kokoo kaikki kansa, seurakunnan majan oven eteen."],[8,4,"Moses teki niinkuin Herra hänelle käskenyt oli: ja kokosi kansan seurakunnan majan oven eteen.","Moses teki niinkuin Herra hänelle käskenyt oli: ja kokosi kansan seurakunnan majan oven eteen."],[8,5,"Ja Moses sanoi kansalle: tämä on se minkä Herra on käskenyt tehdä.","Ja Moses sanoi kansalle: tämä on se minkä Herra on käskenyt tehdä."],[8,6,"Ja Moses otti Aaronin poikinensa, ja pesi heidät vedellä.","Ja Moses otti Aaronin poikinensa, ja pesi heidät vedellä."],[8,7,"Ja puetti hänen yllensä hameen, ja vyötti hänen vyöllä ja puetti hänen ylishameella, ja pani päällisvaatteen hänen päällensä: niin myös vyötti hänen päällisvaatteen vyöllä, ja vaatetti hänen sillä.","Ja puetti hänen yllensä hameen, ja vyötti hänen vyöllä ja puetti hänen ylishameella, ja pani päällisvaatteen hänen päällensä: niin myös vyötti hänen päällisvaatteen vyöllä, ja vaatetti hänen sillä."],[8,8,"Ja pani hänen päällensä rintavaatteen: ja pani rintavaatteen päälle valkeudet ja täydellisyydet.","Ja pani hänen päällensä rintavaatteen: ja pani rintavaatteen päälle valkeudet ja täydellisyydet."],[8,9,"Ja pani hiipan hänen päähänsä: ja pani hiipan päälle hänen otsallensa kultaisen otsalehden, pyhän kruunun, niinkuin Herra Mosekselle käskenyt oli.","Ja pani hiipan hänen päähänsä: ja pani hiipan päälle hänen otsallensa kultaisen otsalehden, pyhän kruunun, niinkuin Herra Mosekselle käskenyt oli."],[8,10,"Ja Moses otti voidellusöljyn, ja voiteli majan ja kaikki mitä siinä oli: ja pyhitti ne.","Ja Moses otti voidellusöljyn, ja voiteli majan ja kaikki mitä siinä oli: ja pyhitti ne."],[8,11,"Ja priiskotti sitä seitsemän kertaa alttarille, ja voiteli alttarin ja kaikki sen astiat, ja pesoastian jalkoinensa, ja pyhitti ne.","Ja priiskotti sitä seitsemän kertaa alttarille, ja voiteli alttarin ja kaikki sen astiat, ja pesoastian jalkoinensa, ja pyhitti ne."],[8,12,"Ja kaasi voidellusöljyä Aaronin pään päälle, ja voiteli hänen ja pyhitti.","Ja kaasi voidellusöljyä Aaronin pään päälle, ja voiteli hänen ja pyhitti."],[8,13,"Ja Moses toi aaronin pojat, ja puetti heidän yllensä hameet, vyötti heidät vyöllä, ja sitoi lakit heidän päähänsä: niin kuin Herra hänelle käskenyt oli.","Ja Moses toi aaronin pojat, ja puetti heidän yllensä hameet, vyötti heidät vyöllä, ja sitoi lakit heidän päähänsä: niin kuin Herra hänelle käskenyt oli."],[8,14,"Ja antoi tuoda mullin rikosuhriksi ja Aaron poikinensa pani kätensä rikosuhrin mullin pään päälle,","Ja antoi tuoda mullin rikosuhriksi ja Aaron poikinensa pani kätensä rikosuhrin mullin pään päälle,"],[8,15,"Ja teurasti sen. Ja Moses otti verestä, ja pani sormellansa alttarin sarviin ympärinsä, ja puhdisti alttarin, ja kaasi veren alttarin pohjalle, ja pyhitti sen, sovittaaksensa (kansaa) sen päällä.","Ja teurasti sen. Ja Moses otti verestä, ja pani sormellansa alttarin sarviin ympärinsä, ja puhdisti alttarin, ja kaasi veren alttarin pohjalle, ja pyhitti sen, sovittaaksensa (kansaa) sen päällä."],[8,16,"Ja otti kaiken sisällysten lihavuuden, ja maksan kalvon, ja molemmat munaskuut, ynnä lihavuuden kanssa, ja Moses suitsutti ne alttarilla.","Ja otti kaiken sisällysten lihavuuden, ja maksan kalvon, ja molemmat munaskuut, ynnä lihavuuden kanssa, ja Moses suitsutti ne alttarilla."],[8,17,"Mutta mullin vuotinensa, lihoinensa ja sontinensa poltti hän tulessa ulkona leiristä, niinkuin Herra Mosekselle käskenyt oli.","Mutta mullin vuotinensa, lihoinensa ja sontinensa poltti hän tulessa ulkona leiristä, niinkuin Herra Mosekselle käskenyt oli."],[8,18,"Ja hän toi oinaan polttouhriksi, ja Aaron poikinensa panivat kätensä oinaan pään päälle.","Ja hän toi oinaan polttouhriksi, ja Aaron poikinensa panivat kätensä oinaan pään päälle."],[8,19,"Ja se teurastettiin, ja Moses priiskotti hänen verensä alttarille ympäri.","Ja se teurastettiin, ja Moses priiskotti hänen verensä alttarille ympäri."],[8,20,"Ja leikkasi oinaan kappaleiksi, ja Moses suitsutti pään ja kappaleet ja lihavuuden,","Ja leikkasi oinaan kappaleiksi, ja Moses suitsutti pään ja kappaleet ja lihavuuden,"],[8,21,"Ja pesi sisällykset ja jalat vedellä; ja Moses suitsutti koko oinaan alttarilla: se on polttouhri makiaksi hajuksi, se on tuliuhri Herralle, niinkuin Herra hänelle käskenyt oli.","Ja pesi sisällykset ja jalat vedellä; ja Moses suitsutti koko oinaan alttarilla: se on polttouhri makiaksi hajuksi, se on tuliuhri Herralle, niinkuin Herra hänelle käskenyt oli."],[8,22,"Ja toi myös toisen oinaan, täytösuhrin oinaan, ja Aaron poikinensa pani kätensä oinaan pään päälle.","Ja toi myös toisen oinaan, täytösuhrin oinaan, ja Aaron poikinensa pani kätensä oinaan pään päälle."],[8,23,"Ja Moses teurasti sen ja otti hänen vertansa, ja sivui Aaronin oikian korvan lehteen, niin myös oikian käden peukaloon, ja oikian jalan isoon varpaaseen.","Ja Moses teurasti sen ja otti hänen vertansa, ja sivui Aaronin oikian korvan lehteen, niin myös oikian käden peukaloon, ja oikian jalan isoon varpaaseen."],[8,24,"Ja Moses toi myös Aaronin pojat, ja sivui verellä heidän oikian korvansa lehden, ja heidän oikian kätensä peukaloon, ja heidän oikian jalkansa isoon varpaaseen, ja Moses priiskotti veren alttarille ympäri.","Ja Moses toi myös Aaronin pojat, ja sivui verellä heidän oikian korvansa lehden, ja heidän oikian kätensä peukaloon, ja heidän oikian jalkansa isoon varpaaseen, ja Moses priiskotti veren alttarille ympäri."],[8,25,"Ja otti lihavuuden ja saparon ja kaiken sisällysten lihavuuden, ja maksan kalvon ja molemmat munaskuut heidän lihavuutensa kanssa, niin myös oikian lavan.","Ja otti lihavuuden ja saparon ja kaiken sisällysten lihavuuden, ja maksan kalvon ja molemmat munaskuut heidän lihavuutensa kanssa, niin myös oikian lavan."],[8,26,"Hän otti myös korista, jossa happamattomat leivät olivat Herran edessä, yhden happamattoman kyrsän, ja öljyllä voidellun kyrsän, ja ohukaisen kyrsän, ja pani ne lihavuuden ja oikian lavan päälle,","Hän otti myös korista, jossa happamattomat leivät olivat Herran edessä, yhden happamattoman kyrsän, ja öljyllä voidellun kyrsän, ja ohukaisen kyrsän, ja pani ne lihavuuden ja oikian lavan päälle,"],[8,27,"Ja antoi kaikki nämät Aaronin käsiin, ja hänen poikainsa käsiin, ja häälytti ne häälytykseksi Herran edessä.","Ja antoi kaikki nämät Aaronin käsiin, ja hänen poikainsa käsiin, ja häälytti ne häälytykseksi Herran edessä."],[8,28,"Ja sitte otti Moses ne heidän käsistänsä ja poltti alttarilla polttouhrin päällä: se on täytösuhri lepytyshajuksi, se on tuliuhri Herralle.","Ja sitte otti Moses ne heidän käsistänsä ja poltti alttarilla polttouhrin päällä: se on täytösuhri lepytyshajuksi, se on tuliuhri Herralle."],[8,29,"Ja Moses otti rinnan ja häälytti sen häälytykseksi Herran edessä: täytösuhrin oinaasta sai Moses osan, niinkuin Herra hänelle käskenyt oli.","Ja Moses otti rinnan ja häälytti sen häälytykseksi Herran edessä: täytösuhrin oinaasta sai Moses osan, niinkuin Herra hänelle käskenyt oli."],[8,30,"Ja Moses otti voidellusöljyä ja verta, joka oli alttarilla, ja priiskotti Aaronin ja hänen vaatettensa päälle, niin myös hänen poikainsa ja heidän vaatettensa päälle, ja pyhitti niin Aaronin ja hänen vaatteensa, niin myös hänen poikansa ja heidän vaatteensa hänen kanssansa.","Ja Moses otti voidellusöljyä ja verta, joka oli alttarilla, ja priiskotti Aaronin ja hänen vaatettensa päälle, niin myös hänen poikainsa ja heidän vaatettensa päälle, ja pyhitti niin Aaronin ja hänen vaatteensa, niin myös hänen poikansa ja heidän vaatteensa hänen kanssansa."],[8,31,"Ja Moses sanoi Aaronille ja hänen pojillensa: keittäkäät lihaa seurakunnan majan oven edessä, ja syökäät se siinä paikassa, niin myös leipää, joka täytösuhrin korissa on, niinkuin minä käskin sanoen: Aaron poikinensa pitää ne syömän.","Ja Moses sanoi Aaronille ja hänen pojillensa: keittäkäät lihaa seurakunnan majan oven edessä, ja syökäät se siinä paikassa, niin myös leipää, joka täytösuhrin korissa on, niinkuin minä käskin sanoen: Aaron poikinensa pitää ne syömän."],[8,32,"Vaan mitä jää tähteeksi lihasta ja leivästä, sen teidän pitää polttaman tulessa.","Vaan mitä jää tähteeksi lihasta ja leivästä, sen teidän pitää polttaman tulessa."],[8,33,"Ja ei teidän pidä lähtemän seitsemänä päivänä seurakunnan majan ovesta, siihenasti, koska tiedän täytösuhrinne päivät täytetään; sillä seitsemänä päivänä teidän kätenne täytetään.","Ja ei teidän pidä lähtemän seitsemänä päivänä seurakunnan majan ovesta, siihenasti, koska tiedän täytösuhrinne päivät täytetään; sillä seitsemänä päivänä teidän kätenne täytetään."],[8,34,"Niinkuin se tänäpänä tapahtunut on, niin Herra on käskenyt tehtää, että te sovitettaisiin.","Niinkuin se tänäpänä tapahtunut on, niin Herra on käskenyt tehtää, että te sovitettaisiin."],[8,35,"Ja teidän pitää oleman seitsemän päivää seurakunnan majan oven edessä, yli päivää ja yötä, ja teidän pitää ottaman vaarin Herran vartioista, ettette kuolisi; sillä niin on minulle käsketty.","Ja teidän pitää oleman seitsemän päivää seurakunnan majan oven edessä, yli päivää ja yötä, ja teidän pitää ottaman vaarin Herran vartioista, ettette kuolisi; sillä niin on minulle käsketty."],[8,36,"Ja Aaron poikinensa teki kaiken sen, kuin Herra Moseksen kautta käskenyt oli.","Ja Aaron poikinensa teki kaiken sen, kuin Herra Moseksen kautta käskenyt oli."],[9,1,"Ja tapahtui kahdeksantena päivänä, että Moses kutsui Aaronin ja hänen poikansa, niin myös vanhimmat Israelista.","Ja tapahtui kahdeksantena päivänä, että Moses kutsui Aaronin ja hänen poikansa, niin myös vanhimmat Israelista."],[9,2,"Ja sanoi Aaronille: ota sinulles nuori vasikka rikosuhriksi, ja oinas polttouhriksi, molemmat virheettömät, ja tuo Herran eteen.","Ja sanoi Aaronille: ota sinulles nuori vasikka rikosuhriksi, ja oinas polttouhriksi, molemmat virheettömät, ja tuo Herran eteen."],[9,3,"Ja puhu Israelin lapsille, sanoen: ottakaat kauris rikosuhriksi, ja vasikka ja karitsa, molemmat vuosikuntaiset ja virheettömät, polttouhriksi.","Ja puhu Israelin lapsille, sanoen: ottakaat kauris rikosuhriksi, ja vasikka ja karitsa, molemmat vuosikuntaiset ja virheettömät, polttouhriksi."],[9,4,"Ja myös härkä ja oinas uhrattaa kiitosuhriksi Herran edessä, ja ruokauhri sekoitettu öljyllä; sillä tänäpänä ilmestyy Herra teille.","Ja myös härkä ja oinas uhrattaa kiitosuhriksi Herran edessä, ja ruokauhri sekoitettu öljyllä; sillä tänäpänä ilmestyy Herra teille."],[9,5,"Ja he toivat ne kuin Moses käskenyt oli, seurakunnan majan oven eteen: ja kaikki kansa kävi edes, ja seisoi Herran edessä.","Ja he toivat ne kuin Moses käskenyt oli, seurakunnan majan oven eteen: ja kaikki kansa kävi edes, ja seisoi Herran edessä."],[9,6,"Niin sanoi Moses: tämä on se, minkä Herra käskenyt on teidän tehdä, ja Herran kunnia ilmestyy teille.","Niin sanoi Moses: tämä on se, minkä Herra käskenyt on teidän tehdä, ja Herran kunnia ilmestyy teille."],[9,7,"Ja Moses sanoi Aaronille: astu alttarin tykö, ja tee rikosuhris, ja poltouhris ja sovita sinuas ja kansaa, ja tee sitte kansan uhri ja sovita heitä, niinkuin Herra käskenyt on.","Ja Moses sanoi Aaronille: astu alttarin tykö, ja tee rikosuhris, ja poltouhris ja sovita sinuas ja kansaa, ja tee sitte kansan uhri ja sovita heitä, niinkuin Herra käskenyt on."],[9,8,"Ja Aaron astui alttarin tykö ja teurasti vasikan rikosuhriksensa.","Ja Aaron astui alttarin tykö ja teurasti vasikan rikosuhriksensa."],[9,9,"Ja Aaronin pojat kantoivat veren hänen tykönsä, ja hän kasti sormensa vereen, ja sivui alttarin sarviin, ja veren kaasi hän alttarin pohjalle.","Ja Aaronin pojat kantoivat veren hänen tykönsä, ja hän kasti sormensa vereen, ja sivui alttarin sarviin, ja veren kaasi hän alttarin pohjalle."],[9,10,"Ja lihavuuden, ja munaskuut, ja maksan kalvon rikosuhrista, poltti hän alttarilla, niinkuin Herra oli Mosekselle käskenyt.","Ja lihavuuden, ja munaskuut, ja maksan kalvon rikosuhrista, poltti hän alttarilla, niinkuin Herra oli Mosekselle käskenyt."],[9,11,"Mutta lihan ja nahan poltti hän tulessa ulkona leiristä.","Mutta lihan ja nahan poltti hän tulessa ulkona leiristä."],[9,12,"Sitte hän teurasti polttouhrin, ja Aaronin pojat kantoivat veren hänen tykönsä, ja hän priiskotti sen alttarille ympäri.","Sitte hän teurasti polttouhrin, ja Aaronin pojat kantoivat veren hänen tykönsä, ja hän priiskotti sen alttarille ympäri."],[9,13,"Ja he toivat myös polttouhrin hänelle, kappaleiksi leikatun, ja pään, ja hän poltti ne alttarilla.","Ja he toivat myös polttouhrin hänelle, kappaleiksi leikatun, ja pään, ja hän poltti ne alttarilla."],[9,14,"Ja hän pesi sisällykset ja jalat, ja poltti ne polttouhrin päällä, alttarilla.","Ja hän pesi sisällykset ja jalat, ja poltti ne polttouhrin päällä, alttarilla."],[9,15,"Sitte kantoi hän kansan uhrin edes, ja otti kauriin, joka oli kansan rikosuhri, ja teurasti sen, ja teki siitä rikosuhrin, niinkuin sen entisenkin.","Sitte kantoi hän kansan uhrin edes, ja otti kauriin, joka oli kansan rikosuhri, ja teurasti sen, ja teki siitä rikosuhrin, niinkuin sen entisenkin."],[9,16,"Ja hän toi myös polttouhrin, ja valmisti sen tavan jälkeen.","Ja hän toi myös polttouhrin, ja valmisti sen tavan jälkeen."],[9,17,"Ja toi ruokauhrin, ja otti siitä pivonsa täyden, ja poltti ne alttarilla, paitsi aamullista polttouhria.","Ja toi ruokauhrin, ja otti siitä pivonsa täyden, ja poltti ne alttarilla, paitsi aamullista polttouhria."],[9,18,"Sitte teurasti hän härjän ja oinaan kansan kiitosuhriksi, ja Aaronin pojat kantoivat veren hänelle, ja hän priiskotti sen alttarin ympäri.","Sitte teurasti hän härjän ja oinaan kansan kiitosuhriksi, ja Aaronin pojat kantoivat veren hänelle, ja hän priiskotti sen alttarin ympäri."],[9,19,"Mutta härjän lihavuuden, ja oinaan saparon, ja sisällysten lihavuuden, ja munaskuut, ja maksan kalvon:","Mutta härjän lihavuuden, ja oinaan saparon, ja sisällysten lihavuuden, ja munaskuut, ja maksan kalvon:"],[9,20,"Kaiken tämän lihavuuden panivat he rintain päälle, ja polttivat lihavuuden alttarilla.","Kaiken tämän lihavuuden panivat he rintain päälle, ja polttivat lihavuuden alttarilla."],[9,21,"Mutta rinnat ja oikian lavan häälytti Aaron häälytykseksi Herran edessä, niinkuin Herra oli käskenyt Mosekselle.","Mutta rinnat ja oikian lavan häälytti Aaron häälytykseksi Herran edessä, niinkuin Herra oli käskenyt Mosekselle."],[9,22,"Ja Aaron nosti kätensä kansan puoleen, ja siunasi heitä: ja sittekuin hän rikosuhrin, polttouhrin ja kiitosuhrin tehnyt oli, meni hän alas.","Ja Aaron nosti kätensä kansan puoleen, ja siunasi heitä: ja sittekuin hän rikosuhrin, polttouhrin ja kiitosuhrin tehnyt oli, meni hän alas."],[9,23,"Niin Moses ja Aaron menivät seurakunnan majaan, ja koska he jälleen sieltä läksivät, siunasivat he kansan. Niin Herran kunnia ilmestyi kaiken kansan edessä:","Niin Moses ja Aaron menivät seurakunnan majaan, ja koska he jälleen sieltä läksivät, siunasivat he kansan. Niin Herran kunnia ilmestyi kaiken kansan edessä:"],[9,24,"Sillä tuli tuli Herralta alas, ja kulutti polttouhrin, ja sen lihavuuden, alttarilta: ja koska kaikki kansa sen näki, riemuitsivat he sangen suuresti, ja lankesivat maahan kasvoillensa.","Sillä tuli tuli Herralta alas, ja kulutti polttouhrin, ja sen lihavuuden, alttarilta: ja koska kaikki kansa sen näki, riemuitsivat he sangen suuresti, ja lankesivat maahan kasvoillensa."],[10,1,"Ja Aaronin pojat Nadab ja Abihu ottivat kumpikin suitsutusastiansa, ja panivat tulta niihin, ja panivat suitsutusta sen päälle: ja kantoivat vierasta tulta Herran eteen, jota ei hän heille ollut käskenyt.","Ja Aaronin pojat Nadab ja Abihu ottivat kumpikin suitsutusastiansa, ja panivat tulta niihin, ja panivat suitsutusta sen päälle: ja kantoivat vierasta tulta Herran eteen, jota ei hän heille ollut käskenyt."],[10,2,"Silloin läksi tuli Herralta, ja kulutti heidät; niin että he kuolivat Herran edessä.","Silloin läksi tuli Herralta, ja kulutti heidät; niin että he kuolivat Herran edessä."],[10,3,"Niin sanoi Moses Aaronille: tämä on se kuin Herra puhunut on, sanoen: Minä pyhitetään niissä, jotka minua lähestyvät, ja kaiken kansan edessä minä kunnioitetaan. Ja Aaron oli ääneti.","Niin sanoi Moses Aaronille: tämä on se kuin Herra puhunut on, sanoen: Minä pyhitetään niissä, jotka minua lähestyvät, ja kaiken kansan edessä minä kunnioitetaan. Ja Aaron oli ääneti."],[10,4,"Mutta Moses kutsui Misaelin, ja Eltsaphanin, Usielin, Aaronin sedän pojat ja sanoi heille, tulkaat ja kantakaat teidän veljenne pyhän edestä: ulos leiristä.","Mutta Moses kutsui Misaelin, ja Eltsaphanin, Usielin, Aaronin sedän pojat ja sanoi heille, tulkaat ja kantakaat teidän veljenne pyhän edestä: ulos leiristä."],[10,5,"Ja he tulivat ja kantoivat heidät hameinensa leiristä, niinkuin Moses oli sanonut.","Ja he tulivat ja kantoivat heidät hameinensa leiristä, niinkuin Moses oli sanonut."],[10,6,"Niin sanoi Moses Aaronille, ja hänen pojillensa Eleatsarille ja Itamarille: ei teidän pidä paljastaman teidän päätänne, eikä myös repimän teidän vaatteitanne, ettette kuolisi, ja ettei viha tulisi kaiken kansan päälle: mutta teidän veljenne koko Israelin huoneesta itkekään tätä paloa, jonka Herra sytyttänyt on.","Niin sanoi Moses Aaronille, ja hänen pojillensa Eleatsarille ja Itamarille: ei teidän pidä paljastaman teidän päätänne, eikä myös repimän teidän vaatteitanne, ettette kuolisi, ja ettei viha tulisi kaiken kansan päälle: mutta teidän veljenne koko Israelin huoneesta itkekään tätä paloa, jonka Herra sytyttänyt on."],[10,7,"Vaan ei teidän pidä menemän seurakunnan majan ovesta ulos, ettette kuolisi; sillä Herran voidellusöljy on teidän päällänne. Ja he tekivät Moseksen sanan jälkeen.","Vaan ei teidän pidä menemän seurakunnan majan ovesta ulos, ettette kuolisi; sillä Herran voidellusöljy on teidän päällänne. Ja he tekivät Moseksen sanan jälkeen."],[10,8,"Ja Herra puhui Aaronille, sanoen:","Ja Herra puhui Aaronille, sanoen:"],[10,9,"Viinaa ja väkevää juomaa ei pidä sinun juoman, eikä sinun poikas sinun kanssa, koska te menette seurakunnan majaan, ettette kuolisi: se pitää oleman ijankaikkinen sääty teidän sukukunnillenne,","Viinaa ja väkevää juomaa ei pidä sinun juoman, eikä sinun poikas sinun kanssa, koska te menette seurakunnan majaan, ettette kuolisi: se pitää oleman ijankaikkinen sääty teidän sukukunnillenne,"],[10,10,"Että te eroitatte mikä pyhä ja ei pyhä, mikä saastainen ja puhdas on.","Että te eroitatte mikä pyhä ja ei pyhä, mikä saastainen ja puhdas on."],[10,11,"Ja että te opettaisitte Israelin lapsille kaikki oikeudet, kuin Herra heille Moseksen kautta puhunut on.","Ja että te opettaisitte Israelin lapsille kaikki oikeudet, kuin Herra heille Moseksen kautta puhunut on."],[10,12,"Ja Moses puhui Aaronille ja hänen jääneille pojillensa Eleatsarille ja Itamarille: ottakaat se, joka tähteeksi jäänyt on ruokauhrista, Herran tuliuhrista, ja syökäät se happamattomana alttarin tykönä; sillä se on kaikkein pyhin.","Ja Moses puhui Aaronille ja hänen jääneille pojillensa Eleatsarille ja Itamarille: ottakaat se, joka tähteeksi jäänyt on ruokauhrista, Herran tuliuhrista, ja syökäät se happamattomana alttarin tykönä; sillä se on kaikkein pyhin."],[10,13,"Ja teidän pitää sen syömän pyhällä sialla: sillä se on sinun oikeutes ja sinun poikais oikeus Herran tuliuhrista; sillä se on minulle niin käsketty.","Ja teidän pitää sen syömän pyhällä sialla: sillä se on sinun oikeutes ja sinun poikais oikeus Herran tuliuhrista; sillä se on minulle niin käsketty."],[10,14,"Mutta häälytysrinnan ja ylennyslavan pitää sinun ja sinun poikas ja tyttäres sinun kanssas syömän puhtaalla paikalla; sillä tämä oikeus on sinulle ja sinun pojilles annettu Israelin lasten kiitosuhrista;","Mutta häälytysrinnan ja ylennyslavan pitää sinun ja sinun poikas ja tyttäres sinun kanssas syömän puhtaalla paikalla; sillä tämä oikeus on sinulle ja sinun pojilles annettu Israelin lasten kiitosuhrista;"],[10,15,"Sillä ylennyslapa ja häälytysrinta, lihavuus tuliuhrein kanssa, pitää kannettaman sisälle häälytettää häälytykseksi Herran edessä: sentähden pitää sen oleman sinulle ja sinun lapsilles ijankaikkiseksi säädyksi, niinkuin Herra käskenyt on.","Sillä ylennyslapa ja häälytysrinta, lihavuus tuliuhrein kanssa, pitää kannettaman sisälle häälytettää häälytykseksi Herran edessä: sentähden pitää sen oleman sinulle ja sinun lapsilles ijankaikkiseksi säädyksi, niinkuin Herra käskenyt on."],[10,16,"Ja Moses etsi ahkerasti rikosuhrin kaurista, ja katso, se oli poltettu: ja vihastui Eleatsarin ja Itamarin Aaronin jääneiden poikain päälle, sanoen:","Ja Moses etsi ahkerasti rikosuhrin kaurista, ja katso, se oli poltettu: ja vihastui Eleatsarin ja Itamarin Aaronin jääneiden poikain päälle, sanoen:"],[10,17,"Miksi ette ole syöneet rikosuhria pyhällä paikalla? sillä se on kaikkein pyhin, ja hän on antanut teille sen, että teidän pitää kantaman kansan rikokset, ja sovittaman heitä Herran edessä.","Miksi ette ole syöneet rikosuhria pyhällä paikalla? sillä se on kaikkein pyhin, ja hän on antanut teille sen, että teidän pitää kantaman kansan rikokset, ja sovittaman heitä Herran edessä."],[10,18,"Katso, hänen verensä ei ole tuotu pyhään: teidän olis pitänyt kaiketi syömän sen pyhässä, niinkuin minulle käsketty on.","Katso, hänen verensä ei ole tuotu pyhään: teidän olis pitänyt kaiketi syömän sen pyhässä, niinkuin minulle käsketty on."],[10,19,"Mutta Aaron sanoi Mosekselle: katso, tänäpänä ovat he uhranneet rikosuhrinsa ja polttouhrinsa Herran edessä. Ja minulle on senkaltainen asia tapahtunut: ja pitäiskö minun tänäpänä syömän rikosuhrista, olisko se Herralle otollinen?","Mutta Aaron sanoi Mosekselle: katso, tänäpänä ovat he uhranneet rikosuhrinsa ja polttouhrinsa Herran edessä. Ja minulle on senkaltainen asia tapahtunut: ja pitäiskö minun tänäpänä syömän rikosuhrista, olisko se Herralle otollinen?"],[10,20,"Kun Moses sen kuuli, tyytyi hän siihen","Kun Moses sen kuuli, tyytyi hän siihen"],[11,1,"Ja Herra puhui Mosekselle ja Aaronille, sanoen heille:","Ja Herra puhui Mosekselle ja Aaronille, sanoen heille:"],[11,2,"Puhukaat Israelin lapsille, sanoen: nämät ovat eläimet, joita te saatte syödä, kaikkein eläinten seassa maan päällä.","Puhukaat Israelin lapsille, sanoen: nämät ovat eläimet, joita te saatte syödä, kaikkein eläinten seassa maan päällä."],[11,3,"Kaikista kaksisorkkaisista eläimistä, jotka sorkkansa kokonansa hajoittavat ja märhettivät, saatte te syödä.","Kaikista kaksisorkkaisista eläimistä, jotka sorkkansa kokonansa hajoittavat ja märhettivät, saatte te syödä."],[11,4,"Kuitenkin tätä ette mahda syödä niistä, jotka märhettivät ja ovat kaksisorkkaiset, nimittäin: kameli, joka kyllä märhettii, vaan ei hajota sorkkiansa, se on teille saastainen;","Kuitenkin tätä ette mahda syödä niistä, jotka märhettivät ja ovat kaksisorkkaiset, nimittäin: kameli, joka kyllä märhettii, vaan ei hajota sorkkiansa, se on teille saastainen;"],[11,5,"Kaninit märhettivät, mutta ei ole kaksisorkkaiset, sentähden ne ovat teille saastaiset;","Kaninit märhettivät, mutta ei ole kaksisorkkaiset, sentähden ne ovat teille saastaiset;"],[11,6,"Ja jänis myös märhettii, vaan ei ole kaksisorkkainen, sentähden se on teille saastainen;","Ja jänis myös märhettii, vaan ei ole kaksisorkkainen, sentähden se on teille saastainen;"],[11,7,"Ja sika on kaksisorkkainen, joka kokonansa hajottaa sorkkansa, mutta ei märheti, sentähden se on teille saastainen.","Ja sika on kaksisorkkainen, joka kokonansa hajottaa sorkkansa, mutta ei märheti, sentähden se on teille saastainen."],[11,8,"Näiden lihaa ei teidän pidä syömän, eikä heidän raatoihinsa tarttuman; sillä ne ovat teille saastaiset.","Näiden lihaa ei teidän pidä syömän, eikä heidän raatoihinsa tarttuman; sillä ne ovat teille saastaiset."],[11,9,"Näitä te saatte syödä kaikista niistä jotka vesissä ovat: kaikki, joilla on uimukset ja suomukset vesissä, meressä ja virroissa, niitä teidän pitää syömän.","Näitä te saatte syödä kaikista niistä jotka vesissä ovat: kaikki, joilla on uimukset ja suomukset vesissä, meressä ja virroissa, niitä teidän pitää syömän."],[11,10,"Mutta kaikki, joilla ei ole uimuksia ja suomuksia meressä ja virroissa, kaikkein niiden seassa, jotka liikkuvat ja elävät vesissä, ne pitää oleman teille kauhistus.","Mutta kaikki, joilla ei ole uimuksia ja suomuksia meressä ja virroissa, kaikkein niiden seassa, jotka liikkuvat ja elävät vesissä, ne pitää oleman teille kauhistus."],[11,11,"Ne ovat teitä kauhistavat: niiden lihaa ei teidän pidä syömän, kauhistukaat heidän raatoansa.","Ne ovat teitä kauhistavat: niiden lihaa ei teidän pidä syömän, kauhistukaat heidän raatoansa."],[11,12,"Sillä kaikki, joilla ei ole uimuksia ja suomuksia vesissä, ne ovat teille kauhistus.","Sillä kaikki, joilla ei ole uimuksia ja suomuksia vesissä, ne ovat teille kauhistus."],[11,13,"Näitä te kauhistukaat linnuista, eikä teidän niitä pidä syömän, sillä ne ovat kauhistus: Kotka, ja luukotka ja kalakotka;","Näitä te kauhistukaat linnuista, eikä teidän niitä pidä syömän, sillä ne ovat kauhistus: Kotka, ja luukotka ja kalakotka;"],[11,14,"Kokkolintu, ja harakka lainensa,","Kokkolintu, ja harakka lainensa,"],[11,15,"Ja kaikki kaarneet lainensa;","Ja kaikki kaarneet lainensa;"],[11,16,"Strutsi, pääskyinen, louve ja haukka lainensa;","Strutsi, pääskyinen, louve ja haukka lainensa;"],[11,17,"Huhkaja, merimetsäs ja hyypiä;","Huhkaja, merimetsäs ja hyypiä;"],[11,18,"Yökkö, ruovonpäristäjä ja storkki;","Yökkö, ruovonpäristäjä ja storkki;"],[11,19,"Haikara ja mäkihaukka lainensa, puputtaja ja nahkasiipi.","Haikara ja mäkihaukka lainensa, puputtaja ja nahkasiipi."],[11,20,"Ja kaikki, jotka liikkuvat lintuin seassa ja käyvät neljällä jalalla, pitää oleman teille kauhistus.","Ja kaikki, jotka liikkuvat lintuin seassa ja käyvät neljällä jalalla, pitää oleman teille kauhistus."],[11,21,"Kuitenkin näitä saatte te syödä linnuista, jotka liikkuvat ja käyvät neljällä jalalla: joilla ovat sääret jalkain päällä, hypellä maan päällä.","Kuitenkin näitä saatte te syödä linnuista, jotka liikkuvat ja käyvät neljällä jalalla: joilla ovat sääret jalkain päällä, hypellä maan päällä."],[11,22,"Ja näitä te saatte syödä heistä kuin on: arbe lainensa, ja selaam lainensa, ja hargol lainensa, ja hagab lainensa.","Ja näitä te saatte syödä heistä kuin on: arbe lainensa, ja selaam lainensa, ja hargol lainensa, ja hagab lainensa."],[11,23,"Vaan kaikki, jotka paitsi niitä ovat nelijalkaiset lintuin seassa, ne ovat teille kauhistus.","Vaan kaikki, jotka paitsi niitä ovat nelijalkaiset lintuin seassa, ne ovat teille kauhistus."],[11,24,"Ja ne pitää teidän saastaisena pitämän; ja jokainen kuin tarttuu heidän raatoihinsa, sen pitää oleman saastaisen ehtoosen asti.","Ja ne pitää teidän saastaisena pitämän; ja jokainen kuin tarttuu heidän raatoihinsa, sen pitää oleman saastaisen ehtoosen asti."],[11,25,"Ja jos joku heidän raatojansa kantaa, sen pitää pesemän vaatteensa ja oleman saastaisen ehtoosen asti.","Ja jos joku heidän raatojansa kantaa, sen pitää pesemän vaatteensa ja oleman saastaisen ehtoosen asti."],[11,26,"Ja jokainen eläin, joka on sorkallinen, vaan ei kaksisorkkainen, eikä märheti, ne ovat teille saastaiset; ja jokainen, kuin niihin tarttuu, pitää oleman saastainen.","Ja jokainen eläin, joka on sorkallinen, vaan ei kaksisorkkainen, eikä märheti, ne ovat teille saastaiset; ja jokainen, kuin niihin tarttuu, pitää oleman saastainen."],[11,27,"Ja jokainen kuin käy kämmenellänsä kaikkein petoin seassa, jotka käyvät neljällä jalalla, ne ovat teille saastaiset; jokainen, kuin rupee heidän raatoihinsa, sen pitää oleman saastaisen ehtoosen asti.","Ja jokainen kuin käy kämmenellänsä kaikkein petoin seassa, jotka käyvät neljällä jalalla, ne ovat teille saastaiset; jokainen, kuin rupee heidän raatoihinsa, sen pitää oleman saastaisen ehtoosen asti."],[11,28,"Ja joka kantaa heidän raatojansa, se peskään vaatteensa, ja pitää oleman saastaisen ehtoosen asti; sillä kaikki nämät ovat saastaiset teille.","Ja joka kantaa heidän raatojansa, se peskään vaatteensa, ja pitää oleman saastaisen ehtoosen asti; sillä kaikki nämät ovat saastaiset teille."],[11,29,"Ja nämät pitää oleman myös teille saastaiset niiden eläinten seassa, jotka matelevat maalla: myyrä, hiiri, maakrokodili, jokainen lainensa.","Ja nämät pitää oleman myös teille saastaiset niiden eläinten seassa, jotka matelevat maalla: myyrä, hiiri, maakrokodili, jokainen lainensa."],[11,30,"Stellio, kameleon, sisilisko, sinisisilisko ja salamandra.","Stellio, kameleon, sisilisko, sinisisilisko ja salamandra."],[11,31,"Nämät ovat teille saastaiset kaikkein niiden seassa, kuin matelevat; ja jokainen kuin rupee heihin sittekuin he kuolleet ovat, pitää oleman saastainen ehtoosen asti.","Nämät ovat teille saastaiset kaikkein niiden seassa, kuin matelevat; ja jokainen kuin rupee heihin sittekuin he kuolleet ovat, pitää oleman saastainen ehtoosen asti."],[11,32,"Ja kaikki, kuin senkaltainen raato päälle putoo pitää oleman saastainen, olis se kaikkinainen puuastia, eli vaate, eli nahka, eli säkki; ja kaikkinainen ase, jolla jotakin tehdään, pitää pantaman veteen, ja sen pitää oleman saastaisen ehtoosen asti, niin se tulee puhtaaksi.","Ja kaikki, kuin senkaltainen raato päälle putoo pitää oleman saastainen, olis se kaikkinainen puuastia, eli vaate, eli nahka, eli säkki; ja kaikkinainen ase, jolla jotakin tehdään, pitää pantaman veteen, ja sen pitää oleman saastaisen ehtoosen asti, niin se tulee puhtaaksi."],[11,33,"Ja kaikkinaiset savi-astiat, joihinka senkaltainen raato putoo, ovat kaikki saastaiset, ja mitä niissä on, ja pitää rikottaman.","Ja kaikkinaiset savi-astiat, joihinka senkaltainen raato putoo, ovat kaikki saastaiset, ja mitä niissä on, ja pitää rikottaman."],[11,34,"Kaikki ruoka, jota syödään, jos se vesi tulee sen päälle, se on saastainen, ja kaikki juoma, jota juodaan senkaltaisista astioista, on saastainen.","Kaikki ruoka, jota syödään, jos se vesi tulee sen päälle, se on saastainen, ja kaikki juoma, jota juodaan senkaltaisista astioista, on saastainen."],[11,35,"Ja kaikki, kuin senkaltainen raato päälle putoo, se tulee saastaiseksi, olis se pätsi eli kattila, se pitää rikottaman; sillä se on saastainen, ja sen pitää oleman teille saastaisen.","Ja kaikki, kuin senkaltainen raato päälle putoo, se tulee saastaiseksi, olis se pätsi eli kattila, se pitää rikottaman; sillä se on saastainen, ja sen pitää oleman teille saastaisen."],[11,36,"Kuitenkin lähteet, kaivot ja lammikot ovat puhtaat; vaan jokainen, joka tarttuu heidän raatoonsa, sen pitää oleman saastaisen.","Kuitenkin lähteet, kaivot ja lammikot ovat puhtaat; vaan jokainen, joka tarttuu heidän raatoonsa, sen pitää oleman saastaisen."],[11,37,"Ja jos senkaltainen raato lankee siemenen päälle, joka kylvetty on, niin on se kuitenkin puhdas.","Ja jos senkaltainen raato lankee siemenen päälle, joka kylvetty on, niin on se kuitenkin puhdas."],[11,38,"Ja jos vettä kaadetaan siemenen päälle, ja lankee joku senkaltainen raato niiden päälle, niin se tulee teille saastaiseksi.","Ja jos vettä kaadetaan siemenen päälle, ja lankee joku senkaltainen raato niiden päälle, niin se tulee teille saastaiseksi."],[11,39,"Ja jos joku eläin kuolee, jota teidän sopii syödä, se joka sen raatoon tarttuu, se on saastainen ehtoosen asti.","Ja jos joku eläin kuolee, jota teidän sopii syödä, se joka sen raatoon tarttuu, se on saastainen ehtoosen asti."],[11,40,"Se joka syö senkaltaista raatoa, hänen pitää pesemän vaatteensa ja oleman saastaisen ehtoosen asti, niin myös se, joka kantaa senkaltasia raatoja, pitää pesemän vaatteensa ja oleman saastaisen ehtoosen asti.","Se joka syö senkaltaista raatoa, hänen pitää pesemän vaatteensa ja oleman saastaisen ehtoosen asti, niin myös se, joka kantaa senkaltasia raatoja, pitää pesemän vaatteensa ja oleman saastaisen ehtoosen asti."],[11,41,"Kaikki maalla matelevainen pitää oleman teille kauhistava, ja ei pidä sitä syötämän.","Kaikki maalla matelevainen pitää oleman teille kauhistava, ja ei pidä sitä syötämän."],[11,42,"Ja jokainen kuin vatsallansa käy, ja jotka käyvät neljällä eli useammalla jalalla, kaikista, jotka matelevat maalla, ei pidä teidän niitä syömän; sillä ne ovat kauhistus.","Ja jokainen kuin vatsallansa käy, ja jotka käyvät neljällä eli useammalla jalalla, kaikista, jotka matelevat maalla, ei pidä teidän niitä syömän; sillä ne ovat kauhistus."],[11,43,"Älkäät sielujanne kauhistavaiseksi tehkö kaikissa matelevaisissa, ja älkäät saastuttako teitänne niissä, niin että te tulette saastaiseksi.","Älkäät sielujanne kauhistavaiseksi tehkö kaikissa matelevaisissa, ja älkäät saastuttako teitänne niissä, niin että te tulette saastaiseksi."],[11,44,"Sillä minä olen Herra teidän Jumalanne, sentähden teidän pitää pyhittämän teitänne, että te tulisitte pyhäksi; sillä minäkin olen pyhä. Ei teidän pidä saastuttaman teidän sielujanne jollakin matelevaisella eläimellä, joka matelee maalla.","Sillä minä olen Herra teidän Jumalanne, sentähden teidän pitää pyhittämän teitänne, että te tulisitte pyhäksi; sillä minäkin olen pyhä. Ei teidän pidä saastuttaman teidän sielujanne jollakin matelevaisella eläimellä, joka matelee maalla."],[11,45,"Sillä minä olen Herra, joka teidät johdatin Egyptin maalta, että minä olisin teidän Jumalanne, sentähden teidän pitää oleman pyhät; sillä minä olen pyhä.","Sillä minä olen Herra, joka teidät johdatin Egyptin maalta, että minä olisin teidän Jumalanne, sentähden teidän pitää oleman pyhät; sillä minä olen pyhä."],[11,46,"Ja tämä on sääty kaikista eläimistä ja linnuista, ja kaikista, jotka vesissä liikkuvat, ja kaikkinaisista eläimistä, jotka maalla matelevat,","Ja tämä on sääty kaikista eläimistä ja linnuista, ja kaikista, jotka vesissä liikkuvat, ja kaikkinaisista eläimistä, jotka maalla matelevat,"],[11,47,"Että tietäisitte eroittaa puhtaat saastaisista: ja mitä eläimiä syödä saadaan, ja mitä eläimiä ei sovi syödä.","Että tietäisitte eroittaa puhtaat saastaisista: ja mitä eläimiä syödä saadaan, ja mitä eläimiä ei sovi syödä."],[12,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[12,2,"Puhu Israelin lapsille, ja sano: koska vaimo siittää ja synnyttä poikalapsen, niin hänen pitää seitsemän päivää oleman saastaisen, niinkauvan kuin hän kärsii sairauttansa.","Puhu Israelin lapsille, ja sano: koska vaimo siittää ja synnyttä poikalapsen, niin hänen pitää seitsemän päivää oleman saastaisen, niinkauvan kuin hän kärsii sairauttansa."],[12,3,"Ja kahdeksantena päivänä pitää ympärileikattaman hänen esinahkansa liha.","Ja kahdeksantena päivänä pitää ympärileikattaman hänen esinahkansa liha."],[12,4,"Mutta hänen pitää oleman kotona kolmeneljättäkymmentä päivää puhdistuksensa veressä; ei hänen pidä rupeeman yhteekään, mikä pyhä on, eikä hänen pidä pyhään tuleman, siihenasti kuin hänen puhdistuspäivänsä täytetään.","Mutta hänen pitää oleman kotona kolmeneljättäkymmentä päivää puhdistuksensa veressä; ei hänen pidä rupeeman yhteekään, mikä pyhä on, eikä hänen pidä pyhään tuleman, siihenasti kuin hänen puhdistuspäivänsä täytetään."],[12,5,"Mutta jos hän synnyttää piikalapsen, niin hänen pitää saastaisen oleman kaksi viikkoa, niinkauvan kuin hän kärsii sairauttansa, ja kuusiseitsemättäkymmentä päivää pitää hänen kotona oleman puhdistuksensa veressä.","Mutta jos hän synnyttää piikalapsen, niin hänen pitää saastaisen oleman kaksi viikkoa, niinkauvan kuin hän kärsii sairauttansa, ja kuusiseitsemättäkymmentä päivää pitää hänen kotona oleman puhdistuksensa veressä."],[12,6,"Mutta koska hänen puhdistuspäivänsä pojan eli tyttären jälkeen ovat täytetyt, niin tuokaan vuosikuntaisen karitsan polttouhriksi, ja kyhkyläisen pojan eli mettisen rikosuhriksi, papille seurakunnan majan oven eteen,","Mutta koska hänen puhdistuspäivänsä pojan eli tyttären jälkeen ovat täytetyt, niin tuokaan vuosikuntaisen karitsan polttouhriksi, ja kyhkyläisen pojan eli mettisen rikosuhriksi, papille seurakunnan majan oven eteen,"],[12,7,"Jonka ne pitää uhraaman Herran edessä, ja sovittaman hänen, niin hän puhdistuu verensä juoksusta. Tämä on sääty pojan eli tyttären synnyttämisestä.","Jonka ne pitää uhraaman Herran edessä, ja sovittaman hänen, niin hän puhdistuu verensä juoksusta. Tämä on sääty pojan eli tyttären synnyttämisestä."],[12,8,"Jos ei hänellä ole varaa karitsaan, niin ottakaan kaksi mettistä, eli kaksi kyhkyläisen poikaa, toisen polttouhriksi ja toisen rikosuhriksi. Ja niin papin pitää sovittaman hänen, että hän puhdistettaisiin.","Jos ei hänellä ole varaa karitsaan, niin ottakaan kaksi mettistä, eli kaksi kyhkyläisen poikaa, toisen polttouhriksi ja toisen rikosuhriksi. Ja niin papin pitää sovittaman hänen, että hän puhdistettaisiin."],[13,1,"Ja Herra puhui Mosekselle ja Aaronille, sanoen:","Ja Herra puhui Mosekselle ja Aaronille, sanoen:"],[13,2,"Jos ihmisen ihoon tulee ajos, eli rupi, eli syhelmä, niinkuin spitalitauti tahtois tulla hänen ihoonsa, niin pitää hän vietämän papin Aaronin tykö, eli yhden hänen pojistansa pappein seasta.","Jos ihmisen ihoon tulee ajos, eli rupi, eli syhelmä, niinkuin spitalitauti tahtois tulla hänen ihoonsa, niin pitää hän vietämän papin Aaronin tykö, eli yhden hänen pojistansa pappein seasta."],[13,3,"Ja sitte kuin pappi näkee merkin ihossa, ja jos karvat merkissä ovat muuttuneet valkiaksi, ja haavan paikka on nähdä matalampi kuin muu iho hänen ruumiissansa, niin se on spitalitauti, sentähden pitää papin katseleman häntä ja tuomitseman hänen saastaiseksi.","Ja sitte kuin pappi näkee merkin ihossa, ja jos karvat merkissä ovat muuttuneet valkiaksi, ja haavan paikka on nähdä matalampi kuin muu iho hänen ruumiissansa, niin se on spitalitauti, sentähden pitää papin katseleman häntä ja tuomitseman hänen saastaiseksi."],[13,4,"Mutta jos hänen ihossansa on valkea syhelmä, eikä kuitenkaan näy olevan syvemmällä muuta ihoa, ja karvat ei ole muuttuneet valkiaksi, niin pitää papin hänen sulkeman sisälle seitsemäksi päiväksi.","Mutta jos hänen ihossansa on valkea syhelmä, eikä kuitenkaan näy olevan syvemmällä muuta ihoa, ja karvat ei ole muuttuneet valkiaksi, niin pitää papin hänen sulkeman sisälle seitsemäksi päiväksi."],[13,5,"Ja seitsemäntenä päivänä katselkaan pappi häntä, jos haavat näkyvät hänessä olevan niinkuin ennekin, ja ei ole levinneet hänen ihossansa, niin papin pitää hänen jälleen toiseksi seitsemäksi päiväksi sulkeman sisälle.","Ja seitsemäntenä päivänä katselkaan pappi häntä, jos haavat näkyvät hänessä olevan niinkuin ennekin, ja ei ole levinneet hänen ihossansa, niin papin pitää hänen jälleen toiseksi seitsemäksi päiväksi sulkeman sisälle."],[13,6,"Ja koska pappi taas katselee hänen toisena seitsemäntenä päivänä ja löytää haavat rauvenneeksi, eikä levinneeksi hänen ihossansa, niin pitää papin tuomitseman hänen puhtaaksi; sillä se on syhelmä: ja pitää pesemän vaatteensa, ja niin on hän puhdas.","Ja koska pappi taas katselee hänen toisena seitsemäntenä päivänä ja löytää haavat rauvenneeksi, eikä levinneeksi hänen ihossansa, niin pitää papin tuomitseman hänen puhtaaksi; sillä se on syhelmä: ja pitää pesemän vaatteensa, ja niin on hän puhdas."],[13,7,"Mutta jos rupi leviää hänen ihossansa, sitte kuin hän on papilta katsottu ja puhtaaksi sanottu, niin hän pitää katsottaman toisen kerran papilta.","Mutta jos rupi leviää hänen ihossansa, sitte kuin hän on papilta katsottu ja puhtaaksi sanottu, niin hän pitää katsottaman toisen kerran papilta."],[13,8,"Jos siis pappi näkee, että ruvet ovat levinneet hänen ihossansa, niin pitää papin tuomitseman hänen saastaiseksi: se on spitali.","Jos siis pappi näkee, että ruvet ovat levinneet hänen ihossansa, niin pitää papin tuomitseman hänen saastaiseksi: se on spitali."],[13,9,"Mutta koska spitalin haava tulee ihmiseen, niin hän pitää vietämän papin tykö.","Mutta koska spitalin haava tulee ihmiseen, niin hän pitää vietämän papin tykö."],[13,10,"Ja koska pappi näke valkian ajoksen tulleeksi hänen ihoonsa, ja karvat vaalistuneeksi, ja elävän lihan olevan ajoksessa.","Ja koska pappi näke valkian ajoksen tulleeksi hänen ihoonsa, ja karvat vaalistuneeksi, ja elävän lihan olevan ajoksessa."],[13,11,"Niin on vanha spitali hänen ihossansa, ja sentähden pitää papin tuomitseman häntä saastaiseksi, ja ei silleen sulkeman sisälle, sillä hän on jo saastainen.","Niin on vanha spitali hänen ihossansa, ja sentähden pitää papin tuomitseman häntä saastaiseksi, ja ei silleen sulkeman sisälle, sillä hän on jo saastainen."],[13,12,"Ja jos spitali kovin leviää hänen ihossansa, ja täyttää koko ihonsa, päästä niin jalkoihin, kaiken sen jälkeen, mitä pappi näkee silmäinsä edessä.","Ja jos spitali kovin leviää hänen ihossansa, ja täyttää koko ihonsa, päästä niin jalkoihin, kaiken sen jälkeen, mitä pappi näkee silmäinsä edessä."],[13,13,"Koska pappi katsoo ja näkee spitalin peittäneeksi koko hänen ihona, niin pitää hän tuomitseman hänen puhtaaksi, sentähden että kaikki on hänessä muuttunut valkiaksi; sillä hän on puhdas.","Koska pappi katsoo ja näkee spitalin peittäneeksi koko hänen ihona, niin pitää hän tuomitseman hänen puhtaaksi, sentähden että kaikki on hänessä muuttunut valkiaksi; sillä hän on puhdas."],[13,14,"Mutta jona päivänä elävä liha hänessä näkyy, niin hän tuomitaan saastaiseksi,","Mutta jona päivänä elävä liha hänessä näkyy, niin hän tuomitaan saastaiseksi,"],[13,15,"Ja pappi nähtyänsä elävän lihan, pitää hänen tuomitseman saastaiseksi; sillä elävä liha on saastainen, ja se on spitali.","Ja pappi nähtyänsä elävän lihan, pitää hänen tuomitseman saastaiseksi; sillä elävä liha on saastainen, ja se on spitali."],[13,16,"Mutta jos se elävä liha muuttuu jälleen valkiaksi, niin pitää hänen tuleman papin tykö,","Mutta jos se elävä liha muuttuu jälleen valkiaksi, niin pitää hänen tuleman papin tykö,"],[13,17,"Ja koska pappi näkee haavat muuttuneen valkiaksi, niin papin pitää tuomitseman hänen puhtaaksi; sillä hän on puhdas.","Ja koska pappi näkee haavat muuttuneen valkiaksi, niin papin pitää tuomitseman hänen puhtaaksi; sillä hän on puhdas."],[13,18,"Ja jos jonkun ihoon tulee paisuma, ja paranee jälleen,","Ja jos jonkun ihoon tulee paisuma, ja paranee jälleen,"],[13,19,"Ja sitte siihen siaan tulee jotakin valkiaa eli punaista rakkoa, se pitää katsottaman papilta.","Ja sitte siihen siaan tulee jotakin valkiaa eli punaista rakkoa, se pitää katsottaman papilta."],[13,20,"Koska pappi näkee sen paikan matalammaksi muuta ihoa, ja karvat ovat muuttuneet valkiaksi, niin papin pitää hänen tuomitseman saastaiseksi; sillä siitä paisumasta on spitali tullut.","Koska pappi näkee sen paikan matalammaksi muuta ihoa, ja karvat ovat muuttuneet valkiaksi, niin papin pitää hänen tuomitseman saastaiseksi; sillä siitä paisumasta on spitali tullut."],[13,21,"Mutta jos pappi näkee, ettei karvat ole siinä muuttuneet valkiaksi, ja ei ole matalampi kuin muukaan iho, ja se on kadonnut, niin papin pitää sulkeman hänen sisälle seitsemäksi päiväksi.","Mutta jos pappi näkee, ettei karvat ole siinä muuttuneet valkiaksi, ja ei ole matalampi kuin muukaan iho, ja se on kadonnut, niin papin pitää sulkeman hänen sisälle seitsemäksi päiväksi."],[13,22,"Mutta jos se paljo levenee hänen ihossansa, niin pitää papin tuomitseman hänen saastaiseksi; sillä se on spitalin haava.","Mutta jos se paljo levenee hänen ihossansa, niin pitää papin tuomitseman hänen saastaiseksi; sillä se on spitalin haava."],[13,23,"Mutta jos se syhelmä pysyy siallansa, ja ei levitä itseänsä, niin se on paisuman arpi, ja papin pitää tuomitseman hänen puhtaaksi.","Mutta jos se syhelmä pysyy siallansa, ja ei levitä itseänsä, niin se on paisuman arpi, ja papin pitää tuomitseman hänen puhtaaksi."],[13,24,"Ja jos jonkun iho tulee rupiin tulen poltteesta ja polton haavat ovat punaiset taikka valkiat,","Ja jos jonkun iho tulee rupiin tulen poltteesta ja polton haavat ovat punaiset taikka valkiat,"],[13,25,"Ja pappi näkee sen karvat muuttuneeksi valkiaksi, siitä kuin palanut on, ja matalammaksi muuta ihoa, niin on spitali tullut siitä poltteesta: sentähden pitää papin tuomitseman hänen saastaiseksi; sillä se on spitalin haava.","Ja pappi näkee sen karvat muuttuneeksi valkiaksi, siitä kuin palanut on, ja matalammaksi muuta ihoa, niin on spitali tullut siitä poltteesta: sentähden pitää papin tuomitseman hänen saastaiseksi; sillä se on spitalin haava."],[13,26,"Mutta jos pappi näkee, ettei karvat palaneessa ole muuttuneet valkiaksi, eikä matalammaksi ole tullut muuta ihoa, ja on siitä kadonnut, niin pitää papin sulkeman hänen sisälle seitsemäksi päiväksi.","Mutta jos pappi näkee, ettei karvat palaneessa ole muuttuneet valkiaksi, eikä matalammaksi ole tullut muuta ihoa, ja on siitä kadonnut, niin pitää papin sulkeman hänen sisälle seitsemäksi päiväksi."],[13,27,"Ja seitsemäntenä päivänä pitää papin katseleman häntä: jos se on paljo levinnyt hänessä, niin papin pitää tuomitseman hänen saastaiseksi; sillä se on spitali.","Ja seitsemäntenä päivänä pitää papin katseleman häntä: jos se on paljo levinnyt hänessä, niin papin pitää tuomitseman hänen saastaiseksi; sillä se on spitali."],[13,28,"Mutta jos se on alallansa pysynyt palaneessa, eikä ole levinnyt hänen ihossansa, mutta on kadonnut, niin se on arpi palaneen jälkeen, ja papin pitää tuomitseman hänen puhtaaksi; sillä se on arpi palaneen jälkeen.","Mutta jos se on alallansa pysynyt palaneessa, eikä ole levinnyt hänen ihossansa, mutta on kadonnut, niin se on arpi palaneen jälkeen, ja papin pitää tuomitseman hänen puhtaaksi; sillä se on arpi palaneen jälkeen."],[13,29,"Jos mieheen eli vaimoon tulee syhelmä, päähän eli partaan,","Jos mieheen eli vaimoon tulee syhelmä, päähän eli partaan,"],[13,30,"Ja pappi katsoo sen ruven ja näkee sen matalammaksi muuta ihoa, ja karvat tulevat siitä paikasta keltaiseksi ja harvemmaksi, niin papin pitää tuomitseman sen saastaiseksi; sillä se on rupi, se on spitali päässä eli parrassa.","Ja pappi katsoo sen ruven ja näkee sen matalammaksi muuta ihoa, ja karvat tulevat siitä paikasta keltaiseksi ja harvemmaksi, niin papin pitää tuomitseman sen saastaiseksi; sillä se on rupi, se on spitali päässä eli parrassa."],[13,31,"Mutta jos pappi näkee, ettei se rupi ole matalampi muuta ihoa, ja karvat ei ole hänessä mustat, niin pitää papin sulkeman hänen, jolla rupihaava on, sisälle seitsemäksi päiväksi.","Mutta jos pappi näkee, ettei se rupi ole matalampi muuta ihoa, ja karvat ei ole hänessä mustat, niin pitää papin sulkeman hänen, jolla rupihaava on, sisälle seitsemäksi päiväksi."],[13,32,"Ja koska pappi seitsemäntenä päivänä näkee, ettei rupi ole levinnyt ihossa, eikä ole keltaisia karvoja, ja ei ole rupi matalampi nähdä muuta ihoa,","Ja koska pappi seitsemäntenä päivänä näkee, ettei rupi ole levinnyt ihossa, eikä ole keltaisia karvoja, ja ei ole rupi matalampi nähdä muuta ihoa,"],[13,33,"Pitää hänen ajeleman itsensä, kuitenkin ettei hän ajele rupea ja papin pitää hänen, jolla rupi on, sulkeman sisälle toiseksi seitsemäksi päiväksi;","Pitää hänen ajeleman itsensä, kuitenkin ettei hän ajele rupea ja papin pitää hänen, jolla rupi on, sulkeman sisälle toiseksi seitsemäksi päiväksi;"],[13,34,"Ja koska pappi seitsemäntenä päivänä näkee ruven, ja löytää, ettei rupi ole levinnyt ihossa, ja ei ole matalampi muuta ihoa, niin papin pitää tuomitseman hänen puhtaaksi, ja hänen pitää pesemän vaatteensa, ja niin puhdas oleman.","Ja koska pappi seitsemäntenä päivänä näkee ruven, ja löytää, ettei rupi ole levinnyt ihossa, ja ei ole matalampi muuta ihoa, niin papin pitää tuomitseman hänen puhtaaksi, ja hänen pitää pesemän vaatteensa, ja niin puhdas oleman."],[13,35,"Mutta jos rupi kovin levittää itsensä ihoon hänen puhdistuksensa jälkeen,","Mutta jos rupi kovin levittää itsensä ihoon hänen puhdistuksensa jälkeen,"],[13,36,"Ja pappi näkee ruven levinneeksi ihossa, niin ei pidä papin silleen kysymän, jos karvat ovat keltaiset; sillä hän on saastainen.","Ja pappi näkee ruven levinneeksi ihossa, niin ei pidä papin silleen kysymän, jos karvat ovat keltaiset; sillä hän on saastainen."],[13,37,"Jos se on silmäin edessä nähdä, että rupi on yhdellänsä ollut, ja siitä ovat mustat karvat käyneet ulos, niin rupi on parantunut, ja hän on puhdas: sentähden pitää papin hänen puhtaaksi sanoman.","Jos se on silmäin edessä nähdä, että rupi on yhdellänsä ollut, ja siitä ovat mustat karvat käyneet ulos, niin rupi on parantunut, ja hän on puhdas: sentähden pitää papin hänen puhtaaksi sanoman."],[13,38,"Ja jos miehen eli vaimon ihoon tulee valkia syhelmä,","Ja jos miehen eli vaimon ihoon tulee valkia syhelmä,"],[13,39,"Ja pappi näkee sen rauvenneeksi, niin on valkia rupi tullut hänen ihoonsa, ja hän on puhdas.","Ja pappi näkee sen rauvenneeksi, niin on valkia rupi tullut hänen ihoonsa, ja hän on puhdas."],[13,40,"Jos miehen hiukset päästä lähtevät, niin että hän tulee paljaspääksi, hän on puhdas.","Jos miehen hiukset päästä lähtevät, niin että hän tulee paljaspääksi, hän on puhdas."],[13,41,"Ja jos ne etiseltä puolelta päätä lähtevät, niin hän on otsalta paljas, ja on puhdas.","Ja jos ne etiseltä puolelta päätä lähtevät, niin hän on otsalta paljas, ja on puhdas."],[13,42,"Mutta jos joku valkea taikka punainen haava tulee paljaan päälle, niin on siihen spitali tullut paljaan pään eli otsan päälle;","Mutta jos joku valkea taikka punainen haava tulee paljaan päälle, niin on siihen spitali tullut paljaan pään eli otsan päälle;"],[13,43,"Sentähden pitää papin katsoman häntä, ja koska hän näkee valkian eli punaisen haavan tulleen paljaan pään eli otsan päälle, että se näkyy niinkuin muukin spitali ihossa,","Sentähden pitää papin katsoman häntä, ja koska hän näkee valkian eli punaisen haavan tulleen paljaan pään eli otsan päälle, että se näkyy niinkuin muukin spitali ihossa,"],[13,44,"Niin hän on spitalinen ja saastainen mies, ja papin pitää kaiketi tuomitseman hänen saastaiseksi, senkaltaisen haavan tähden hänen päässänsä.","Niin hän on spitalinen ja saastainen mies, ja papin pitää kaiketi tuomitseman hänen saastaiseksi, senkaltaisen haavan tähden hänen päässänsä."],[13,45,"Joka spitalinen on, hänen vaatteensa pitää revityt oleman, ja pää avoin, suu peitetty, ja hänen pitää huutaman: saastainen! saastainen!","Joka spitalinen on, hänen vaatteensa pitää revityt oleman, ja pää avoin, suu peitetty, ja hänen pitää huutaman: saastainen! saastainen!"],[13,46,"Niinkauvan kuin haava hänessä on, pitää hänen saastainen oleman, yksinänsä asuman ja hänen asuinsiansa ulkona leiristä oleman.","Niinkauvan kuin haava hänessä on, pitää hänen saastainen oleman, yksinänsä asuman ja hänen asuinsiansa ulkona leiristä oleman."],[13,47,"Jos jonkun vaatteeseen tulee tulee spitalin haava, olkoon se lankainen eli liinainen,","Jos jonkun vaatteeseen tulee tulee spitalin haava, olkoon se lankainen eli liinainen,"],[13,48,"Loimeen eli kuteesen, olkoon se liinainen eli villainen, elikkä nahkaan, elikkä kaikkinaiseen nahkavaatteeseen:","Loimeen eli kuteesen, olkoon se liinainen eli villainen, elikkä nahkaan, elikkä kaikkinaiseen nahkavaatteeseen:"],[13,49,"Ja jos se haava kovin vihertyy, eli paljo punertuu vaatteessa, eli nahassa, eli loimessa, eli kuteessa, eli jossakussa kappaleessa, joka nahasta tehty on, se on spitalin haava; sentähden pitää papin häntä katsoman.","Ja jos se haava kovin vihertyy, eli paljo punertuu vaatteessa, eli nahassa, eli loimessa, eli kuteessa, eli jossakussa kappaleessa, joka nahasta tehty on, se on spitalin haava; sentähden pitää papin häntä katsoman."],[13,50,"Ja koska pappi senkaltaisen haavan näkee, niin hänen pitää sen sulkeman sisälle seitsemäksi päiväksi;","Ja koska pappi senkaltaisen haavan näkee, niin hänen pitää sen sulkeman sisälle seitsemäksi päiväksi;"],[13,51,"Ja jos hän seitsemäntenä päivänä näkee että haava on levinnyt vaatteessa, loimessa eli kuteessa, nahassa, eli jossakussa kappaleessa joka nahasta tehty on, niin on se kuluttavainen spitali, ja se haava on saastainen.","Ja jos hän seitsemäntenä päivänä näkee että haava on levinnyt vaatteessa, loimessa eli kuteessa, nahassa, eli jossakussa kappaleessa joka nahasta tehty on, niin on se kuluttavainen spitali, ja se haava on saastainen."],[13,52,"Ja hänen pitää vaatteet polttaman, loimen ja kuteen, eli mikä se olis, liinainen eli lankainen, eli kaikkinainen joka nahasta tehty on, jossa senkaltainen haava on; sillä se on kuluttavainen spitali, ja pitää tulessa poltettaman.","Ja hänen pitää vaatteet polttaman, loimen ja kuteen, eli mikä se olis, liinainen eli lankainen, eli kaikkinainen joka nahasta tehty on, jossa senkaltainen haava on; sillä se on kuluttavainen spitali, ja pitää tulessa poltettaman."],[13,53,"Ja jos pappi näkee, ettei haava ole levinnyt vaatteessa, loimessa eli kuteessa, eli kaikkinaisessa kappaleessa joka nahasta on,","Ja jos pappi näkee, ettei haava ole levinnyt vaatteessa, loimessa eli kuteessa, eli kaikkinaisessa kappaleessa joka nahasta on,"],[13,54,"Niin pitää papin käskemän pestä sen, jossa haava on, ja pitää hänen sulkeman sisälle jällensä toiseksi seitsemäksi päiväksi.","Niin pitää papin käskemän pestä sen, jossa haava on, ja pitää hänen sulkeman sisälle jällensä toiseksi seitsemäksi päiväksi."],[13,55,"Ja koska pappi näkee haavan, sittekuin se pesty on, ettei haava ole muuttunut hänen silmäinsä edessä, eikä myös ole levinnyt, niin se on saastainen, ja pitää tulessa poltettaman; sillä se on syvälle itsensä laskenut, ja on sen paljaaksi kuluttanut.","Ja koska pappi näkee haavan, sittekuin se pesty on, ettei haava ole muuttunut hänen silmäinsä edessä, eikä myös ole levinnyt, niin se on saastainen, ja pitää tulessa poltettaman; sillä se on syvälle itsensä laskenut, ja on sen paljaaksi kuluttanut."],[13,56,"Jos pappi näkee, ette haava kadonnut on sittekuin se pestiin, niin hänen pitää sen repäisemän pois vaatteesta, nahasta, loimesta eli kuteesta.","Jos pappi näkee, ette haava kadonnut on sittekuin se pestiin, niin hänen pitää sen repäisemän pois vaatteesta, nahasta, loimesta eli kuteesta."],[13,57,"Ja jos se vielä sitte näkyy vaatteessa, loimessa, kuteessa eli kaikkinaisessa nahkavaatteessa, niin se on pisama, ja se pitää poltettaman tulessa ynnä sen kanssa, jossa se haava on.","Ja jos se vielä sitte näkyy vaatteessa, loimessa, kuteessa eli kaikkinaisessa nahkavaatteessa, niin se on pisama, ja se pitää poltettaman tulessa ynnä sen kanssa, jossa se haava on."],[13,58,"Mutta vaate, loimi, kude, eli kaikkinainen nahkakalu, kuin pesty on, joista haava kadonnut on; se pitää vastuudesta pestämän ja puhdas oleman.","Mutta vaate, loimi, kude, eli kaikkinainen nahkakalu, kuin pesty on, joista haava kadonnut on; se pitää vastuudesta pestämän ja puhdas oleman."],[13,59,"Tämä on sääty spitalisesta ruvesta vaatteessa, liinaisessa, lankaisessa loimessa eli kuteessa, ja kaikkinaisessa nahkavaatteessa: niitä puhtaaksi eli saastaiseksi sanoa.","Tämä on sääty spitalisesta ruvesta vaatteessa, liinaisessa, lankaisessa loimessa eli kuteessa, ja kaikkinaisessa nahkavaatteessa: niitä puhtaaksi eli saastaiseksi sanoa."],[14,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[14,2,"Ja tämä on spitalisen sääty: koska hän puhdistetaan, hän pitää tuotaman papin tykö.","Ja tämä on spitalisen sääty: koska hän puhdistetaan, hän pitää tuotaman papin tykö."],[14,3,"Ja papin pitää käymän ulos leiristä, katselemaan häntä, jos spitalin haava on parantunut spitalisesta.","Ja papin pitää käymän ulos leiristä, katselemaan häntä, jos spitalin haava on parantunut spitalisesta."],[14,4,"Ja pappi käskekään sen, joka puhdistetaan, ottaa kaksi elävää puhdasta lintua, ja sedripuuta, ja tulipunaiseksi painettua villaa, ja isoppia.","Ja pappi käskekään sen, joka puhdistetaan, ottaa kaksi elävää puhdasta lintua, ja sedripuuta, ja tulipunaiseksi painettua villaa, ja isoppia."],[14,5,"Ja pappi käskekään sen teurastaa yhden linnun saviastiassa, vuotavan veden tykönä.","Ja pappi käskekään sen teurastaa yhden linnun saviastiassa, vuotavan veden tykönä."],[14,6,"Ja ottakaan elävän linnun sedripuun kanssa, tulipunalla painetun villan ja isopin, ja kastakaan tapetun linnun vereen, vuotavan veden tykönä.","Ja ottakaan elävän linnun sedripuun kanssa, tulipunalla painetun villan ja isopin, ja kastakaan tapetun linnun vereen, vuotavan veden tykönä."],[14,7,"Ja priiskottakaan spitalista puhdistettavan päälle seitsemän kertaa: ja niin puhdistakaan hänen, ja antakaan elävän linnun lentää kedolle.","Ja priiskottakaan spitalista puhdistettavan päälle seitsemän kertaa: ja niin puhdistakaan hänen, ja antakaan elävän linnun lentää kedolle."],[14,8,"Mutta puhdistettu peskään vaatteensa, ja ajelkaan kaikki hiuksensa, ja peskään itsensä vedessä ja niin on hän puhdas. Menkään sitte leiriin, kuitenkin asukaan ulkona majastansa seitsemän päivää.","Mutta puhdistettu peskään vaatteensa, ja ajelkaan kaikki hiuksensa, ja peskään itsensä vedessä ja niin on hän puhdas. Menkään sitte leiriin, kuitenkin asukaan ulkona majastansa seitsemän päivää."],[14,9,"Ja seitsemäntenä päivänä pitää hänen ajeleman kaikki hiukset päästänsä, ja partansa ja karvat silmäkulmistansa, niin että kaikki karvat ovat ajellut, ja pitää pesemän vaatteensa, ja pesemän ihonsa vedellä, niin on hän puhdas.","Ja seitsemäntenä päivänä pitää hänen ajeleman kaikki hiukset päästänsä, ja partansa ja karvat silmäkulmistansa, niin että kaikki karvat ovat ajellut, ja pitää pesemän vaatteensa, ja pesemän ihonsa vedellä, niin on hän puhdas."],[14,10,"Ja kahdeksantena päivänä pitää hänen ottaman kaksi virheetöintä karitsaa, ja virheettömän vuosikuntaisen lampaan, niin myös kolme kymmenestä sämpyläjauhoja ruokauhriksi, öljyllä sekoitettuja, ja yhden login öljyä.","Ja kahdeksantena päivänä pitää hänen ottaman kaksi virheetöintä karitsaa, ja virheettömän vuosikuntaisen lampaan, niin myös kolme kymmenestä sämpyläjauhoja ruokauhriksi, öljyllä sekoitettuja, ja yhden login öljyä."],[14,11,"Niin pitää papin, joka puhdisti, asettaman puhdistetun ja tämän kalun, Herran eteen seurakunnan majan oven edessä.","Niin pitää papin, joka puhdisti, asettaman puhdistetun ja tämän kalun, Herran eteen seurakunnan majan oven edessä."],[14,12,"Ja papin pitää ottaman yhden karitsan, ja uhraaman vikauhriksi, öljylogin kanssa, ja pitää ne häälyttämäm häälytykseksi Herran edessä.","Ja papin pitää ottaman yhden karitsan, ja uhraaman vikauhriksi, öljylogin kanssa, ja pitää ne häälyttämäm häälytykseksi Herran edessä."],[14,13,"Ja sitte teurastaman karitsan sillä paikalla, kussa rikosuhri ja polttouhri teurastetaan, pyhässä siassa; sillä niinkuin rikosuhri, niin myös vikauhrikin on papin oma; sillä se on kaikkein pyhin.","Ja sitte teurastaman karitsan sillä paikalla, kussa rikosuhri ja polttouhri teurastetaan, pyhässä siassa; sillä niinkuin rikosuhri, niin myös vikauhrikin on papin oma; sillä se on kaikkein pyhin."],[14,14,"Ja papin pitää ottaman vikauhrin verta ja sivuman puhdistetun oikian korvan lehteen, niin myös oikian käden peukaloon, ja oikian jalan isoon varpaaseen.","Ja papin pitää ottaman vikauhrin verta ja sivuman puhdistetun oikian korvan lehteen, niin myös oikian käden peukaloon, ja oikian jalan isoon varpaaseen."],[14,15,"Ja papin pitää ottaman öljylogista ja vuodattaman papin vasempaan käteen.","Ja papin pitää ottaman öljylogista ja vuodattaman papin vasempaan käteen."],[14,16,"Ja papin pitää kastaman oikian kätensä sormen öljyyn, joka hänen vasemmassa kädessänsä on, ja priiskottaman öljyä sormellansa seitsemän kertaa Herran edessä.","Ja papin pitää kastaman oikian kätensä sormen öljyyn, joka hänen vasemmassa kädessänsä on, ja priiskottaman öljyä sormellansa seitsemän kertaa Herran edessä."],[14,17,"Vaan käteensä jääneestä öljystä pitää papin paneman puhdistetun oikian korvan lehteen, ja oikiaan peukaloon, ja oikian jalan isoon varpaaseen, vikauhrin veren päälle.","Vaan käteensä jääneestä öljystä pitää papin paneman puhdistetun oikian korvan lehteen, ja oikiaan peukaloon, ja oikian jalan isoon varpaaseen, vikauhrin veren päälle."],[14,18,"Käteensä jääneen öljyn, pitää papin paneman puhdistetun pään päälle, ja papin pitää sovittaman häntä Herran edessä.","Käteensä jääneen öljyn, pitää papin paneman puhdistetun pään päälle, ja papin pitää sovittaman häntä Herran edessä."],[14,19,"Ja papin pitää tekemän rikosuhrin, ja sovittaman puhdistetun hänen saastaisuudestansa, ja sen jälkeen teurastaman polttouhrin.","Ja papin pitää tekemän rikosuhrin, ja sovittaman puhdistetun hänen saastaisuudestansa, ja sen jälkeen teurastaman polttouhrin."],[14,20,"Ja papin pitää uhraaman polttouhrin ja ruokauhrin alttarilla, ja papin pitää sovittaman häntä, niin hän on puhdas.","Ja papin pitää uhraaman polttouhrin ja ruokauhrin alttarilla, ja papin pitää sovittaman häntä, niin hän on puhdas."],[14,21,"Jos hän on köyhä eikä ole hänellä varaa, niin ottakaan karitsan vikauhrinsa edestä häälytykseksi, sovittaakseen häntä, ja yhden kymmeneksen sämpyläjauhoja, sekoitetun öljyllä, ruokauhriksi, ja login öljyä,","Jos hän on köyhä eikä ole hänellä varaa, niin ottakaan karitsan vikauhrinsa edestä häälytykseksi, sovittaakseen häntä, ja yhden kymmeneksen sämpyläjauhoja, sekoitetun öljyllä, ruokauhriksi, ja login öljyä,"],[14,22,"Ja kaksi mettistä eli kaksi kyyhkyläisen poikaa, jotka hän voi saada: toinen olkoon rikosuhriksi, ja toinen polttouhriksi.","Ja kaksi mettistä eli kaksi kyyhkyläisen poikaa, jotka hän voi saada: toinen olkoon rikosuhriksi, ja toinen polttouhriksi."],[14,23,"Ja kantakaan sen papille kahdeksantena päivänä puhdistukseksensa, seurakunnan majan oven eteen, Herran edessä.","Ja kantakaan sen papille kahdeksantena päivänä puhdistukseksensa, seurakunnan majan oven eteen, Herran edessä."],[14,24,"Niin pitää papin ottaman vikauhrin karitsan, ja login öljyä, ja papin pitää ne häälyttämän häälytykseksi Herran edessä,","Niin pitää papin ottaman vikauhrin karitsan, ja login öljyä, ja papin pitää ne häälyttämän häälytykseksi Herran edessä,"],[14,25,"Ja teurastaman vikauhrin karitsan, ja papin pitää ottaman vikauhrin verta, ja sivuman puhdistetun oikian korvan lehteen, niin myös oikian käden peukaloon, ja oikian jalan isoon varpaaseen.","Ja teurastaman vikauhrin karitsan, ja papin pitää ottaman vikauhrin verta, ja sivuman puhdistetun oikian korvan lehteen, niin myös oikian käden peukaloon, ja oikian jalan isoon varpaaseen."],[14,26,"Ja papin pitää vuodattaman öljyä papin vasempaan käteen.","Ja papin pitää vuodattaman öljyä papin vasempaan käteen."],[14,27,"Ja papin pitää priiskottaman oikian käden sormella öljyä, joka on hänen vasemmassa kädessänsä, seitsemän kertaa Herran edessä.","Ja papin pitää priiskottaman oikian käden sormella öljyä, joka on hänen vasemmassa kädessänsä, seitsemän kertaa Herran edessä."],[14,28,"Käteensä jääneestä öljystä pitää papin panenman puhdistetun oikian korvan lehteen, ja oikian käden peukaloon, ja oikian jalan isoon varpaaseen, vikauhrin veren päälle.","Käteensä jääneestä öljystä pitää papin panenman puhdistetun oikian korvan lehteen, ja oikian käden peukaloon, ja oikian jalan isoon varpaaseen, vikauhrin veren päälle."],[14,29,"Ja käteensä jääneen öljyn pankaan papin puhdistetun pään päälle, ja sovittakoon häntä Herran edessä.","Ja käteensä jääneen öljyn pankaan papin puhdistetun pään päälle, ja sovittakoon häntä Herran edessä."],[14,30,"Ja valmistakaan mettisiä, taikka kyhkyläisen poikia, jotka hän on voinut saada,","Ja valmistakaan mettisiä, taikka kyhkyläisen poikia, jotka hän on voinut saada,"],[14,31,"Nimittäin niitä, joita hän on voinut saada: yhden rikosuhriksi ja toisen polttouhriksi, ynnä ruokauhrin kanssa; ja niin pitää papin sovittaman puhdistetun Herran edessä,","Nimittäin niitä, joita hän on voinut saada: yhden rikosuhriksi ja toisen polttouhriksi, ynnä ruokauhrin kanssa; ja niin pitää papin sovittaman puhdistetun Herran edessä,"],[14,32,"Tämä on sääty spitalisesta, joka ei voi saada sitä, mikä hänen puhdistukseensa tarvitaan.","Tämä on sääty spitalisesta, joka ei voi saada sitä, mikä hänen puhdistukseensa tarvitaan."],[14,33,"Ja Herra puhui Mosekselle ja Aaronille, sanoen:","Ja Herra puhui Mosekselle ja Aaronille, sanoen:"],[14,34,"Koska te tulette Kanaanin maalle, jonka minä annan teille omaisuudeksi, ja minä sen maan huoneesen spitalin haavan annan,","Koska te tulette Kanaanin maalle, jonka minä annan teille omaisuudeksi, ja minä sen maan huoneesen spitalin haavan annan,"],[14,35,"Niin pitää sen tuleman, jonka huone on, ja ilmoittaman papille, sanoen: minun huoneessani näkyy niinkuin (spitalin) haava;","Niin pitää sen tuleman, jonka huone on, ja ilmoittaman papille, sanoen: minun huoneessani näkyy niinkuin (spitalin) haava;"],[14,36,"Niin pitää papin käskemän heidän lakaista huoneen, ennenkuin pappi siihen menee katsomaan haavaa, ettei kaikki, jotka huoneessa ovat, saastutettaisi: sitte pitää papin menemän katselemaan huonetta.","Niin pitää papin käskemän heidän lakaista huoneen, ennenkuin pappi siihen menee katsomaan haavaa, ettei kaikki, jotka huoneessa ovat, saastutettaisi: sitte pitää papin menemän katselemaan huonetta."],[14,37,"Koska hän näkee haavan, ja löytää, että huoneen seinissä viheriäiset ja punahtavat onnet ovat, ja ovat nähdä matalammat muuta seinää;","Koska hän näkee haavan, ja löytää, että huoneen seinissä viheriäiset ja punahtavat onnet ovat, ja ovat nähdä matalammat muuta seinää;"],[14,38,"Niin lähtekään pappi huoneen ovesta, ja sulkekaan huoneen kiinni seitsemäksi päiväksi.","Niin lähtekään pappi huoneen ovesta, ja sulkekaan huoneen kiinni seitsemäksi päiväksi."],[14,39,"Ja koska pappi seitsemäntenä päivänä palajaa ja näkee haavan itsensä levittäneeksi huoneen seiniin;","Ja koska pappi seitsemäntenä päivänä palajaa ja näkee haavan itsensä levittäneeksi huoneen seiniin;"],[14,40,"Niin pitää papin käskemän heidän kangottaa ulos kiviä, joissa haava on, ja heittää niitä kaupungista ulos, saastaiseen paikkaan.","Niin pitää papin käskemän heidän kangottaa ulos kiviä, joissa haava on, ja heittää niitä kaupungista ulos, saastaiseen paikkaan."],[14,41,"Ja huone pitää sisältä kaikki ympärinsä puhtaaksi kaavittaman, ja kaavittu savi heitettämän kaupungista ulos, saastaiseen paikkaan.","Ja huone pitää sisältä kaikki ympärinsä puhtaaksi kaavittaman, ja kaavittu savi heitettämän kaupungista ulos, saastaiseen paikkaan."],[14,42,"Ja heidän pitää ottaman toiset kivet, ja paneman niiden kivein siaan, ja ottaman toisen saven, ja sivuman huoneen.","Ja heidän pitää ottaman toiset kivet, ja paneman niiden kivein siaan, ja ottaman toisen saven, ja sivuman huoneen."],[14,43,"Jos siis haava jällensä tulee, ja pakahtuu ulos huoneessa sittekuin kivet ovat kangotetut ulos, ja huone vastuudesta sivuttu;","Jos siis haava jällensä tulee, ja pakahtuu ulos huoneessa sittekuin kivet ovat kangotetut ulos, ja huone vastuudesta sivuttu;"],[14,44,"Niin pitää papin menemän sen sisälle, ja koska hän näkee haavan laskeneeksi itsensä leviämmälle huoneessa, niin on tosin kuluttuvainen spitali siinä huoneessa, ja se on saastainen.","Niin pitää papin menemän sen sisälle, ja koska hän näkee haavan laskeneeksi itsensä leviämmälle huoneessa, niin on tosin kuluttuvainen spitali siinä huoneessa, ja se on saastainen."],[14,45,"Sentähden pitää se huone särjettämän, sekä kivet että puut, ja kaikki savi huoneesta, ja vietävä kaupungista ulos, saastaiseen paikkaan.","Sentähden pitää se huone särjettämän, sekä kivet että puut, ja kaikki savi huoneesta, ja vietävä kaupungista ulos, saastaiseen paikkaan."],[14,46,"Ja se joka käy huoneessa niinkauvan kuin se teljetty on, hänen pitää oleman saastainen ehtoosen asti.","Ja se joka käy huoneessa niinkauvan kuin se teljetty on, hänen pitää oleman saastainen ehtoosen asti."],[14,47,"Ja sen joka siinä huoneessa makaa, pitää vaatteensa pesemän, ja se joka syö siinä huoneessa, pitää vaatteensa pesemän.","Ja sen joka siinä huoneessa makaa, pitää vaatteensa pesemän, ja se joka syö siinä huoneessa, pitää vaatteensa pesemän."],[14,48,"Jos myös pappi menee ja näkee, ettei haava ole laskenut itseänsä leviämmelle huoneessa, sittekuin se sivuttu on, niin sanokaan sen puhtaaksi; sillä haava on parannut.","Jos myös pappi menee ja näkee, ettei haava ole laskenut itseänsä leviämmelle huoneessa, sittekuin se sivuttu on, niin sanokaan sen puhtaaksi; sillä haava on parannut."],[14,49,"Ja pitää ottaman huoneen puhdistamiseksi kaksi lintua, niin myös sedripuuta, ja tulipunalla painetuita villoja, ja isoppia,","Ja pitää ottaman huoneen puhdistamiseksi kaksi lintua, niin myös sedripuuta, ja tulipunalla painetuita villoja, ja isoppia,"],[14,50,"Ja teurastaman toisen linnun savisessa astiassa, vuotavan veden tykönä.","Ja teurastaman toisen linnun savisessa astiassa, vuotavan veden tykönä."],[14,51,"Ja pitää ottaman sedripuun, ja isopin, ja tulipunalla painetuita villoja, ja elävän linnun, ja kastaman ne sen vereen, ja vuotavaan veteen, ja priiskottaman huoneen seitsemän kertaa,","Ja pitää ottaman sedripuun, ja isopin, ja tulipunalla painetuita villoja, ja elävän linnun, ja kastaman ne sen vereen, ja vuotavaan veteen, ja priiskottaman huoneen seitsemän kertaa,"],[14,52,"Ja puhdistaman huoneen linnun verellä, ja vuotavalla vedellä, niin myös elävällä linnulla, sedripuulla, isopilla ja tulipunalla painetulla villalla.","Ja puhdistaman huoneen linnun verellä, ja vuotavalla vedellä, niin myös elävällä linnulla, sedripuulla, isopilla ja tulipunalla painetulla villalla."],[14,53,"Ja sitte päästäkään elävän linnun lentämään kaupungista kedolle, ja sovittakaan huoneen, niin se on puhdas.","Ja sitte päästäkään elävän linnun lentämään kaupungista kedolle, ja sovittakaan huoneen, niin se on puhdas."],[14,54,"Tämä on kaikkinaisen spitalin ja syhelmän haavain sääty:","Tämä on kaikkinaisen spitalin ja syhelmän haavain sääty:"],[14,55,"Vaatteen ja huoneen spitalin,","Vaatteen ja huoneen spitalin,"],[14,56,"Paisumain, pisamain ja putkenpolttamien,","Paisumain, pisamain ja putkenpolttamien,"],[14,57,"Että pitää tiedettämän, mikä puhdas eli saastainen kunakin päivänä oleman pitää. Tämä on sääty spitalista.","Että pitää tiedettämän, mikä puhdas eli saastainen kunakin päivänä oleman pitää. Tämä on sääty spitalista."],[15,1,"Ja Herra puhui Mosekselle ja Aaronille, sanoen:","Ja Herra puhui Mosekselle ja Aaronille, sanoen:"],[15,2,"Puhukaat Israelin lapsille, ja sanokaat heille: koska miehellä on lihansa juoksu, on hän saastainen.","Puhukaat Israelin lapsille, ja sanokaat heille: koska miehellä on lihansa juoksu, on hän saastainen."],[15,3,"Ja silloin on hän saastainen siitä juoksusta, koska hänen lihansa juoksee taikka tulee tukituksi siitä vuotamisesta; niin se on saastaisuus.","Ja silloin on hän saastainen siitä juoksusta, koska hänen lihansa juoksee taikka tulee tukituksi siitä vuotamisesta; niin se on saastaisuus."],[15,4,"Jokainen vuode, jossa hän lepää, jolla on juoksu, on saastainen, ja kaikki se, jonka päällä hän istuu, saastutetaan.","Jokainen vuode, jossa hän lepää, jolla on juoksu, on saastainen, ja kaikki se, jonka päällä hän istuu, saastutetaan."],[15,5,"Ja se, joka sattuu hänen vuoteesensa, pitää pesemän vaatteensa, ja viruttaman hänensä vedellä, ja pitää oleman saastaisen ehtoosen asti.","Ja se, joka sattuu hänen vuoteesensa, pitää pesemän vaatteensa, ja viruttaman hänensä vedellä, ja pitää oleman saastaisen ehtoosen asti."],[15,6,"Se joka istuu sillä istuimella millä hän on istunut, jolla juoksu on, hänen pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti.","Se joka istuu sillä istuimella millä hän on istunut, jolla juoksu on, hänen pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti."],[15,7,"Se joka sattuu hänen lihaansa, hän peskään vaatteensa, ja viruttakaan hänensä vedellä, ja olkaan saastainen ehtoosen asti.","Se joka sattuu hänen lihaansa, hän peskään vaatteensa, ja viruttakaan hänensä vedellä, ja olkaan saastainen ehtoosen asti."],[15,8,"Jos hän sylkee puhtaan päälle, niin se pitää pesemän vaatteensa, ja viruttaman hänensä vedellä, ja oleman saastainen ehtoosen asti.","Jos hän sylkee puhtaan päälle, niin se pitää pesemän vaatteensa, ja viruttaman hänensä vedellä, ja oleman saastainen ehtoosen asti."],[15,9,"Ja koko se satula, jolla hän ajaa, pitää oleman saastainen.","Ja koko se satula, jolla hän ajaa, pitää oleman saastainen."],[15,10,"Ja se joka sattuu johonkuhun siihen, joka hänen allansa on ollut, pitää saastaisen oleman ehtoosen asti, ja joka niitä kantaa, pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti.","Ja se joka sattuu johonkuhun siihen, joka hänen allansa on ollut, pitää saastaisen oleman ehtoosen asti, ja joka niitä kantaa, pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti."],[15,11,"Ja johonka hän, jolla juoksu on, tarttuu, ennen kuin hän kätensä pesee vedellä, sen pitää vaatteensa pesemän ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti.","Ja johonka hän, jolla juoksu on, tarttuu, ennen kuin hän kätensä pesee vedellä, sen pitää vaatteensa pesemän ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti."],[15,12,"Jos hän tarttuu saviseen astiaan, se pitää rikottaman; mutta puu-astia pitää vedellä virutettaman.","Jos hän tarttuu saviseen astiaan, se pitää rikottaman; mutta puu-astia pitää vedellä virutettaman."],[15,13,"Ja tultuansa puhtaaksi lihansa juoksusta, pitää hänen lukeman seitsemän päivää puhdistuksestansa, ja pitää pesemän vaatteensa, niin myös viruttaman itsensä juoksevalla vedellä, niin hän on puhdas.","Ja tultuansa puhtaaksi lihansa juoksusta, pitää hänen lukeman seitsemän päivää puhdistuksestansa, ja pitää pesemän vaatteensa, niin myös viruttaman itsensä juoksevalla vedellä, niin hän on puhdas."],[15,14,"Ja kahdeksantena päivänä pitää hänen ottaman parin mettisiä, eli kaksi kyhkyläisen poikaa, ja pitää tuoman Herran eteen seurakunnan majan ovella, ja antaman ne papille.","Ja kahdeksantena päivänä pitää hänen ottaman parin mettisiä, eli kaksi kyhkyläisen poikaa, ja pitää tuoman Herran eteen seurakunnan majan ovella, ja antaman ne papille."],[15,15,"Ja papin pitää ne uhraaman, yhden rikosuhriksi, ja toisen polttouhriksi, ja sovittaman hänen Herran edessä hänen juoksustansa.","Ja papin pitää ne uhraaman, yhden rikosuhriksi, ja toisen polttouhriksi, ja sovittaman hänen Herran edessä hänen juoksustansa."],[15,16,"Koska miehestä siemen vuotaa unessa, hänen pitää pesemän koko ruumiinsa vedellä, ja oleman saastaisen ehtoosen asti.","Koska miehestä siemen vuotaa unessa, hänen pitää pesemän koko ruumiinsa vedellä, ja oleman saastaisen ehtoosen asti."],[15,17,"Ja kaikki vaate, ja kaikki nahka, joka senkaltaisella siemenellä tahrattu on, pitää pestämän vedellä, ja oleman saastainen ehtoosen asti.","Ja kaikki vaate, ja kaikki nahka, joka senkaltaisella siemenellä tahrattu on, pitää pestämän vedellä, ja oleman saastainen ehtoosen asti."],[15,18,"Ja vaimo, jonka tykönä senkaltainen mies makaa, jolla on siemenen juoksu, heidän pitää pesemän itsensä vedellä, ja oleman saastaiset ehtoosen asti.","Ja vaimo, jonka tykönä senkaltainen mies makaa, jolla on siemenen juoksu, heidän pitää pesemän itsensä vedellä, ja oleman saastaiset ehtoosen asti."],[15,19,"Koska vaimolla on lihansa veren juoksu, pitää hänen erinänsä oleman seitsemän päivää, ja joka häneen sattuu, sen pitää saastaisen oleman ehtoosen asti.","Koska vaimolla on lihansa veren juoksu, pitää hänen erinänsä oleman seitsemän päivää, ja joka häneen sattuu, sen pitää saastaisen oleman ehtoosen asti."],[15,20,"Ja kaikki jonka päällä hän lepää, niinkauvan kuin hän erinänsä on, pitää oleman saastainen, ja kaikki, jonka päällä hän istuu, pitää oleman saastainen.","Ja kaikki jonka päällä hän lepää, niinkauvan kuin hän erinänsä on, pitää oleman saastainen, ja kaikki, jonka päällä hän istuu, pitää oleman saastainen."],[15,21,"Ja se, joka hänen vuoteesensa sattuu, pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti.","Ja se, joka hänen vuoteesensa sattuu, pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti."],[15,22,"Ja joka tarttuu johonkuhun, jonka päällä hän on istunut, hänen pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti.","Ja joka tarttuu johonkuhun, jonka päällä hän on istunut, hänen pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti."],[15,23,"Jos jotakin osaa olla sen vuoteessa, eli istuimella, kussa hän istuu, ja joku siihen tarttuu, hänen pitää oleman saastaisen ehtoosen asti.","Jos jotakin osaa olla sen vuoteessa, eli istuimella, kussa hän istuu, ja joku siihen tarttuu, hänen pitää oleman saastaisen ehtoosen asti."],[15,24,"Ja jos joku mies leväten lepää hänen tykönänsä, siihen aikaa kuin hänen aikansa tulee, hänen pitää oleman saastaisen seitsemän päivää, ja koko hänen vuoteensa, jossa hän levännyt on, pitää oleman saastaisen.","Ja jos joku mies leväten lepää hänen tykönänsä, siihen aikaa kuin hänen aikansa tulee, hänen pitää oleman saastaisen seitsemän päivää, ja koko hänen vuoteensa, jossa hän levännyt on, pitää oleman saastaisen."],[15,25,"Jos jonkun vaimon veren juoksu vuotaa kauvan aikaa, ei vaivoin niinkauvan kuin aika on, mutta myös ylitse sen ajan, hänen pitää oleman saastaisen niinkauvan kuin se vuotaa, niinkuin hänen oikialla vuotonsa ajalla.","Jos jonkun vaimon veren juoksu vuotaa kauvan aikaa, ei vaivoin niinkauvan kuin aika on, mutta myös ylitse sen ajan, hänen pitää oleman saastaisen niinkauvan kuin se vuotaa, niinkuin hänen oikialla vuotonsa ajalla."],[15,26,"Kaikki vuode, kussa hän lepää, niinkauvan kuin hän vuotaa, pitää oleman niinkuin oikian vuotonsa ajan vuode. Ja kaikki istuin, jonka päällä hän istuu, pitää oleman saastainen, niinkuin se hänen oikiana vuotamisensa aikana on saastainen.","Kaikki vuode, kussa hän lepää, niinkauvan kuin hän vuotaa, pitää oleman niinkuin oikian vuotonsa ajan vuode. Ja kaikki istuin, jonka päällä hän istuu, pitää oleman saastainen, niinkuin se hänen oikiana vuotamisensa aikana on saastainen."],[15,27,"Se joka rupee johonkuhun niihin, hänen pitää oleman saastaisen, ja pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti.","Se joka rupee johonkuhun niihin, hänen pitää oleman saastaisen, ja pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti."],[15,28,"Koska hän on puhdas vuotamisesta, niin hänen pitää lukeman seitsemän päivää, ja sitte hänen pitää oleman puhtaan.","Koska hän on puhdas vuotamisesta, niin hänen pitää lukeman seitsemän päivää, ja sitte hänen pitää oleman puhtaan."],[15,29,"Mutta kahdeksantena päivänä pitää hänen ottaman parin mettisiä eli kaksi kyhkyläisen poikaa, ja viemän papille, seurakunnan majan oven edessä.","Mutta kahdeksantena päivänä pitää hänen ottaman parin mettisiä eli kaksi kyhkyläisen poikaa, ja viemän papille, seurakunnan majan oven edessä."],[15,30,"Ja papin pitää uhraaman yhden rikosuhriksi, ja toisen polttouhriksi, ja sovittaman hänen Herran edessä saastaisuutensa juoksusta.","Ja papin pitää uhraaman yhden rikosuhriksi, ja toisen polttouhriksi, ja sovittaman hänen Herran edessä saastaisuutensa juoksusta."],[15,31,"Niin teidän pitää eroittaman Israelin lapsia heidän saastaisuudestansa, ettei he kuolisi saastaisuudessa, koska he minun majani saastuttavat, joka heidän seassansa on.","Niin teidän pitää eroittaman Israelin lapsia heidän saastaisuudestansa, ettei he kuolisi saastaisuudessa, koska he minun majani saastuttavat, joka heidän seassansa on."],[15,32,"Tämä on sääty vuotamisesta, ja siitä, jolta (unessa) siemen vuotaa, niin että hän siitä tulee saastaiseksi,","Tämä on sääty vuotamisesta, ja siitä, jolta (unessa) siemen vuotaa, niin että hän siitä tulee saastaiseksi,"],[15,33,"Ja siitä, jolla on veren juoksu, ja siitä, jolla joku vuotaminen on, miehestä eli vaimosta: ja koska mies lepää saastaisen tykönä.","Ja siitä, jolla on veren juoksu, ja siitä, jolla joku vuotaminen on, miehestä eli vaimosta: ja koska mies lepää saastaisen tykönä."],[16,1,"Ja Herra puhui Mosekselle, sittekuin ne kaksi Aaronin poikaa kuolleet olivat; sillä uhratessansa Herran edessä kuolivat he.","Ja Herra puhui Mosekselle, sittekuin ne kaksi Aaronin poikaa kuolleet olivat; sillä uhratessansa Herran edessä kuolivat he."],[16,2,"Ja Herra sanoi Mosekselle: sano veljelles Aaronille, ettei hän joka aika mene sisimäiseen pyhään, sisälliselle puolelle esirippua armo-istuimen eteen, joka arkin päällä on, ettei hän kuolisi; sillä minä näytän minun pilvessä armo-istuimen päällä.","Ja Herra sanoi Mosekselle: sano veljelles Aaronille, ettei hän joka aika mene sisimäiseen pyhään, sisälliselle puolelle esirippua armo-istuimen eteen, joka arkin päällä on, ettei hän kuolisi; sillä minä näytän minun pilvessä armo-istuimen päällä."],[16,3,"Mutta näiden kanssa pitää Aaronin käymän pyhään sisälle: hänen pitää ottaman nuoren mullin rikosuhriksi, ja oinaan polttouhriksi,","Mutta näiden kanssa pitää Aaronin käymän pyhään sisälle: hänen pitää ottaman nuoren mullin rikosuhriksi, ja oinaan polttouhriksi,"],[16,4,"Ja pitää pukeman pyhän liinahameen yllensä ja liinaisen alusvaatteen ihonsa päälle, ja vyöttämään itsensä liinaisella vyöllä, ja paneman liinahiipan päähänsä; sillä ne ovat pyhät vaatteet, ja pitää viruttaman ihonsa vedellä, ja ne pukeman päällensä.","Ja pitää pukeman pyhän liinahameen yllensä ja liinaisen alusvaatteen ihonsa päälle, ja vyöttämään itsensä liinaisella vyöllä, ja paneman liinahiipan päähänsä; sillä ne ovat pyhät vaatteet, ja pitää viruttaman ihonsa vedellä, ja ne pukeman päällensä."],[16,5,"Ja pitää ottaman Israelin lasten joukolta kaksi kaurista rikosuhriksi ja yhden oinaan polttouhriksi.","Ja pitää ottaman Israelin lasten joukolta kaksi kaurista rikosuhriksi ja yhden oinaan polttouhriksi."],[16,6,"Ja Aaronin pitää tuoman mullin rikosuhriksensa ja sovittaman itsensä huoneinensa,","Ja Aaronin pitää tuoman mullin rikosuhriksensa ja sovittaman itsensä huoneinensa,"],[16,7,"Ja sitte ottaman ne kaksi kaurista asettaaksensa Herran eteen, seurakunnan majan ovella.","Ja sitte ottaman ne kaksi kaurista asettaaksensa Herran eteen, seurakunnan majan ovella."],[16,8,"Ja Aaronin pitää heittämän arvan kahdesta kauriista: toisen arvan Herralle, ja toisen vapaalle kauriille.","Ja Aaronin pitää heittämän arvan kahdesta kauriista: toisen arvan Herralle, ja toisen vapaalle kauriille."],[16,9,"Ja Aaronin pitää uhraaman sen kauriin, jonka päälle Herran arpa lankesi, ja valmistaman sen rikosuhriksi.","Ja Aaronin pitää uhraaman sen kauriin, jonka päälle Herran arpa lankesi, ja valmistaman sen rikosuhriksi."],[16,10,"Mutta sen kauriin, jonka päälle vapauden arpa lankesi, pitää hänen asettaman elävänä Herran eteen, että hänen pitää sovittaman sen ja päästämän sen vapaan kauriin korpeen.","Mutta sen kauriin, jonka päälle vapauden arpa lankesi, pitää hänen asettaman elävänä Herran eteen, että hänen pitää sovittaman sen ja päästämän sen vapaan kauriin korpeen."],[16,11,"Ja niin pitää Aaronin tuoman rikosuhrinsa mullin, ja sovittaman itsensä ja huoneensa, ja teurastaman sen rikosuhrin mullin edestänsä,","Ja niin pitää Aaronin tuoman rikosuhrinsa mullin, ja sovittaman itsensä ja huoneensa, ja teurastaman sen rikosuhrin mullin edestänsä,"],[16,12,"Ja ottaman astian täynnänsä tulisia hiiliä alttarilta, joka on Herran edessä, ja pivonsa täyden survottua Pyhää savua ja kantaman sisälliselle puolen esirippua,","Ja ottaman astian täynnänsä tulisia hiiliä alttarilta, joka on Herran edessä, ja pivonsa täyden survottua Pyhää savua ja kantaman sisälliselle puolen esirippua,"],[16,13,"Ja paneman sitä tulen päälle Herran eteen, niin että pyhän savun suitsu armo-istuimen peittäis, joka on todistuksen päällä, ettei hän kuolisi,","Ja paneman sitä tulen päälle Herran eteen, niin että pyhän savun suitsu armo-istuimen peittäis, joka on todistuksen päällä, ettei hän kuolisi,"],[16,14,"Ja ottaman mullin verta, priiskottaaksensa sormellansa armo-istuimen puoleen, etiselle puolelle itään päin: seitsemän kertaa pitää hänen näin sormellansa armo-istuimen edessä verta priiskottaman.","Ja ottaman mullin verta, priiskottaaksensa sormellansa armo-istuimen puoleen, etiselle puolelle itään päin: seitsemän kertaa pitää hänen näin sormellansa armo-istuimen edessä verta priiskottaman."],[16,15,"Sitte pitää hänen teurastaman kansan rikosuhrin kauriin ja kantaman hänen verestänsä esiripun sisälliselle puolelle, ja pitää tekemän sen veren kanssa, niinkuin hän teki mullin veren kanssa, ja priiskottaman sitä armo-istuimen päälle, ja armo-istuimen edessä,","Sitte pitää hänen teurastaman kansan rikosuhrin kauriin ja kantaman hänen verestänsä esiripun sisälliselle puolelle, ja pitää tekemän sen veren kanssa, niinkuin hän teki mullin veren kanssa, ja priiskottaman sitä armo-istuimen päälle, ja armo-istuimen edessä,"],[16,16,"Ja niin sovittaman pyhän, Israelin lasten riettaudesta ja heidän vääryydestänsä, kaikissa heidän synneissänsä: niin pitää myös hänen tekemän seurakunnan majalle, joka on heidän tykönänsä, keskellä heidän saastaisuuttansa.","Ja niin sovittaman pyhän, Israelin lasten riettaudesta ja heidän vääryydestänsä, kaikissa heidän synneissänsä: niin pitää myös hänen tekemän seurakunnan majalle, joka on heidän tykönänsä, keskellä heidän saastaisuuttansa."],[16,17,"Ei pidä yhdenkään ihmisen oleman seurakunnan majassa, koska hän käy sovittamaan pyhässä, siihenasti että hän sieltä käy ulos: ja pitää niin sovittaman itsensä, ja huoneensa, ja koko Israelin kansan.","Ei pidä yhdenkään ihmisen oleman seurakunnan majassa, koska hän käy sovittamaan pyhässä, siihenasti että hän sieltä käy ulos: ja pitää niin sovittaman itsensä, ja huoneensa, ja koko Israelin kansan."],[16,18,"Ja koska hän menee ulos alttarin tykö, joka on Herran edessä, pitää hänen sovittaman sen ja ottaman mullin verta, ja kauriin verta, ja sivuman alttarin sarvein päälle ympärinsä.","Ja koska hän menee ulos alttarin tykö, joka on Herran edessä, pitää hänen sovittaman sen ja ottaman mullin verta, ja kauriin verta, ja sivuman alttarin sarvein päälle ympärinsä."],[16,19,"Ja priiskottaman sormellansa verta seitsemän kertaa sen päälle ja puhdistaman ja pyhittämän sen Israelin lasten saastaisuudesta.","Ja priiskottaman sormellansa verta seitsemän kertaa sen päälle ja puhdistaman ja pyhittämän sen Israelin lasten saastaisuudesta."],[16,20,"Ja koska hän on täyttänyt pyhän ja seurakunnan majan ja alttarin sovinnon, niin pitää hänen tuoman elävän kauriin.","Ja koska hän on täyttänyt pyhän ja seurakunnan majan ja alttarin sovinnon, niin pitää hänen tuoman elävän kauriin."],[16,21,"Ja Aaronin pitää paneman molemmat kätensä elävän kauriin pään päälle, ja tunnustaman sen päällä kaikki Israelin rikokset ja heidän pahat tekonsa kaikissa heidän synneissänsä, ja ne paneman kauriin pään päälle, ja lähettämän sen jonkun soveliaan miehen kanssa korpeen:","Ja Aaronin pitää paneman molemmat kätensä elävän kauriin pään päälle, ja tunnustaman sen päällä kaikki Israelin rikokset ja heidän pahat tekonsa kaikissa heidän synneissänsä, ja ne paneman kauriin pään päälle, ja lähettämän sen jonkun soveliaan miehen kanssa korpeen:"],[16,22,"Että kauriin pitää kantaman kaikki heidän pahat tekonsa erämaahan, ja hänen pitää jättämän kauriin korpeen.","Että kauriin pitää kantaman kaikki heidän pahat tekonsa erämaahan, ja hänen pitää jättämän kauriin korpeen."],[16,23,"Ja Aaronin pitää käymän seurakunnan majaan, ja riisuman liinavaatteet yltänsä, jotka hän ennen pukenut oli käydessänsä pyhään, ja jättämän ne sinne.","Ja Aaronin pitää käymän seurakunnan majaan, ja riisuman liinavaatteet yltänsä, jotka hän ennen pukenut oli käydessänsä pyhään, ja jättämän ne sinne."],[16,24,"Ja pitää pesemän ihonsa vedellä pyhässä siassa, ja pukeman yllensä omat vaatteensa, ja menemän ulos, ja tekemän sekä oman että kansan polttouhrin, ja niin sovittaman sekä itsensä että kansan,","Ja pitää pesemän ihonsa vedellä pyhässä siassa, ja pukeman yllensä omat vaatteensa, ja menemän ulos, ja tekemän sekä oman että kansan polttouhrin, ja niin sovittaman sekä itsensä että kansan,"],[16,25,"Ja polttaman rikosuhrin lihavuuden alttarilla.","Ja polttaman rikosuhrin lihavuuden alttarilla."],[16,26,"Vaan se, joka vei sen vapaan kauriin ulos, pitää viruttaman vaatteensa, ja pesemän ihonsa vedellä, ja sitte tuleman jällensä leiriin.","Vaan se, joka vei sen vapaan kauriin ulos, pitää viruttaman vaatteensa, ja pesemän ihonsa vedellä, ja sitte tuleman jällensä leiriin."],[16,27,"Ja rikosuhrin mullin ja rikosuhrin kauriin, joidenka veri kannettiin sovinnoksi pyhään, pitää vietämän leiristä ulos, tulessa poltettaa, sekä heidän nahkansa, lihansa ja rapansa.","Ja rikosuhrin mullin ja rikosuhrin kauriin, joidenka veri kannettiin sovinnoksi pyhään, pitää vietämän leiristä ulos, tulessa poltettaa, sekä heidän nahkansa, lihansa ja rapansa."],[16,28,"Ja se joka niitä polttaa, pitää viruttaman vaatteensa, ja pesemän ihonsa vedellä, ja sitte tuleman leiriin.","Ja se joka niitä polttaa, pitää viruttaman vaatteensa, ja pesemän ihonsa vedellä, ja sitte tuleman leiriin."],[16,29,"Tämän pitää oleman teille ijankaikkisen säädyn: kymmenentenä päivänä seitsemäntenä kuukautena pitää teidän sielujanne vaivaaman, ja ei mitäkään työtä tekemän: olkoon se omainen, eli vieras, joka teidän seassanne muukalainen on.","Tämän pitää oleman teille ijankaikkisen säädyn: kymmenentenä päivänä seitsemäntenä kuukautena pitää teidän sielujanne vaivaaman, ja ei mitäkään työtä tekemän: olkoon se omainen, eli vieras, joka teidän seassanne muukalainen on."],[16,30,"Sillä sinä päivänä te sovitetaan, niin että tulette puhtaaksi: kaikista teidän synneistänne Herran edessä tulette te puhtaaksi.","Sillä sinä päivänä te sovitetaan, niin että tulette puhtaaksi: kaikista teidän synneistänne Herran edessä tulette te puhtaaksi."],[16,31,"Sentähden pitää sen oleman teille suurimman sabbatin, ja teidän pitää vaivaaman teidän sielujanne: se olkoon teille alinomainen sääty.","Sentähden pitää sen oleman teille suurimman sabbatin, ja teidän pitää vaivaaman teidän sielujanne: se olkoon teille alinomainen sääty."],[16,32,"Mutta sovinnon pitää papin tekemän, joka voideltu on, ja jonka käsi täytetty on papin virkaan hänen isänsä siaan: ja pitää pukeman yllensä liinaiset vaatteet, jotka ovat pyhät vaatteet.","Mutta sovinnon pitää papin tekemän, joka voideltu on, ja jonka käsi täytetty on papin virkaan hänen isänsä siaan: ja pitää pukeman yllensä liinaiset vaatteet, jotka ovat pyhät vaatteet."],[16,33,"Ja niin pitää hänen sovittaman kaikkein pyhimmän ja seurakunnan majan ja alttarin, niin myös papit, ja kaiken kansan pitää hänen sovittaman.","Ja niin pitää hänen sovittaman kaikkein pyhimmän ja seurakunnan majan ja alttarin, niin myös papit, ja kaiken kansan pitää hänen sovittaman."],[16,34,"Tämän pitää oleman teille alinomaisen säädyn, että sovitatte Israelin lapset kaikista heidän synneistänsä, kerran vuodessa. Ja hän teki niinkuin Herra oli käskenyt Mosekselle.","Tämän pitää oleman teille alinomaisen säädyn, että sovitatte Israelin lapset kaikista heidän synneistänsä, kerran vuodessa. Ja hän teki niinkuin Herra oli käskenyt Mosekselle."],[17,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[17,2,"Puhu Aaronille ja hänen pojillensa, ja kaikille Israelin lapsille, ja sano heille: tämä on se, minkä Herra käskenyt on, sanoen:","Puhu Aaronille ja hänen pojillensa, ja kaikille Israelin lapsille, ja sano heille: tämä on se, minkä Herra käskenyt on, sanoen:"],[17,3,"Kuka ikänänsä Israelin huoneesta teurastaa härjän, eli karitsan, eli vuohen leirissä, taikka joka teurastaa ulkona leiristä,","Kuka ikänänsä Israelin huoneesta teurastaa härjän, eli karitsan, eli vuohen leirissä, taikka joka teurastaa ulkona leiristä,"],[17,4,"Ja ei kanna seurakunnan majan oven eteen sitä, mikä Herralle uhriksi pitää tuotaman, Herran majan eteen, hänen pitää vereen vikapää oleman, niinkuin se, jonka veren vuodattanut on, ja se ihminen pitää hävitettämän kansastansa.","Ja ei kanna seurakunnan majan oven eteen sitä, mikä Herralle uhriksi pitää tuotaman, Herran majan eteen, hänen pitää vereen vikapää oleman, niinkuin se, jonka veren vuodattanut on, ja se ihminen pitää hävitettämän kansastansa."],[17,5,"Sentähden pitää Israelin lapset uhrinsa, jonka he kedolla uhrata tahtovat, Herran eteen kantaman seurakunnan majan ovella papille, ja siellä uhraaman ne kiitosuhriksi Herralle.","Sentähden pitää Israelin lapset uhrinsa, jonka he kedolla uhrata tahtovat, Herran eteen kantaman seurakunnan majan ovella papille, ja siellä uhraaman ne kiitosuhriksi Herralle."],[17,6,"Ja papin pitää priiskottaman veren Herran alttarille seurakunnan majan oven edessä, ja polttaman lihavuuden Herralle lepytyshajuksi,","Ja papin pitää priiskottaman veren Herran alttarille seurakunnan majan oven edessä, ja polttaman lihavuuden Herralle lepytyshajuksi,"],[17,7,"Ja ei millään muotoa enää uhriansa uhraaman ajattaroille, joiden kanssa he huorin tehneet ovat. Se pitää oleman heille heidän sukukunnissansa ijankaikkinen sääty.","Ja ei millään muotoa enää uhriansa uhraaman ajattaroille, joiden kanssa he huorin tehneet ovat. Se pitää oleman heille heidän sukukunnissansa ijankaikkinen sääty."],[17,8,"Sentähden pitää sinun sanoman heille: kuka ikänänsä ihminen Israelin huoneesta, eli vieras, joka teidän seassanne on muukalainen, teki uhrin eli polttouhrin,","Sentähden pitää sinun sanoman heille: kuka ikänänsä ihminen Israelin huoneesta, eli vieras, joka teidän seassanne on muukalainen, teki uhrin eli polttouhrin,"],[17,9,"Eikä sitä kanna seurakunnan majan oven eteen, että hänen Herralle sen tekemän pitäis, se ihminen pitää hävitettämän kansastansa.","Eikä sitä kanna seurakunnan majan oven eteen, että hänen Herralle sen tekemän pitäis, se ihminen pitää hävitettämän kansastansa."],[17,10,"Ja kuka ikänänsä ihminen Israelin huoneesta, eli muukalaisista, jotka teidän seassanne asuvat, syö jotakin verta, häntä vastoin minä panen minun kasvoni, ja hävitän hänen kansastansa","Ja kuka ikänänsä ihminen Israelin huoneesta, eli muukalaisista, jotka teidän seassanne asuvat, syö jotakin verta, häntä vastoin minä panen minun kasvoni, ja hävitän hänen kansastansa"],[17,11,"Sillä lihan sielu on veressä, ja minä olen sen teille antanut alttarille, että teidän sielunne pitäis sen kautta sovitettaman; sillä veri on sielun sovinto.","Sillä lihan sielu on veressä, ja minä olen sen teille antanut alttarille, että teidän sielunne pitäis sen kautta sovitettaman; sillä veri on sielun sovinto."],[17,12,"Sentähden minä olen sanonut Israelin lapsille: ei yksikään henki teidän seassanne pidä verta syömän: eikä yksikään muukalainen, joka teidän seassanne asuu, pidä verta syömän.","Sentähden minä olen sanonut Israelin lapsille: ei yksikään henki teidän seassanne pidä verta syömän: eikä yksikään muukalainen, joka teidän seassanne asuu, pidä verta syömän."],[17,13,"Ja kuka ikänä ihminen Israelin lapsista, taikka muukalainen teidän seassanne, joka saa metsän eläimen eli linnun pyydyksellä, jota syödään, hänen pitää vuodattaman sen veren, ja peittämän sen multaan.","Ja kuka ikänä ihminen Israelin lapsista, taikka muukalainen teidän seassanne, joka saa metsän eläimen eli linnun pyydyksellä, jota syödään, hänen pitää vuodattaman sen veren, ja peittämän sen multaan."],[17,14,"Sillä kaiken lihan henki on hänen verensä niinkauvan kuin se elää. Ja minä olen sanonut Israelin lapsille: ei teidän pidä yhdenkään lihan verta syömän; sillä kaiken lihan henki on hänen verensä: kuka ikänänsä sen syö, se pitää hukutettaman.","Sillä kaiken lihan henki on hänen verensä niinkauvan kuin se elää. Ja minä olen sanonut Israelin lapsille: ei teidän pidä yhdenkään lihan verta syömän; sillä kaiken lihan henki on hänen verensä: kuka ikänänsä sen syö, se pitää hukutettaman."],[17,15,"Ja kuka ikänä henki syö raatoa, taikka sitä, joka revitty on, olkoon hän kotolainen eli muukalainen, hänen pitää pesemän vaatteensa, ja viruttaman hänensä vedellä, ja oleman saastaisen ehtoosen asti: niin hän tulee puhtaaksi.","Ja kuka ikänä henki syö raatoa, taikka sitä, joka revitty on, olkoon hän kotolainen eli muukalainen, hänen pitää pesemän vaatteensa, ja viruttaman hänensä vedellä, ja oleman saastaisen ehtoosen asti: niin hän tulee puhtaaksi."],[17,16,"Jollei hän pese itsiänsä ja ihoansa viruta, niin hänen pitää itse kantaman vääryytensä.","Jollei hän pese itsiänsä ja ihoansa viruta, niin hänen pitää itse kantaman vääryytensä."],[18,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[18,2,"Puhu Israelin lapsille, ja sano heille. Minä olen Herra teidän Jumalanne.","Puhu Israelin lapsille, ja sano heille. Minä olen Herra teidän Jumalanne."],[18,3,"Ei teidän pidä tekemän Egyptin maan työn jälkeen, jossa te asuitte, ei myös teidän pidä tekemän Kanaanin maan työn jälkeen, johonka minä tiedän vien, ei teidän myös pidä heidän säädyissänsä vaeltaman.","Ei teidän pidä tekemän Egyptin maan työn jälkeen, jossa te asuitte, ei myös teidän pidä tekemän Kanaanin maan työn jälkeen, johonka minä tiedän vien, ei teidän myös pidä heidän säädyissänsä vaeltaman."],[18,4,"Vaan tehkäät minun oikeuteni, ja pitäkäät minun säätyni, vaeltaaksenne niissä; (sillä) minä olen Herra teidän Jumalanne.","Vaan tehkäät minun oikeuteni, ja pitäkäät minun säätyni, vaeltaaksenne niissä; (sillä) minä olen Herra teidän Jumalanne."],[18,5,"Sentähden pitää teidän minun säätyni pitämän ja minun oikeuteni: se ihminen, joka niitä tekee, hän elää niissä; sillä minä olen Herra.","Sentähden pitää teidän minun säätyni pitämän ja minun oikeuteni: se ihminen, joka niitä tekee, hän elää niissä; sillä minä olen Herra."],[18,6,"Ei kenenkään pidä lähimmäistä lankoansa lähestymän, hänen häpyänsä paljastaman; sillä minä olen Herra.","Ei kenenkään pidä lähimmäistä lankoansa lähestymän, hänen häpyänsä paljastaman; sillä minä olen Herra."],[18,7,"Sinun isäs häpyä, ja äitis häpyä ei sinun pidä paljastaman. Se on sinun äitis, älä siis hänen häpyänsä paljasta.","Sinun isäs häpyä, ja äitis häpyä ei sinun pidä paljastaman. Se on sinun äitis, älä siis hänen häpyänsä paljasta."],[18,8,"Ei sinun pidä paljastaman isäs emännän häpyä; sillä se on isäs häpy.","Ei sinun pidä paljastaman isäs emännän häpyä; sillä se on isäs häpy."],[18,9,"Sinun sisares häpyä, isäs tyttären, eli äitis tyttären, kotona taikka ulkona syntyneen, ei sinun pidä paljastaman heidän häpyänsä.","Sinun sisares häpyä, isäs tyttären, eli äitis tyttären, kotona taikka ulkona syntyneen, ei sinun pidä paljastaman heidän häpyänsä."],[18,10,"Ei sinun pidä paljastaman poikas tyttären, eli tyttäres tyttären häpyä; sillä se on sinun häpys.","Ei sinun pidä paljastaman poikas tyttären, eli tyttäres tyttären häpyä; sillä se on sinun häpys."],[18,11,"Ei sinun pidä paljastaman äitipuoles tyttären häpyä, joka isälles syntynyt on; sillä se on sinun sisares.","Ei sinun pidä paljastaman äitipuoles tyttären häpyä, joka isälles syntynyt on; sillä se on sinun sisares."],[18,12,"Ei sinun pidä paljastaman isäs sisaren häpyä; sillä se on isäs lähimmäinen.","Ei sinun pidä paljastaman isäs sisaren häpyä; sillä se on isäs lähimmäinen."],[18,13,"Ei sinun pidä paljastaman äitis sisaren häpyä, sillä se on sinun äitis lähimmäinen.","Ei sinun pidä paljastaman äitis sisaren häpyä, sillä se on sinun äitis lähimmäinen."],[18,14,"Ei sinun pidä paljastaman setäs häpyä, niin ettäs lähestyt hänen emäntäänsä; sillä se on sinun setäs emäntä.","Ei sinun pidä paljastaman setäs häpyä, niin ettäs lähestyt hänen emäntäänsä; sillä se on sinun setäs emäntä."],[18,15,"Ei sinun pidä paljastaman miniäs häpyä; sillä hän on poikas emäntä, sentähden ei sinun pidä hänen häpyänsä paljastaman.","Ei sinun pidä paljastaman miniäs häpyä; sillä hän on poikas emäntä, sentähden ei sinun pidä hänen häpyänsä paljastaman."],[18,16,"Ei sinun pidä paljastaman veljes emännän häpyä; sillä se on sinun veljes häpy.","Ei sinun pidä paljastaman veljes emännän häpyä; sillä se on sinun veljes häpy."],[18,17,"Ei sinun pidä sinun emäntäs ynnä hänen tyttärensä häpyä paljastaman, eikä hänen poikansa tytärtä, eli tyttären tytärtä ottaman, heidän häpyänsä paljastamaan; sillä ne ovat hänen lähimmäisensä, ja se on kauhistus.","Ei sinun pidä sinun emäntäs ynnä hänen tyttärensä häpyä paljastaman, eikä hänen poikansa tytärtä, eli tyttären tytärtä ottaman, heidän häpyänsä paljastamaan; sillä ne ovat hänen lähimmäisensä, ja se on kauhistus."],[18,18,"Ei sinun pidä myös ottaman sinun emäntäs sisarta, häntä vaivaamaan, hänen häpyänsä paljastamaan, vielä hänen eläissänsä.","Ei sinun pidä myös ottaman sinun emäntäs sisarta, häntä vaivaamaan, hänen häpyänsä paljastamaan, vielä hänen eläissänsä."],[18,19,"Vaimon tykö, niin kauvan kuin hän saastaisuutensa sairautta kärsii, ei sinun pidä lähestymän, hänen häpynsä paljastamaan.","Vaimon tykö, niin kauvan kuin hän saastaisuutensa sairautta kärsii, ei sinun pidä lähestymän, hänen häpynsä paljastamaan."],[18,20,"Ei sinun pidä myös makaaman lähimmäises emännän tykönä, häneen ryhtymän, jolla itses häneen saastutat.","Ei sinun pidä myös makaaman lähimmäises emännän tykönä, häneen ryhtymän, jolla itses häneen saastutat."],[18,21,"Ei sinun pidä siemenestäs antaman Molekille poltettaa, ettes häpäisisi sinun Jumalas nimeä; sillä minä olen Herra.","Ei sinun pidä siemenestäs antaman Molekille poltettaa, ettes häpäisisi sinun Jumalas nimeä; sillä minä olen Herra."],[18,22,"Ei sinun pidä miehenpuolen kanssa makaaman, niinkuin vaimon kanssa; sillä se on kauhistus.","Ei sinun pidä miehenpuolen kanssa makaaman, niinkuin vaimon kanssa; sillä se on kauhistus."],[18,23,"Ei sinun pidä myös eläimen kanssa makaaman, ettes itsiäs sen kanssa saastuttais. Ja ei yksikään vaimo pidä eläimeen ryhtymän, yhdistymään sen kanssa; sillä se on kauhistus.","Ei sinun pidä myös eläimen kanssa makaaman, ettes itsiäs sen kanssa saastuttais. Ja ei yksikään vaimo pidä eläimeen ryhtymän, yhdistymään sen kanssa; sillä se on kauhistus."],[18,24,"Ei teidän pidä yhdessäkään näissä itsiänne saastuttaman; sillä näissä kaikissa ovat pakanat heitänsä saastuttaneet, jotka minä ajan pois teidän edestänne.","Ei teidän pidä yhdessäkään näissä itsiänne saastuttaman; sillä näissä kaikissa ovat pakanat heitänsä saastuttaneet, jotka minä ajan pois teidän edestänne."],[18,25,"Ja maa on sillä saastutettu, ja minä etsiskelen sen pahat teot, niin että sen maan pitää asujansa oksentaman.","Ja maa on sillä saastutettu, ja minä etsiskelen sen pahat teot, niin että sen maan pitää asujansa oksentaman."],[18,26,"Sentähden pitäkäät minun säätyni ja oikeuteni, ja älkäät näistä kauhistuksista yhtäkään tehkö: ei omainen, eikä vieras, joka teidän seassanne muukalainen on.","Sentähden pitäkäät minun säätyni ja oikeuteni, ja älkäät näistä kauhistuksista yhtäkään tehkö: ei omainen, eikä vieras, joka teidän seassanne muukalainen on."],[18,27,"Sillä kaikkia näitä kauhistuksia ovat tämän maan kansat tehneet, jotka teidän edellänne olivat, ja ovat maan saastuttaneet,","Sillä kaikkia näitä kauhistuksia ovat tämän maan kansat tehneet, jotka teidän edellänne olivat, ja ovat maan saastuttaneet,"],[18,28,"Ettei se maa myös teitä oksentaisi, jos te sitä saastutatte, niinkuin se on oksentanut kansan, joka teidän edellänne oli.","Ettei se maa myös teitä oksentaisi, jos te sitä saastutatte, niinkuin se on oksentanut kansan, joka teidän edellänne oli."],[18,29,"Sillä kuka ikänänsä näitä kauhistuksia tekee, sen sielu pitää hävitettämän kansastansa.","Sillä kuka ikänänsä näitä kauhistuksia tekee, sen sielu pitää hävitettämän kansastansa."],[18,30,"Sentähden pitäkäät minun käskyni, ettette tekisi kauhistavaisten tapain jälkeen, joita ne tekivät, jotka teidän edellänne olivat: ettette itsiänne niillä saastuttaisi; sillä minä olen Herra teidän Jumalanne.","Sentähden pitäkäät minun käskyni, ettette tekisi kauhistavaisten tapain jälkeen, joita ne tekivät, jotka teidän edellänne olivat: ettette itsiänne niillä saastuttaisi; sillä minä olen Herra teidän Jumalanne."],[19,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[19,2,"Puhu koko Israelin lasten joukolle, ja sano heille: teidän pitää oleman pyhät; sillä minä olen pyhä, Herra teidän Jumalanne.","Puhu koko Israelin lasten joukolle, ja sano heille: teidän pitää oleman pyhät; sillä minä olen pyhä, Herra teidän Jumalanne."],[19,3,"Jokainen peljätkään äitiänsä ja isäänsä, ja pitäkäät minun sabbatini; sillä minä olen Herra teidän Jumalanne.","Jokainen peljätkään äitiänsä ja isäänsä, ja pitäkäät minun sabbatini; sillä minä olen Herra teidän Jumalanne."],[19,4,"Ei teidän pidä teitänne kääntämän epäjumalain tykö, ja ei pidä teidän tekemän teillenne valetuita jumalia; sillä minä olen Herra teidän Jumalanne.","Ei teidän pidä teitänne kääntämän epäjumalain tykö, ja ei pidä teidän tekemän teillenne valetuita jumalia; sillä minä olen Herra teidän Jumalanne."],[19,5,"Ja koska te Herralle teette kiitosuhria, niin teidän pitää uhraaman, että se teiltä otollinen olis.","Ja koska te Herralle teette kiitosuhria, niin teidän pitää uhraaman, että se teiltä otollinen olis."],[19,6,"Ja se pitää syötämän sinä päivänä, jona te uhraatte, ja toisena päivänä; mutta mitä tähteeksi jää kolmanneksi päiväksi, pitää tulella poltettaman.","Ja se pitää syötämän sinä päivänä, jona te uhraatte, ja toisena päivänä; mutta mitä tähteeksi jää kolmanneksi päiväksi, pitää tulella poltettaman."],[19,7,"Jos joku sitä kuitenkin syö kolmantena päivänä, niin on se kauhistus, eikä ole otollinen.","Jos joku sitä kuitenkin syö kolmantena päivänä, niin on se kauhistus, eikä ole otollinen."],[19,8,"Ja joka siitä syö, sen pitää kantaman vääryytensä; sillä hän on Herran pyhän riivannut, ja se sielu pitää hävitettämän kansastansa.","Ja joka siitä syö, sen pitää kantaman vääryytensä; sillä hän on Herran pyhän riivannut, ja se sielu pitää hävitettämän kansastansa."],[19,9,"Koska te elon leikkaatte maastanne, ei sinun pidä tyynni peltos kulmia leikkaaman, ja ei elos päitä noukkiman.","Koska te elon leikkaatte maastanne, ei sinun pidä tyynni peltos kulmia leikkaaman, ja ei elos päitä noukkiman."],[19,10,"Ei pidä sinun myös tyynni korjaaman viinamäkiäs, eli noukkiman varisseita marjoja, vaan jättämän ne vaivaisille ja muukalaisille; sillä minä olen Herra teidän Jumalanne.","Ei pidä sinun myös tyynni korjaaman viinamäkiäs, eli noukkiman varisseita marjoja, vaan jättämän ne vaivaisille ja muukalaisille; sillä minä olen Herra teidän Jumalanne."],[19,11,"Ei teidän pidä varastaman, eli valehteleman, eli pettämän toinen toistanne.","Ei teidän pidä varastaman, eli valehteleman, eli pettämän toinen toistanne."],[19,12,"Ei teidän pidä väärin vannoman minun nimeeni, ja häpäisemän sinun Jumalas nimeä; sillä minä olen Herra.","Ei teidän pidä väärin vannoman minun nimeeni, ja häpäisemän sinun Jumalas nimeä; sillä minä olen Herra."],[19,13,"Ei sinun pidä tekemän lähimmäiselles vääryyttä, eli ryöväämän häntä. Sinun päivämiehes palkka ei pidä oleman sinun tykönäs huomiseen asti.","Ei sinun pidä tekemän lähimmäiselles vääryyttä, eli ryöväämän häntä. Sinun päivämiehes palkka ei pidä oleman sinun tykönäs huomiseen asti."],[19,14,"Ei sinun pidä kuuroja kirooman, ei sinun pidä myös paneman sokian eteen jotakin, johonka hän kompastuis. Vaan sinun pitää pelkäämän sinun Jumalaas; sillä minä olen Herra.","Ei sinun pidä kuuroja kirooman, ei sinun pidä myös paneman sokian eteen jotakin, johonka hän kompastuis. Vaan sinun pitää pelkäämän sinun Jumalaas; sillä minä olen Herra."],[19,15,"Ei teidän pidä vääryyttä tekemän tuomiossa, ei armaitseman köyhää, eikä kunnioitseman voimallista, mutta tuomitseman lähimmäises oikein.","Ei teidän pidä vääryyttä tekemän tuomiossa, ei armaitseman köyhää, eikä kunnioitseman voimallista, mutta tuomitseman lähimmäises oikein."],[19,16,"Ei sinun pidä oleman panettelian sinun kansas seassa. Ei sinun pidä myös asettaman sinuas lähimmäises verta vastaan; sillä minä olen Herra.","Ei sinun pidä oleman panettelian sinun kansas seassa. Ei sinun pidä myös asettaman sinuas lähimmäises verta vastaan; sillä minä olen Herra."],[19,17,"Ei sinun pidä vihaaman veljeäs sinun sydämessäs; vaan sinun pitää kaiketi nuhteleman lähimmäistäs, ettes vikapääksi tulisi hänen tähtensä.","Ei sinun pidä vihaaman veljeäs sinun sydämessäs; vaan sinun pitää kaiketi nuhteleman lähimmäistäs, ettes vikapääksi tulisi hänen tähtensä."],[19,18,"Ei sinun pidä kostaman, eikä vihaaman kansas lapsia. Sinun pitää rakastaman lähimmäistäs, niinkuin itse sinuas; sillä minä olen Herra.","Ei sinun pidä kostaman, eikä vihaaman kansas lapsia. Sinun pitää rakastaman lähimmäistäs, niinkuin itse sinuas; sillä minä olen Herra."],[19,19,"Minun säätyni pitää teidän pitämän. Ei sinun pidä antaman karjas sekoittaa heitänsä muiden eläinten laihin. Ja älä kylvä peltoas sekoitetulla siemenellä. Ja ei yksikään vaate pidä tuleman sinun ylles, joka villaisesta ja liinaisesta kudottu on.","Minun säätyni pitää teidän pitämän. Ei sinun pidä antaman karjas sekoittaa heitänsä muiden eläinten laihin. Ja älä kylvä peltoas sekoitetulla siemenellä. Ja ei yksikään vaate pidä tuleman sinun ylles, joka villaisesta ja liinaisesta kudottu on."],[19,20,"Jos mies makaa vaimon tykönä ja ryhtyy häneen, ja se on orja, ja jo on toiselta maattu, kuitenkaan ei ole irrallensa eli vapaaksi laskettu, se pitää suomittaman, vaan ei pidä heidän kuoleman, sillä ei hän ollut vapaa.","Jos mies makaa vaimon tykönä ja ryhtyy häneen, ja se on orja, ja jo on toiselta maattu, kuitenkaan ei ole irrallensa eli vapaaksi laskettu, se pitää suomittaman, vaan ei pidä heidän kuoleman, sillä ei hän ollut vapaa."],[19,21,"Mutta miehen pitää tuoman Herralle vikansa edestä oinaan vikauhriksi, seurakunnan majan oven eteen.","Mutta miehen pitää tuoman Herralle vikansa edestä oinaan vikauhriksi, seurakunnan majan oven eteen."],[19,22,"Ja papin pitää sovittaman hänen vikauhrinsa oinaalla Herran edessä siitä rikoksesta, jolla hän on rikkonut; niin hänelle (Jumalalta) armo tapahtuu hänen rikoksestansa, jolla hän rikkonut on.","Ja papin pitää sovittaman hänen vikauhrinsa oinaalla Herran edessä siitä rikoksesta, jolla hän on rikkonut; niin hänelle (Jumalalta) armo tapahtuu hänen rikoksestansa, jolla hän rikkonut on."],[19,23,"Koska te tulette siihen maahan ja istutatte kaikkinaisia puita, joita syödään, pitää teidän leikkaaman pois niiden hedelmän esinahan: kolme vuotta pitää teidän pitämän heitä ympärileikkaamatoinna, niin ettette syö niistä;","Koska te tulette siihen maahan ja istutatte kaikkinaisia puita, joita syödään, pitää teidän leikkaaman pois niiden hedelmän esinahan: kolme vuotta pitää teidän pitämän heitä ympärileikkaamatoinna, niin ettette syö niistä;"],[19,24,"Vaan neljäntenä vuonna pitää kaikki heidän hedelmänsä pyhitettämän kiitokseksi Herralle.","Vaan neljäntenä vuonna pitää kaikki heidän hedelmänsä pyhitettämän kiitokseksi Herralle."],[19,25,"Viidentenä vuonna pitää teidän hedelmän syömän, ja kokooman sisälle tulon; sillä minä olen Herra teidän Jumalanne.","Viidentenä vuonna pitää teidän hedelmän syömän, ja kokooman sisälle tulon; sillä minä olen Herra teidän Jumalanne."],[19,26,"Ei teidän pidä mitään syömän veren kanssa. Ei teidän pidä totteleman aavistuksia eli taikauksia.","Ei teidän pidä mitään syömän veren kanssa. Ei teidän pidä totteleman aavistuksia eli taikauksia."],[19,27,"Ei teidän pidä keritsemän paljaaksi päänne lakea ympärinsä, ja ei tyynni ajeleman partaanne.","Ei teidän pidä keritsemän paljaaksi päänne lakea ympärinsä, ja ei tyynni ajeleman partaanne."],[19,28,"Ei teidän pidä leikkaaman ihoanne kuolleen tähden, eli piirusteleman kirjoituksia päällenne; sillä minä olen Herra.","Ei teidän pidä leikkaaman ihoanne kuolleen tähden, eli piirusteleman kirjoituksia päällenne; sillä minä olen Herra."],[19,29,"Ei sinun pidä salliman tytärtäs porttona olla, ettei maa tottuisi haureuteen ja tulisi täyteen kauhistusta.","Ei sinun pidä salliman tytärtäs porttona olla, ettei maa tottuisi haureuteen ja tulisi täyteen kauhistusta."],[19,30,"Pitäkäät minun pyhäpäiväni, ja peljätkäät minun pyhääni; sillä minä olen Herra.","Pitäkäät minun pyhäpäiväni, ja peljätkäät minun pyhääni; sillä minä olen Herra."],[19,31,"Ei teidän pidä kääntämän teitänne tietäjäin tykö, ja älkäät kysykö velhoilta, ettette saastuisi heistä; sillä minä olen Herra teidän Jumalanne.","Ei teidän pidä kääntämän teitänne tietäjäin tykö, ja älkäät kysykö velhoilta, ettette saastuisi heistä; sillä minä olen Herra teidän Jumalanne."],[19,32,"Harmaapään edessä pitää sinun nouseman, ja kunnioittaman vanhaa, ja pelkäämän Jumalaas; sillä minä olen Herra.","Harmaapään edessä pitää sinun nouseman, ja kunnioittaman vanhaa, ja pelkäämän Jumalaas; sillä minä olen Herra."],[19,33,"Jos joku muukalainen on sinun tykönäs teidän maallanne asuva, ei teidän pidä sitä ryöstämän.","Jos joku muukalainen on sinun tykönäs teidän maallanne asuva, ei teidän pidä sitä ryöstämän."],[19,34,"Hänen pitää asuman teidän tykönänne, niinkuin omainen teidän seassanne. Ja sinun pitää rakastaman häntä, niinkuin itse sinuas; sillä te olitte myös muukalaiset Egyptin maalla. Minä olen Herra teidän Jumalanne.","Hänen pitää asuman teidän tykönänne, niinkuin omainen teidän seassanne. Ja sinun pitää rakastaman häntä, niinkuin itse sinuas; sillä te olitte myös muukalaiset Egyptin maalla. Minä olen Herra teidän Jumalanne."],[19,35,"Ei pidä teidän vääryyttä tekemän tuomiolla: kyynärällä, vaalla ja mitalla.","Ei pidä teidän vääryyttä tekemän tuomiolla: kyynärällä, vaalla ja mitalla."],[19,36,"Oikia vaaka, oikia leiviskä, oikia vakka, oikia kannu pitää oleman teidän tykönänne; sillä minä olen Herra teidän Jumalanne, joka teitä olen johdattanut Egyptin maalta:","Oikia vaaka, oikia leiviskä, oikia vakka, oikia kannu pitää oleman teidän tykönänne; sillä minä olen Herra teidän Jumalanne, joka teitä olen johdattanut Egyptin maalta:"],[19,37,"Että teidän pitää pitämän ja tekemän kaikki minun säätyni, ja kaikki minun oikeuteni; sillä minä olen Herra.","Että teidän pitää pitämän ja tekemän kaikki minun säätyni, ja kaikki minun oikeuteni; sillä minä olen Herra."],[20,1,"Ja Herra puhui Mosekselle; sanoen:","Ja Herra puhui Mosekselle; sanoen:"],[20,2,"Sano myös Israelin lapsille: kuka ikänänsä Israelin lapsista, eli muukalaisista, joka Israelin lasten seassa asuu, siemenestänsä Molekille antaa, sen pitää totisesti kuoleman: maan kansan pitää häntä kivittämän kuoliaaksi.","Sano myös Israelin lapsille: kuka ikänänsä Israelin lapsista, eli muukalaisista, joka Israelin lasten seassa asuu, siemenestänsä Molekille antaa, sen pitää totisesti kuoleman: maan kansan pitää häntä kivittämän kuoliaaksi."],[20,3,"Ja minä asetan minun kasvoni sitä ihmistä vastaan, ja hävitän hänen kansastansa, että hän Molekille siemenestänsä antanut ja minun pyhäni saastuttanut on, ja minun pyhää nimeäni häväissyt.","Ja minä asetan minun kasvoni sitä ihmistä vastaan, ja hävitän hänen kansastansa, että hän Molekille siemenestänsä antanut ja minun pyhäni saastuttanut on, ja minun pyhää nimeäni häväissyt."],[20,4,"Ja jos maan kansa sitä ihmistä säästää, joka siemenestänsä Molekille antanut on, niin ettei he sitä surmaa,","Ja jos maan kansa sitä ihmistä säästää, joka siemenestänsä Molekille antanut on, niin ettei he sitä surmaa,"],[20,5,"Niin minä kuitenkin sitä ihmistä vastaan minun kasvoni asetan, ja hänen sukuansa vastaan, ja hävitän sen ja kaikki jotka hänen perässänsä Molekin kanssa huorin tehneet ovat, heidän kansastansa.","Niin minä kuitenkin sitä ihmistä vastaan minun kasvoni asetan, ja hänen sukuansa vastaan, ja hävitän sen ja kaikki jotka hänen perässänsä Molekin kanssa huorin tehneet ovat, heidän kansastansa."],[20,6,"Jos joku sielu hänensä noitain ja tietäjäin tykö kääntää, huorin tekemään heidän kanssansa, niin minä kasvoni asetan sitä sielua vastaan, ja hävitän sen kansastansa.","Jos joku sielu hänensä noitain ja tietäjäin tykö kääntää, huorin tekemään heidän kanssansa, niin minä kasvoni asetan sitä sielua vastaan, ja hävitän sen kansastansa."],[20,7,"Sentähden pyhittäkäät teitänne, ja olkaat pyhät; sillä minä olen Herra teidän Jumalanne.","Sentähden pyhittäkäät teitänne, ja olkaat pyhät; sillä minä olen Herra teidän Jumalanne."],[20,8,"Ja pitäkäät minun säätyni, ja tehkäät niitä; sillä minä olen Herra, joka teitä pyhitän.","Ja pitäkäät minun säätyni, ja tehkäät niitä; sillä minä olen Herra, joka teitä pyhitän."],[20,9,"Kuka ikänänsä isäänsä ja äitiänsä kiroo, sen pitää totisesti kuoleman, että hän isäänsä ja äitiänsä kironnut on: hänen verensä olkoon hänen päällänsä.","Kuka ikänänsä isäänsä ja äitiänsä kiroo, sen pitää totisesti kuoleman, että hän isäänsä ja äitiänsä kironnut on: hänen verensä olkoon hänen päällänsä."],[20,10,"Joka huorin tekee jonkun miehen aviopuolison kanssa, se joka lähimmäisensä emännän kanssa huorin tekee, pitää totisesti kuoletettaman, sekä huorintekiä, että huora.","Joka huorin tekee jonkun miehen aviopuolison kanssa, se joka lähimmäisensä emännän kanssa huorin tekee, pitää totisesti kuoletettaman, sekä huorintekiä, että huora."],[20,11,"Jos joku isänsä emännän tykönä makaa, niin että hän isänsä hävyn paljastanut on, he molemmat pitää totisesti kuoleman: heidän verensä olkoon heidän päällänsä.","Jos joku isänsä emännän tykönä makaa, niin että hän isänsä hävyn paljastanut on, he molemmat pitää totisesti kuoleman: heidän verensä olkoon heidän päällänsä."],[20,12,"Jos joku miniänsä tykönä makaa, niin he molemmat pitää totisesti kuoleman; sillä he ovat kauhistuksen tehneet: heidän verensä olkoon heidän päällänsä.","Jos joku miniänsä tykönä makaa, niin he molemmat pitää totisesti kuoleman; sillä he ovat kauhistuksen tehneet: heidän verensä olkoon heidän päällänsä."],[20,13,"Jos joku miehenpuolen kanssa makaa, niinkuin jonkun vaimon kanssa, he ovat kauhistuksen tehneet, heidän pitää molemmat totisesti kuoleman: heidän verensä olkoon heidän päällänsä.","Jos joku miehenpuolen kanssa makaa, niinkuin jonkun vaimon kanssa, he ovat kauhistuksen tehneet, heidän pitää molemmat totisesti kuoleman: heidän verensä olkoon heidän päällänsä."],[20,14,"Jos joku nai vaimon ja sen äidin, hän on kauhistuksen tehnyt: se pitää tulella poltettaman, ja ne ynnä molemmat, ettei yhtään kauhistusta olisi teidän seassanne.","Jos joku nai vaimon ja sen äidin, hän on kauhistuksen tehnyt: se pitää tulella poltettaman, ja ne ynnä molemmat, ettei yhtään kauhistusta olisi teidän seassanne."],[20,15,"Jos joku eläimen kanssa makaa, sen pitää totisesti kuoleman, ja se eläin pitää tapettaman.","Jos joku eläimen kanssa makaa, sen pitää totisesti kuoleman, ja se eläin pitää tapettaman."],[20,16,"Jos joku vaimo johonkuhun eläimeen ryhtyy, makaamaan sen kanssa, niin sinun pitää tappaman sekä vaimon, että eläimen; heidän pitää totisesti kuoleman: heidän verensä olkoon heidän päällänsä.","Jos joku vaimo johonkuhun eläimeen ryhtyy, makaamaan sen kanssa, niin sinun pitää tappaman sekä vaimon, että eläimen; heidän pitää totisesti kuoleman: heidän verensä olkoon heidän päällänsä."],[20,17,"Jos joku sisarensa nai, isänsä eli äitinsä tyttären, ja hänen häpynsä näkee, ja se näkee hänen häpynsä, se on kauhistus: ne pitää hävitettämän sukunsa kansan edessä: sillä hän on sisarensa hävyn paljastanut, hänen pitää pahuutensa kantaman.","Jos joku sisarensa nai, isänsä eli äitinsä tyttären, ja hänen häpynsä näkee, ja se näkee hänen häpynsä, se on kauhistus: ne pitää hävitettämän sukunsa kansan edessä: sillä hän on sisarensa hävyn paljastanut, hänen pitää pahuutensa kantaman."],[20,18,"Jos joku mies jonkun vaimon tykönä makaa hänen sairautensa aikana, ja paljastaa hänen häpynsä, ja avaa hänen lähteensä, ja vaimo paljastaa verensä lähteen: ne molemmat pitää hävitettämän heidän kansastansa.","Jos joku mies jonkun vaimon tykönä makaa hänen sairautensa aikana, ja paljastaa hänen häpynsä, ja avaa hänen lähteensä, ja vaimo paljastaa verensä lähteen: ne molemmat pitää hävitettämän heidän kansastansa."],[20,19,"Sinun äitis sisaren häpyä ja sinun isäs sisaren häpyä ei sinun pidä paljastaman; sillä se on lähimmäisensä paljastanut, ja ne pitää pahuutensa kantaman.","Sinun äitis sisaren häpyä ja sinun isäs sisaren häpyä ei sinun pidä paljastaman; sillä se on lähimmäisensä paljastanut, ja ne pitää pahuutensa kantaman."],[20,20,"Jos joku setänsä emännän kanssa makaa, hän on setänsä hävyn paljastanut: ne pitää rikoksensa kantaman. Lapsetonna heidän pitää kuoleman.","Jos joku setänsä emännän kanssa makaa, hän on setänsä hävyn paljastanut: ne pitää rikoksensa kantaman. Lapsetonna heidän pitää kuoleman."],[20,21,"Jos joku veljensä emännän ottaa, se on häpiällinen työ: heidän pitää lapsetonna oleman, että hän on veljensä hävyn paljastanut.","Jos joku veljensä emännän ottaa, se on häpiällinen työ: heidän pitää lapsetonna oleman, että hän on veljensä hävyn paljastanut."],[20,22,"Niin pitäkäät nyt kaikki minun säätyni, ja kaikki minun oikeuteni, ja tehkäät ne, ettei maa teitä oksentaisi, johon minä teidät vien asumaan.","Niin pitäkäät nyt kaikki minun säätyni, ja kaikki minun oikeuteni, ja tehkäät ne, ettei maa teitä oksentaisi, johon minä teidät vien asumaan."],[20,23,"Ja älkäät vaeltako pakanain säädyissä, jotka minä teidän edeltänne olen ajava ulos; sillä kaikkia näitä he ovat tehneet, ja minä olen kauhistunut heitä.","Ja älkäät vaeltako pakanain säädyissä, jotka minä teidän edeltänne olen ajava ulos; sillä kaikkia näitä he ovat tehneet, ja minä olen kauhistunut heitä."],[20,24,"Mutta teille sanon minä: teidän pitää omistaman heidän maansa; sillä minä annan teille sen perimiseksi, sen maan, jossa rieskaa ja hunajaa vuotaa. Minä olen Herra teidän Jumalanne, joka olen teitä eroittanut muista kansoista.","Mutta teille sanon minä: teidän pitää omistaman heidän maansa; sillä minä annan teille sen perimiseksi, sen maan, jossa rieskaa ja hunajaa vuotaa. Minä olen Herra teidän Jumalanne, joka olen teitä eroittanut muista kansoista."],[20,25,"Että teidän pitää myös eroittaman puhtaat eläimet saastaisista, ja saastaiset linnut puhtaista, ja ei saastuttaman teidän sielujanne eläimissä, linnuissa ja kaikissa, mitkä maalla matelevat, jotka minä teille eroittanut olen, että ne ovat saastaiset.","Että teidän pitää myös eroittaman puhtaat eläimet saastaisista, ja saastaiset linnut puhtaista, ja ei saastuttaman teidän sielujanne eläimissä, linnuissa ja kaikissa, mitkä maalla matelevat, jotka minä teille eroittanut olen, että ne ovat saastaiset."],[20,26,"Sentähden pitää teidän oleman minulle pyhät, sillä minä Herra olen pyhä, ja olen teitä eroittanut muista kansoista, että teidän pitäis oleman minun omani.","Sentähden pitää teidän oleman minulle pyhät, sillä minä Herra olen pyhä, ja olen teitä eroittanut muista kansoista, että teidän pitäis oleman minun omani."],[20,27,"Jos joku mies eli vaimo noidaksi eli tietäjäksi löydetään, ne pitää totisesti kuoleman, heidän pitää ne kivittämän, heidän verensä olkoon heidän päällänsä.","Jos joku mies eli vaimo noidaksi eli tietäjäksi löydetään, ne pitää totisesti kuoleman, heidän pitää ne kivittämän, heidän verensä olkoon heidän päällänsä."],[21,1,"Ja Herra sanoi Mosekselle: puhu papeille Aaronin pojille ja sano heille: papin ei pidä itsiänsä saastuttaman yhdessäkään kuolleessa kansastansa;","Ja Herra sanoi Mosekselle: puhu papeille Aaronin pojille ja sano heille: papin ei pidä itsiänsä saastuttaman yhdessäkään kuolleessa kansastansa;"],[21,2,"Vaan hänen suvussansa, joka on hänen lähimmäisensä: niinkuin hänen äitinsä, isänsä, poikansa, tyttärensä ja veljensä,","Vaan hänen suvussansa, joka on hänen lähimmäisensä: niinkuin hänen äitinsä, isänsä, poikansa, tyttärensä ja veljensä,"],[21,3,"Ja sisarensa, joka neitsy on, joka hänen tykönänsä on, ja ei yhdenkään miehen emäntänä ollut ole: niissä mahtaa hän saastuttaa itsensä.","Ja sisarensa, joka neitsy on, joka hänen tykönänsä on, ja ei yhdenkään miehen emäntänä ollut ole: niissä mahtaa hän saastuttaa itsensä."],[21,4,"Ei hänen pidä saastuttaman itsiänsä, että hän on esimies kansassansa, ettei hän itsiänsä halventaisi.","Ei hänen pidä saastuttaman itsiänsä, että hän on esimies kansassansa, ettei hän itsiänsä halventaisi."],[21,5,"Ei heidän pidä paljaaksi ajeleman päälakiansa, eli keritsemään partansa vieriä, eikä ihoonsa merkkejä leikkaaman.","Ei heidän pidä paljaaksi ajeleman päälakiansa, eli keritsemään partansa vieriä, eikä ihoonsa merkkejä leikkaaman."],[21,6,"Heidän pitää Jumalallensa pyhät oleman, ja ei häpäisemän Jumalansa nimeä; sillä he uhraavat Herran tuliuhria, Jumalansa leipää; sentähden pitää heidän oleman pyhät.","Heidän pitää Jumalallensa pyhät oleman, ja ei häpäisemän Jumalansa nimeä; sillä he uhraavat Herran tuliuhria, Jumalansa leipää; sentähden pitää heidän oleman pyhät."],[21,7,"Ei heidän pidä naiman porttoa, eli muilta maattua, eli mieheltänsä hyljättyä ottaman; sillä hän on pyhä Jumalallensa.","Ei heidän pidä naiman porttoa, eli muilta maattua, eli mieheltänsä hyljättyä ottaman; sillä hän on pyhä Jumalallensa."],[21,8,"Sentähden pitää sinun pyhittämän hänen, että hän uhraa sinun Jumalas leipää: hänen pitää oleman sinulle pyhän; sillä minä Herra olen pyhä, joka teidät pyhitän.","Sentähden pitää sinun pyhittämän hänen, että hän uhraa sinun Jumalas leipää: hänen pitää oleman sinulle pyhän; sillä minä Herra olen pyhä, joka teidät pyhitän."],[21,9,"Jos papin tytär rupee salavuoteiseksi, se pitää tulessa poltettaman; sillä hän on häväissyt isänsä.","Jos papin tytär rupee salavuoteiseksi, se pitää tulessa poltettaman; sillä hän on häväissyt isänsä."],[21,10,"Joka ylimmäinen pappi on veljeinsä seassa, jonka pään päälle voidellusöljy vuodatettu, ja käsi täytetty on, että hän vaatteesen puetetaan: ei pidä sen paljastaman päätänsä, ja ei leikkaaman rikki vaatettansa.","Joka ylimmäinen pappi on veljeinsä seassa, jonka pään päälle voidellusöljy vuodatettu, ja käsi täytetty on, että hän vaatteesen puetetaan: ei pidä sen paljastaman päätänsä, ja ei leikkaaman rikki vaatettansa."],[21,11,"Ja ei yhdenkään kuolleen tykö tuleman, ja ei saastuttaman itsiänsä isässänsä eli äidissänsä.","Ja ei yhdenkään kuolleen tykö tuleman, ja ei saastuttaman itsiänsä isässänsä eli äidissänsä."],[21,12,"Ei hänen pidä lähtemän pyhästä, ettei hän saastuttaisi Jumalansa pyhää; sillä hänen Jumalansa voidellusöljyn kruunu on hänen päällänsä. Minä olen Herra.","Ei hänen pidä lähtemän pyhästä, ettei hän saastuttaisi Jumalansa pyhää; sillä hänen Jumalansa voidellusöljyn kruunu on hänen päällänsä. Minä olen Herra."],[21,13,"Hänen pitää ottaman neitseen emännäksensä,","Hänen pitää ottaman neitseen emännäksensä,"],[21,14,"Ja ei leskeä, eli hyljättyä, eli maattua, taikka porttoa pidä hänen ottaman. Mutta neitosen omasta kansastansa pitää hänen ottaman emännäksensä,","Ja ei leskeä, eli hyljättyä, eli maattua, taikka porttoa pidä hänen ottaman. Mutta neitosen omasta kansastansa pitää hänen ottaman emännäksensä,"],[21,15,"Ettei hän saastuttaisi siementänsä kansansa seassa; sillä minä olen Herra, joka hänen pyhitän.","Ettei hän saastuttaisi siementänsä kansansa seassa; sillä minä olen Herra, joka hänen pyhitän."],[21,16,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[21,17,"Puhu Aaronille ja sano: jos joku virhe on jossakussa sinun siemenessäs teidän suvussanne, ei pidä sen lähestymän uhraamaan Jumalansa leipää.","Puhu Aaronille ja sano: jos joku virhe on jossakussa sinun siemenessäs teidän suvussanne, ei pidä sen lähestymän uhraamaan Jumalansa leipää."],[21,18,"Sillä ei kenenkään, jossa joku virhe on, pidä käymän edes: jos hän on sokia, eli ontuva, vajava eli liiallinen jäsenistä,","Sillä ei kenenkään, jossa joku virhe on, pidä käymän edes: jos hän on sokia, eli ontuva, vajava eli liiallinen jäsenistä,"],[21,19,"Eli virheellinen jalasta eli kädestä,","Eli virheellinen jalasta eli kädestä,"],[21,20,"Taikka ryhäselkä, eli pienukainen, eli karsoi, eli pisamainen, taikka rupinen, eli rivinoma rauhaisista:","Taikka ryhäselkä, eli pienukainen, eli karsoi, eli pisamainen, taikka rupinen, eli rivinoma rauhaisista:"],[21,21,"Jos jossakin papin Aaronin siemenessä virhe on, ei sen pidä lähestymän uhraamaan Herran tuliuhria; sillä hänellä on virhe, sentähden ei pidä hänen lähestymän Jumalansa leipää uhraamaan.","Jos jossakin papin Aaronin siemenessä virhe on, ei sen pidä lähestymän uhraamaan Herran tuliuhria; sillä hänellä on virhe, sentähden ei pidä hänen lähestymän Jumalansa leipää uhraamaan."],[21,22,"Kuitenkin pitää hänen syömän Jumalansa leivästä, sekä siitä pyhästä, että kaikkein pyhimmästä.","Kuitenkin pitää hänen syömän Jumalansa leivästä, sekä siitä pyhästä, että kaikkein pyhimmästä."],[21,23,"Mutta ei hänen pidä kuitenkaan tuleman esiripun tykö, eikä lähestymän alttaria, että hänessä on virhe, ettei hän saastuttaisi minun pyhääni; sillä minä olen Herra, joka heidät pyhitän.","Mutta ei hänen pidä kuitenkaan tuleman esiripun tykö, eikä lähestymän alttaria, että hänessä on virhe, ettei hän saastuttaisi minun pyhääni; sillä minä olen Herra, joka heidät pyhitän."],[21,24,"Ja Moses sanoi (nämät) Aaronille, ja hänen pojillensa, ja kaikille Israelin lapsille.","Ja Moses sanoi (nämät) Aaronille, ja hänen pojillensa, ja kaikille Israelin lapsille."],[22,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[22,2,"Puhu Aaronille ja hänen pojillensa, että he karttaisivat Israelin lasten pyhitettyä, joita he pyhittävät minulle, ja ettei he häpäisisi minun pyhää nimeäni; sillä minä olen Herra.","Puhu Aaronille ja hänen pojillensa, että he karttaisivat Israelin lasten pyhitettyä, joita he pyhittävät minulle, ja ettei he häpäisisi minun pyhää nimeäni; sillä minä olen Herra."],[22,3,"Sano siis heille ja heidän suvuillensa: jokainen kuin teidän siemenestänne menee pyhitetyn tykö, jonka Israelin lapset pyhittävät Herralle, ja hänen saastaisuutensa on hänessä, hänen sielunsa pitää hävitettämän minun kasvoini edestä; sillä minä olen Herra.","Sano siis heille ja heidän suvuillensa: jokainen kuin teidän siemenestänne menee pyhitetyn tykö, jonka Israelin lapset pyhittävät Herralle, ja hänen saastaisuutensa on hänessä, hänen sielunsa pitää hävitettämän minun kasvoini edestä; sillä minä olen Herra."],[22,4,"Kuka ikänä Aaronin siemenestä on spitalinen eli vuotavainen, sen ei pidä syömän pyhitetyistä, ennen kuin hän puhdistetaan. Ja jos joku rupee johonkuhun saastaiseen ruumiisen, taikka siihen, joka siemenensä vuodattaa unessa,","Kuka ikänä Aaronin siemenestä on spitalinen eli vuotavainen, sen ei pidä syömän pyhitetyistä, ennen kuin hän puhdistetaan. Ja jos joku rupee johonkuhun saastaiseen ruumiisen, taikka siihen, joka siemenensä vuodattaa unessa,"],[22,5,"Taikka se, joka rupee johonkuhun matelevaiseen, joka hänelle saastainen on, taikka ihmiseen, joka hänelle saastainen on, ja kaikkinaiseen, joka hänen saastuttaa:","Taikka se, joka rupee johonkuhun matelevaiseen, joka hänelle saastainen on, taikka ihmiseen, joka hänelle saastainen on, ja kaikkinaiseen, joka hänen saastuttaa:"],[22,6,"Se sielu joka rupee johonkuhun niistä, pitää oleman saastainen ehtoosen asti, ja ei pidä syömän pyhitetyistä, vaan hänen pitää ensin viruttaman ruumiinsa vedellä.","Se sielu joka rupee johonkuhun niistä, pitää oleman saastainen ehtoosen asti, ja ei pidä syömän pyhitetyistä, vaan hänen pitää ensin viruttaman ruumiinsa vedellä."],[22,7,"Ja koska aurinko laskenut on, ja hän on puhdistettu, niin syökään sitte pyhitetyistä; sillä se on hänen ruokansa.","Ja koska aurinko laskenut on, ja hän on puhdistettu, niin syökään sitte pyhitetyistä; sillä se on hänen ruokansa."],[22,8,"Raatoa ja mitä pedolta raadeltu on, ei hänen pidä syömän, ettei hän siitä saastutettaisi; sillä minä olen Herra.","Raatoa ja mitä pedolta raadeltu on, ei hänen pidä syömän, ettei hän siitä saastutettaisi; sillä minä olen Herra."],[22,9,"Sentähden heidän pitää pitämän minun säätyni, ettei heidän pitäisi syntiä saattaman päällensä, ja kuoleman siitä, koska he saastuttavat itsensä; sillä minä olen Herra, joka heitä pyhitän.","Sentähden heidän pitää pitämän minun säätyni, ettei heidän pitäisi syntiä saattaman päällensä, ja kuoleman siitä, koska he saastuttavat itsensä; sillä minä olen Herra, joka heitä pyhitän."],[22,10,"Mutta ei yksikään muukalainen pidä syömän pyhitetyistä, eikä papin perhe, eikä myös joku palkollinen pidä syömän pyhitettyä.","Mutta ei yksikään muukalainen pidä syömän pyhitetyistä, eikä papin perhe, eikä myös joku palkollinen pidä syömän pyhitettyä."],[22,11,"Vaan koska pappi ostaa jonkun hengen rahallansa, se syökään siitä, ja se joka hänen huoneessansa syntynyt on, se myös syökään hänen leivästänsä.","Vaan koska pappi ostaa jonkun hengen rahallansa, se syökään siitä, ja se joka hänen huoneessansa syntynyt on, se myös syökään hänen leivästänsä."],[22,12,"Ja jos papin tytär tulee jonkun muukalaisen emännäksi, niin ei hänen pidä syömän pyhitetystä ylennyksestä.","Ja jos papin tytär tulee jonkun muukalaisen emännäksi, niin ei hänen pidä syömän pyhitetystä ylennyksestä."],[22,13,"Mutta jos papin tytär tulee leskeksi, eli hyljätyksi ja ei hänellä ole siementä, ja hän tulee jälleen kotia isänsä huoneeseen, niin hänen pitää syömän isänsä leivästä, niinkuin silloinkin, koska hän neitsenä oli. Mutta ei yksikään muukalainen pidä siitä syömän.","Mutta jos papin tytär tulee leskeksi, eli hyljätyksi ja ei hänellä ole siementä, ja hän tulee jälleen kotia isänsä huoneeseen, niin hänen pitää syömän isänsä leivästä, niinkuin silloinkin, koska hän neitsenä oli. Mutta ei yksikään muukalainen pidä siitä syömän."],[22,14,"Ja jos joku syö pyhitetyistä tietämätä, hänen pitää lisäämän siihen viidennen osan, ja antaman papille pyhitetyn,","Ja jos joku syö pyhitetyistä tietämätä, hänen pitää lisäämän siihen viidennen osan, ja antaman papille pyhitetyn,"],[22,15,"Ettei heidän pitäisi saastuttaman Israelin lasten pyhitettyjä, joita he ylentävät Herralle,","Ettei heidän pitäisi saastuttaman Israelin lasten pyhitettyjä, joita he ylentävät Herralle,"],[22,16,"Ettei he saattaisi rikosta ja vikaa päällensä, syödessänsä heidän pyhitetyistänsä; sillä minä olen Herra, joka heitä pyhitän.","Ettei he saattaisi rikosta ja vikaa päällensä, syödessänsä heidän pyhitetyistänsä; sillä minä olen Herra, joka heitä pyhitän."],[22,17,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[22,18,"Puhu Aaronille ja hänen pojillensa, ja kaikille Israelin lapsille, ja sano heille: kuka ikänä Israelin huoneesta, eli muukalainen Israelissa, tahtoo uhrata, olkoon se lupauksesta, taikka vapaasta ehdosta, jota he tahtovat uhrata Herralle polttouhriksi,","Puhu Aaronille ja hänen pojillensa, ja kaikille Israelin lapsille, ja sano heille: kuka ikänä Israelin huoneesta, eli muukalainen Israelissa, tahtoo uhrata, olkoon se lupauksesta, taikka vapaasta ehdosta, jota he tahtovat uhrata Herralle polttouhriksi,"],[22,19,"Että se hänelle olis otollinen teiltä, niin pitää sen oleman virheettömän härkyisen karjasta, oinaan karitsoista, eli kauriin vuohista.","Että se hänelle olis otollinen teiltä, niin pitää sen oleman virheettömän härkyisen karjasta, oinaan karitsoista, eli kauriin vuohista."],[22,20,"Mutta ei yhtäkään, jossa virhe on, pidä teidän uhraaman; sillä ei se ole hänelle otollinen teiltä.","Mutta ei yhtäkään, jossa virhe on, pidä teidän uhraaman; sillä ei se ole hänelle otollinen teiltä."],[22,21,"Jos joku tahtoo uhrata Herralle kiitosuhria, eli erinomaisesta lupauksesta, taikka vapaasta ehdosta, karjasta eli lampaista, sen pitää oleman virheettömän, että se olis otollinen: ei siinä pidä yhtään virhettä oleman.","Jos joku tahtoo uhrata Herralle kiitosuhria, eli erinomaisesta lupauksesta, taikka vapaasta ehdosta, karjasta eli lampaista, sen pitää oleman virheettömän, että se olis otollinen: ei siinä pidä yhtään virhettä oleman."],[22,22,"Jos se on sokia, taikka raajarikko, taikka jäsenpuoli, taikka kuivettu, taikka rupinen, taikka köhnäinen, niin ei pidä teidän senkaltaisia Herralle uhraaman, ja ei pidä teidän tuliuhria niistä antaman Herran alttarille.","Jos se on sokia, taikka raajarikko, taikka jäsenpuoli, taikka kuivettu, taikka rupinen, taikka köhnäinen, niin ei pidä teidän senkaltaisia Herralle uhraaman, ja ei pidä teidän tuliuhria niistä antaman Herran alttarille."],[22,23,"Härjän eli lampaan, liiallisen eli puuttuvaisen jäsenistä, saat sinä uhrata vapaasta ehdostas; mutta ei se ole otollinen lupauksen edestä.","Härjän eli lampaan, liiallisen eli puuttuvaisen jäsenistä, saat sinä uhrata vapaasta ehdostas; mutta ei se ole otollinen lupauksen edestä."],[22,24,"Eikä myös sinun pidä sitä Herralle uhraaman, mikä muserrettu, eli runneltu, eli revitty, eli haavoitettu on; ei teidän pidä sitä teidän maassanne tekemän.","Eikä myös sinun pidä sitä Herralle uhraaman, mikä muserrettu, eli runneltu, eli revitty, eli haavoitettu on; ei teidän pidä sitä teidän maassanne tekemän."],[22,25,"Ei myös teidän pidä uhraaman jonkun muukalaisen kädestä teidän Jumalanne leipää kaikista niistä; sillä ne ovat turmellut ja virheelliset: ei ne ole otolliset teiltä.","Ei myös teidän pidä uhraaman jonkun muukalaisen kädestä teidän Jumalanne leipää kaikista niistä; sillä ne ovat turmellut ja virheelliset: ei ne ole otolliset teiltä."],[22,26,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[22,27,"Koska vasikka, eli karitsa, eli vohla pojittu on, niin olkaan emänsä tykönä seitsemän päivää; mutta kahdeksantena päivänä, ja sen jälkeen, on se otollinen tuliuhriksi Herralle.","Koska vasikka, eli karitsa, eli vohla pojittu on, niin olkaan emänsä tykönä seitsemän päivää; mutta kahdeksantena päivänä, ja sen jälkeen, on se otollinen tuliuhriksi Herralle."],[22,28,"Olkoon se nauta, eli lammas, niin ei pidä se teurastettaman sikiöinensä yhtenä päivänä.","Olkoon se nauta, eli lammas, niin ei pidä se teurastettaman sikiöinensä yhtenä päivänä."],[22,29,"Koska te uhraatte Herralle kiitosuhria, teidän pitää sen niin uhraaman, että se teiltä otollinen olis.","Koska te uhraatte Herralle kiitosuhria, teidän pitää sen niin uhraaman, että se teiltä otollinen olis."],[22,30,"Se pitää syötämän sinä päivänä, ja ei pidä mitään tähteeksi huomeneksi jätettämän; sillä minä olen Herra.","Se pitää syötämän sinä päivänä, ja ei pidä mitään tähteeksi huomeneksi jätettämän; sillä minä olen Herra."],[22,31,"Sentähden pitäkäät minun käskyni ja tehkäät ne, sillä minä olen Herra.","Sentähden pitäkäät minun käskyni ja tehkäät ne, sillä minä olen Herra."],[22,32,"Ettette häpeäisi minun pyhää nimeäni, ja että minä pyhitettäisiin Israelin lasten keskellä; sillä minä olen Hera, joka teitä pyhitän,","Ettette häpeäisi minun pyhää nimeäni, ja että minä pyhitettäisiin Israelin lasten keskellä; sillä minä olen Hera, joka teitä pyhitän,"],[22,33,"Ja joka olen teidät johdattanut Egyptin maalta, että minä olisin teidän Jumalanne: minä Herra.","Ja joka olen teidät johdattanut Egyptin maalta, että minä olisin teidän Jumalanne: minä Herra."],[23,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[23,2,"Puhu Israelin lapsille ja sano heille: nämät ovat Herran juhlat, jotka teidän pitää kutsuman pyhiksi kokouksiksi: ne ovat minun juhlani.","Puhu Israelin lapsille ja sano heille: nämät ovat Herran juhlat, jotka teidän pitää kutsuman pyhiksi kokouksiksi: ne ovat minun juhlani."],[23,3,"Kuusi päivää pitää sinun työtä tekemän, vaan seitsemäntenä päivänä on se suuri sabbati, pyhä kokous, jona ei teidän pidä yhtään työtä tekemän; sillä se on Herran sabbati kaikissa teidän asuinsioissanne.","Kuusi päivää pitää sinun työtä tekemän, vaan seitsemäntenä päivänä on se suuri sabbati, pyhä kokous, jona ei teidän pidä yhtään työtä tekemän; sillä se on Herran sabbati kaikissa teidän asuinsioissanne."],[23,4,"Nämät ovat Herran juhlapäivät, pyhät kokoukset, jotka teidän pitää pitämän määrätyillä ajallansa:","Nämät ovat Herran juhlapäivät, pyhät kokoukset, jotka teidän pitää pitämän määrätyillä ajallansa:"],[23,5,"Neljäntenätoistakymmenentenä päivänä ensimmäisenä kuukautena, kahden ehtoon välillä, on Herran pääsiäinen.","Neljäntenätoistakymmenentenä päivänä ensimmäisenä kuukautena, kahden ehtoon välillä, on Herran pääsiäinen."],[23,6,"Ja viidentenätoistakymmenentenä päivänä sinä kuukautena on Herran happamattoman leivän juhla: silloin pitää teidän syömän happamatointa leipää seitsemän päivää.","Ja viidentenätoistakymmenentenä päivänä sinä kuukautena on Herran happamattoman leivän juhla: silloin pitää teidän syömän happamatointa leipää seitsemän päivää."],[23,7,"Ensimmäisenä päivänä olkoon teillä pyhä kokous, eikä yhtään raskasta työtä pidä teidän silloin tekemän.","Ensimmäisenä päivänä olkoon teillä pyhä kokous, eikä yhtään raskasta työtä pidä teidän silloin tekemän."],[23,8,"Ja teidän pitää uhraaman Herralle tuliuhria seitsemän päivää. Seitsemäntenä päivänä on pyhä kokous. (Ja silloin myös) ei pidä teidän yhtäkään raskasta työtä tekemän.","Ja teidän pitää uhraaman Herralle tuliuhria seitsemän päivää. Seitsemäntenä päivänä on pyhä kokous. (Ja silloin myös) ei pidä teidän yhtäkään raskasta työtä tekemän."],[23,9,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[23,10,"Puhu Israelin lapsille, ja sano heille: koska te tulette sille maalle, jonka minä annan teille, ja te leikkaatte sen elon, niin teidän pitää viemän papille lyhteen teidän elostanne uutiseksi.","Puhu Israelin lapsille, ja sano heille: koska te tulette sille maalle, jonka minä annan teille, ja te leikkaatte sen elon, niin teidän pitää viemän papille lyhteen teidän elostanne uutiseksi."],[23,11,"Ja sen lyhteen pitää hänen häälyttämän Herran edessä, että se olis otollinen teiltä: päivää jälkeen sabbatin pitää papin sen häälyttämän.","Ja sen lyhteen pitää hänen häälyttämän Herran edessä, että se olis otollinen teiltä: päivää jälkeen sabbatin pitää papin sen häälyttämän."],[23,12,"Ja teidän pitää sinä päivänä, jona teidän lyhteenne häälytetään, uhraaman virheettömän vuosikuntaisen karitsan polttouhriksi Herralle.","Ja teidän pitää sinä päivänä, jona teidän lyhteenne häälytetään, uhraaman virheettömän vuosikuntaisen karitsan polttouhriksi Herralle."],[23,13,"Ja ruokauhriksi kaksi kymmenestä sämpyläjauhoja, sekoitetut öljyllä, tuliuhriksi ja lepytyshajuksi Herralle, niin myös juomauhriksi neljännes hinni viinaa.","Ja ruokauhriksi kaksi kymmenestä sämpyläjauhoja, sekoitetut öljyllä, tuliuhriksi ja lepytyshajuksi Herralle, niin myös juomauhriksi neljännes hinni viinaa."],[23,14,"Ja ei pidä teidän syömän uudisleipää, kuivattua tähkäpäätä eli jyviä, siihen päivään asti, jona te kannatte teidän Jumalallenne uhrin. Sen pitää oleman ijankaikkisen säädyn teidän sukukunnillenne kaikissa teidän asuinsioissanne.","Ja ei pidä teidän syömän uudisleipää, kuivattua tähkäpäätä eli jyviä, siihen päivään asti, jona te kannatte teidän Jumalallenne uhrin. Sen pitää oleman ijankaikkisen säädyn teidän sukukunnillenne kaikissa teidän asuinsioissanne."],[23,15,"Sitte pitää teidän lukeman toisesta sabbatin päivästä, koska te kannoitte häälytyslyhteen edes: seitsemän täysinäistä viikkoa ne pitää oleman,","Sitte pitää teidän lukeman toisesta sabbatin päivästä, koska te kannoitte häälytyslyhteen edes: seitsemän täysinäistä viikkoa ne pitää oleman,"],[23,16,"Toiseen päivään asti, seitsemännen viikon jälkeen, (se on) viisikymmentä päivää pitää teidän lukeman, ja sitte uhraaman Herralle uutta ruokauhria.","Toiseen päivään asti, seitsemännen viikon jälkeen, (se on) viisikymmentä päivää pitää teidän lukeman, ja sitte uhraaman Herralle uutta ruokauhria."],[23,17,"Ja uhraaman kaikista teidän asumasioistanne kaksi häälytysleipää, kahdesta kymmeneksestä sämpyläjauhoja, hapatettuina pitää ne kypsettämän, Herranne uutiseksi.","Ja uhraaman kaikista teidän asumasioistanne kaksi häälytysleipää, kahdesta kymmeneksestä sämpyläjauhoja, hapatettuina pitää ne kypsettämän, Herranne uutiseksi."],[23,18,"Ja pitää tuoman teidän leipänne kanssa seitsemän vuosikuntaista ja virheetöintä karitsaa, ja yhden nuoren mullin, ja kaksi oinasta: sen pitää oleman Herran polttouhrin, ja heidän ruokauhrinsa ja juomauhrinsa, se on makian hajun tuli Herralle.","Ja pitää tuoman teidän leipänne kanssa seitsemän vuosikuntaista ja virheetöintä karitsaa, ja yhden nuoren mullin, ja kaksi oinasta: sen pitää oleman Herran polttouhrin, ja heidän ruokauhrinsa ja juomauhrinsa, se on makian hajun tuli Herralle."],[23,19,"Niin myös pitää teidän valmistaman kauriin rikosuhriksi, niin myös kaksi vuosikuntaista karitsaa kiitosuhriksi.","Niin myös pitää teidän valmistaman kauriin rikosuhriksi, niin myös kaksi vuosikuntaista karitsaa kiitosuhriksi."],[23,20,"Ja papin pitää häälyttämän ne uudisleivän kanssa häälytykseksi Herran edessä, kahden karitsan kanssa. Ja pitää oleman Herralle pyhät, ja papin omat.","Ja papin pitää häälyttämän ne uudisleivän kanssa häälytykseksi Herran edessä, kahden karitsan kanssa. Ja pitää oleman Herralle pyhät, ja papin omat."],[23,21,"Ja teidän pitää kuuluttaman tämän päivän: tämä pitää teille pyhä kokous oleman. Ei teidän pidä (silloin) yhtäkään raskasta työtä tekemän: ijankaikkisen säädyn pitää sen oleman teidän sukukunnissanne, kaikissa teidän asuinsioissanne.","Ja teidän pitää kuuluttaman tämän päivän: tämä pitää teille pyhä kokous oleman. Ei teidän pidä (silloin) yhtäkään raskasta työtä tekemän: ijankaikkisen säädyn pitää sen oleman teidän sukukunnissanne, kaikissa teidän asuinsioissanne."],[23,22,"Koska te leikkaatte elon teidän maastanne, ei sinun pidä ylen tyynni peltos kulmia leikkaaman, eikä elon päitä noukkiman, vaan jättämän ne vaivaisille ja muukalaisille. Minä olen Herra teidän Jumalanne.","Koska te leikkaatte elon teidän maastanne, ei sinun pidä ylen tyynni peltos kulmia leikkaaman, eikä elon päitä noukkiman, vaan jättämän ne vaivaisille ja muukalaisille. Minä olen Herra teidän Jumalanne."],[23,23,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[23,24,"Puhu Israelin lapsille, ja sano: ensimäisenä päivänä seitsemäntenä kuukautena pitää teidän pitämän sabbatin, soittamisen muistoksi: se on pyhä kokous.","Puhu Israelin lapsille, ja sano: ensimäisenä päivänä seitsemäntenä kuukautena pitää teidän pitämän sabbatin, soittamisen muistoksi: se on pyhä kokous."],[23,25,"Silloin ei pidä teidän yhtään raskasta työtä tekemän, ja teidän pitää uhraaman tuliuhri Herralle.","Silloin ei pidä teidän yhtään raskasta työtä tekemän, ja teidän pitää uhraaman tuliuhri Herralle."],[23,26,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[23,27,"Kymmenentenä päivänä tänä seitsemäntenä kuuna on sovintopäivä, se pitää oleman teille pyhä kokous: silloin vaivatkaat sielujanne, ja uhratkaat Herralle tuliuhri.","Kymmenentenä päivänä tänä seitsemäntenä kuuna on sovintopäivä, se pitää oleman teille pyhä kokous: silloin vaivatkaat sielujanne, ja uhratkaat Herralle tuliuhri."],[23,28,"Ja ei pidä teidän yhtään työtä tekemän sinä päivänä; sillä se on sovintopäivä, että te sovitettaisiin Herran teidän Jumalanne edessä.","Ja ei pidä teidän yhtään työtä tekemän sinä päivänä; sillä se on sovintopäivä, että te sovitettaisiin Herran teidän Jumalanne edessä."],[23,29,"Sillä jokainen sielu, jota ei sinä päivänä vaivata, pitää hävitettämän kansastansa.","Sillä jokainen sielu, jota ei sinä päivänä vaivata, pitää hävitettämän kansastansa."],[23,30,"Ja jokainen sielu, joka sinä päivänä jotakin työtä tekee, sen minä hukutan kansastansa.","Ja jokainen sielu, joka sinä päivänä jotakin työtä tekee, sen minä hukutan kansastansa."],[23,31,"Sentähden ei pidä teidän (silloin) mitään työtä tekemän: sen pitää oleman ijankaikkisen säädyn teidän sukukunnillenne kaikissa teidän asuinsioissanne.","Sentähden ei pidä teidän (silloin) mitään työtä tekemän: sen pitää oleman ijankaikkisen säädyn teidän sukukunnillenne kaikissa teidän asuinsioissanne."],[23,32,"Se on teidän suuri sabbatinne, ja teidän pitää vaivaaman sielujanne: yhdeksäntenä päivänä kuusta ehtoona pitää teidän pitämän tämän sabbatin, ehtoosta niin ehtoosen.","Se on teidän suuri sabbatinne, ja teidän pitää vaivaaman sielujanne: yhdeksäntenä päivänä kuusta ehtoona pitää teidän pitämän tämän sabbatin, ehtoosta niin ehtoosen."],[23,33,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[23,34,"Puhu Israelin lapsille, sanoen: viidentenätoistakymmenentenä päivänä tänä seitsemäntenä kuukautena on lehtimajan juhla, seitsemän päivää Herralle.","Puhu Israelin lapsille, sanoen: viidentenätoistakymmenentenä päivänä tänä seitsemäntenä kuukautena on lehtimajan juhla, seitsemän päivää Herralle."],[23,35,"Ensimäisenä päivänä pitää oleman pyhä kokous: ei teidän pidä yhtään raskasta työtä (silloin) tekemän.","Ensimäisenä päivänä pitää oleman pyhä kokous: ei teidän pidä yhtään raskasta työtä (silloin) tekemän."],[23,36,"Seitsemän päivää pitää teidän uhraaman tuliuhria Herralle, kahdeksantena päivänä pitää teillä pyhä kokous oleman, ja teidän pitää tekemän tuliuhri Herralle; sillä se on päätöspäivä: ei pidä teidän yhtään raskasta työtä (silloin) tekemän.","Seitsemän päivää pitää teidän uhraaman tuliuhria Herralle, kahdeksantena päivänä pitää teillä pyhä kokous oleman, ja teidän pitää tekemän tuliuhri Herralle; sillä se on päätöspäivä: ei pidä teidän yhtään raskasta työtä (silloin) tekemän."],[23,37,"Nämät ovat Herran juhlapäivät, jotka teidän pitää kutsuman pyhäksi kokoukseksi, ja uhraaman Herralle tuliuhria, polttouhria, ruokauhria, juomauhria, ja muita uhreja, jokaisen päivänänsä.","Nämät ovat Herran juhlapäivät, jotka teidän pitää kutsuman pyhäksi kokoukseksi, ja uhraaman Herralle tuliuhria, polttouhria, ruokauhria, juomauhria, ja muita uhreja, jokaisen päivänänsä."],[23,38,"Ilman Herran sabbatia, ja ilman teidän lahjojanne ja ilman kaikkia lupauksianne, ja ilman kaikkia mielellisiä antimianne, joita teidän pitää antaman Herralle.","Ilman Herran sabbatia, ja ilman teidän lahjojanne ja ilman kaikkia lupauksianne, ja ilman kaikkia mielellisiä antimianne, joita teidän pitää antaman Herralle."],[23,39,"Niin pitää nyt teidän viidentenätoistakymmenentenä päivänä seitsemäntenä kuukautena, koottuanne vuoden tulon maalta, juhlallisesti viettämän Herran riemujuhlaa, seitsemän päivää: ensimäisenä päivänä on sabbati, ja kahdeksantena päivänä on myös sabbati.","Niin pitää nyt teidän viidentenätoistakymmenentenä päivänä seitsemäntenä kuukautena, koottuanne vuoden tulon maalta, juhlallisesti viettämän Herran riemujuhlaa, seitsemän päivää: ensimäisenä päivänä on sabbati, ja kahdeksantena päivänä on myös sabbati."],[23,40,"Ja teidän pitää ensimäisenä päivänä ottaman teillenne hedelmiä ihanasta puusta, palmun versoja, ja oksia paksu-oksaisista puista ja pajuja ojista, ja oleman riemuiset seitsemän päivää, Herran teidän Jumalanne edessä.","Ja teidän pitää ensimäisenä päivänä ottaman teillenne hedelmiä ihanasta puusta, palmun versoja, ja oksia paksu-oksaisista puista ja pajuja ojista, ja oleman riemuiset seitsemän päivää, Herran teidän Jumalanne edessä."],[23,41,"Ja pitää niin pitämän Herralle sitä riemujuhlaa vuodessa seitsemän päivää: sen pitää oleman ijankaikkisen säädyn teidän sukukunnissanne, että teidän niin pitää pyhää riemujuhlaa pitämän seitsemäntenä kuukautena.","Ja pitää niin pitämän Herralle sitä riemujuhlaa vuodessa seitsemän päivää: sen pitää oleman ijankaikkisen säädyn teidän sukukunnissanne, että teidän niin pitää pyhää riemujuhlaa pitämän seitsemäntenä kuukautena."],[23,42,"Seitsemän päivää pitää teidän asuman lehtimajoissa: joka omainen on Israelissa, hänen pitää asuman lehtimajoissa,","Seitsemän päivää pitää teidän asuman lehtimajoissa: joka omainen on Israelissa, hänen pitää asuman lehtimajoissa,"],[23,43,"Että teidän sukunne tietäisivät, kuinka minä olen antanut Israelin lapset asua majoissa, koska minä johdatin heitä Egyptin maalta: Minä Herra teidän Jumalanne.","Että teidän sukunne tietäisivät, kuinka minä olen antanut Israelin lapset asua majoissa, koska minä johdatin heitä Egyptin maalta: Minä Herra teidän Jumalanne."],[23,44,"Ja Moses sanoi nämät Herran juhlapäivät Israelin lapsille.","Ja Moses sanoi nämät Herran juhlapäivät Israelin lapsille."],[24,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[24,2,"Käske Israelin lasten tuoda sinulle selkiää öljypuun öljyä, puserrettua ulos, valaistukseksi, joka aina pitää lampuissa sytytettynä oleman.","Käske Israelin lasten tuoda sinulle selkiää öljypuun öljyä, puserrettua ulos, valaistukseksi, joka aina pitää lampuissa sytytettynä oleman."],[24,3,"Ulkoiselle puolelle todistuksen esirippua seurakunnan majassa pitää Aaronin sen alati valmistaman, ehtoosta niin aamuun asti Herran edessä. Sen pitää oleman ijankaikkisen säädyn teidän sukukunnissanne.","Ulkoiselle puolelle todistuksen esirippua seurakunnan majassa pitää Aaronin sen alati valmistaman, ehtoosta niin aamuun asti Herran edessä. Sen pitää oleman ijankaikkisen säädyn teidän sukukunnissanne."],[24,4,"Ja hänen pitää valmistaman lamput puhtaasen kynttiläjalkaan, aina Herran edessä.","Ja hänen pitää valmistaman lamput puhtaasen kynttiläjalkaan, aina Herran edessä."],[24,5,"Ja sinun pitää ottaman sämpyläjauhoja ja leipoman niistä kaksitoistakymmentä kyrsää: kaksi kymmenestä pitää oleman joka kyrsässä.","Ja sinun pitää ottaman sämpyläjauhoja ja leipoman niistä kaksitoistakymmentä kyrsää: kaksi kymmenestä pitää oleman joka kyrsässä."],[24,6,"Ja sinun pitää heidän paneman kahteen läjään, kuusi kumpaankin läjään, puhtaalle pöydälle Herran eteen.","Ja sinun pitää heidän paneman kahteen läjään, kuusi kumpaankin läjään, puhtaalle pöydälle Herran eteen."],[24,7,"Ja sinun pitää paneman niiden päälle puhdasta pyhää savua, että ne pitää oleman muistoleivät: se on tuliuhri Herralle.","Ja sinun pitää paneman niiden päälle puhdasta pyhää savua, että ne pitää oleman muistoleivät: se on tuliuhri Herralle."],[24,8,"Joka sabbatin päivänä pitää hänen aina valmistaman ne Herran edessä, Israelin lapsilta ijankaikkiseksi liitoksi.","Joka sabbatin päivänä pitää hänen aina valmistaman ne Herran edessä, Israelin lapsilta ijankaikkiseksi liitoksi."],[24,9,"Ja ne pitää Aaronin ja hänen poikainsa omat oleman, heidän pitää ne syömän pyhässä siassa; sillä se on hänelle kaikkein pyhin Herran tuliuhreista ijankaikkiseksi säädyksi.","Ja ne pitää Aaronin ja hänen poikainsa omat oleman, heidän pitää ne syömän pyhässä siassa; sillä se on hänelle kaikkein pyhin Herran tuliuhreista ijankaikkiseksi säädyksi."],[24,10,"Ja yhden Israelilaisen vaimon poika läksi ulos, joka Egyptiläisen miehen poika oli Israelin lasten seassa, ja se Israelilaisen vaimon poika riiteli toisen Israelilaisen kanssa leirissä,","Ja yhden Israelilaisen vaimon poika läksi ulos, joka Egyptiläisen miehen poika oli Israelin lasten seassa, ja se Israelilaisen vaimon poika riiteli toisen Israelilaisen kanssa leirissä,"],[24,11,"Ja se Israelilaisen vaimon poika pilkkasi nimeä ja kirosi. Niin toivat he hänen Moseksen eteen, (ja hänen äitinsä nimi oli Selomit Dibrin tytär, Danin sukukunnasta).","Ja se Israelilaisen vaimon poika pilkkasi nimeä ja kirosi. Niin toivat he hänen Moseksen eteen, (ja hänen äitinsä nimi oli Selomit Dibrin tytär, Danin sukukunnasta)."],[24,12,"Ja panivat hänen vankeuteen niinkauvaksi, että heille olis selkiä päätös annettu Herran suusta.","Ja panivat hänen vankeuteen niinkauvaksi, että heille olis selkiä päätös annettu Herran suusta."],[24,13,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[24,14,"Vie häntä leiristä ulos, joka kiroillut on, ja anna kaikkein, jotka sen kuulivat, laskea kätensä hänen päänsä päälle, ja kaikki kansa kivittäkään häntä.","Vie häntä leiristä ulos, joka kiroillut on, ja anna kaikkein, jotka sen kuulivat, laskea kätensä hänen päänsä päälle, ja kaikki kansa kivittäkään häntä."],[24,15,"Ja puhu Israelin lapsille, sanoen: kuka ikänä Jumalaansa kiroilee, hänen pitää kantaman syntinsä.","Ja puhu Israelin lapsille, sanoen: kuka ikänä Jumalaansa kiroilee, hänen pitää kantaman syntinsä."],[24,16,"Ja joka Herran nimeä pilkkaa, sen pitää totisesti kuoleman, kaiken kansan pitää häntä kuoliaaksi kivittämän. Niinkuin muukalaisen, niin pitää myös omaisen oleman: jos hän pilkkaa sitä nimeä, niin hänen pitää kuoleman.","Ja joka Herran nimeä pilkkaa, sen pitää totisesti kuoleman, kaiken kansan pitää häntä kuoliaaksi kivittämän. Niinkuin muukalaisen, niin pitää myös omaisen oleman: jos hän pilkkaa sitä nimeä, niin hänen pitää kuoleman."],[24,17,"Jos joku lyö jonkun ihmisen kuoliaaksi, hänen pitää totisesti kuoleman.","Jos joku lyö jonkun ihmisen kuoliaaksi, hänen pitää totisesti kuoleman."],[24,18,"Vaan joka jonkun naudan lyö, hänen pitää maksaman hengen hengestä.","Vaan joka jonkun naudan lyö, hänen pitää maksaman hengen hengestä."],[24,19,"Ja joka tekee jonkun lähimmäisensä virheelliseksi, hänelle pitää niin tehtämän, kuin hänkin tehnyt on:","Ja joka tekee jonkun lähimmäisensä virheelliseksi, hänelle pitää niin tehtämän, kuin hänkin tehnyt on:"],[24,20,"Haava haavasta, silmä silmästä, hammas hampaasta; niinkuin hän on jonkun ihmisen virheelliseksi tehnyt, niin pitää myös hänelle jälleen tehtämän.","Haava haavasta, silmä silmästä, hammas hampaasta; niinkuin hän on jonkun ihmisen virheelliseksi tehnyt, niin pitää myös hänelle jälleen tehtämän."],[24,21,"Niin että joka lyö naudan, hänen pitää sen maksaman, vaan joka lyö ihmisen, sen pitää kuoleman.","Niin että joka lyö naudan, hänen pitää sen maksaman, vaan joka lyö ihmisen, sen pitää kuoleman."],[24,22,"Yhden oikeuden pitää oleman teidän seassanne, niin muukalaisella kuin omaisellakin; sillä minä olen Herra teidän Jumalanne.","Yhden oikeuden pitää oleman teidän seassanne, niin muukalaisella kuin omaisellakin; sillä minä olen Herra teidän Jumalanne."],[24,23,"Koska Moses oli näitä puhunut Israelin lapsille, niin veivät he sen leiristä ulos, joka kiroillut oli, ja kivittivät hänen kuoliaaksi: ja Israelin lapset tekivät niinkuin Herra Mosekselle käskenyt oli.","Koska Moses oli näitä puhunut Israelin lapsille, niin veivät he sen leiristä ulos, joka kiroillut oli, ja kivittivät hänen kuoliaaksi: ja Israelin lapset tekivät niinkuin Herra Mosekselle käskenyt oli."],[25,1,"Ja Herra puhui Mosekselle Sinain vuorella, sanoen:","Ja Herra puhui Mosekselle Sinain vuorella, sanoen:"],[25,2,"Puhu Israelin lapsille ja sano heille: koska te tulette siihen maahan, jonka minä teille annan, niin maan pitää pitämän Herralle lepoa.","Puhu Israelin lapsille ja sano heille: koska te tulette siihen maahan, jonka minä teille annan, niin maan pitää pitämän Herralle lepoa."],[25,3,"Kuusi vuotta pitää sinun peltos kylvämän, ja kuusi vuotta viinamäkes leikkaaman, ja sen hedelmät kokooman;","Kuusi vuotta pitää sinun peltos kylvämän, ja kuusi vuotta viinamäkes leikkaaman, ja sen hedelmät kokooman;"],[25,4,"Mutta seitsemäntenä vuonna pitää maan pitämän Herralle suuren pyhän, jona ei sinun pidä kylvämän sinun peltoas taikka leikkaaman sinun viinamäkeäs.","Mutta seitsemäntenä vuonna pitää maan pitämän Herralle suuren pyhän, jona ei sinun pidä kylvämän sinun peltoas taikka leikkaaman sinun viinamäkeäs."],[25,5,"Ja mitä itsestänsä kasvaa laihostas, ei sinun pidä leikkaaman, ja viinamarjoja, jotka ilman sinun työtäs ovat kasvaneet, ei sinun pidä noukkiman; sillä se on maan lepovuosi.","Ja mitä itsestänsä kasvaa laihostas, ei sinun pidä leikkaaman, ja viinamarjoja, jotka ilman sinun työtäs ovat kasvaneet, ei sinun pidä noukkiman; sillä se on maan lepovuosi."],[25,6,"Mutta maan lepoa sinun pitää sentähdn pitämän, että sinun pitää siitä syömän, sinun palvelias ja piikas, niin myös päivämiehes, huonekuntaises, ja muukalaiset sinun tykönäs.","Mutta maan lepoa sinun pitää sentähdn pitämän, että sinun pitää siitä syömän, sinun palvelias ja piikas, niin myös päivämiehes, huonekuntaises, ja muukalaiset sinun tykönäs."],[25,7,"Ja sinun karjalles ja eläimilles sinun maallas kaikki, mitä siinä kasvaa, pitää oleman ruaksi.","Ja sinun karjalles ja eläimilles sinun maallas kaikki, mitä siinä kasvaa, pitää oleman ruaksi."],[25,8,"Ja sinun pitää lukeman sinulles seitsemän lepovuotta, niin että seitsemän vuotta pitää seitsemän kertaa luettaman: ja ne seitsemän lepovuoden aikaa tekee yhdeksän vuotta viidettäkymmentä.","Ja sinun pitää lukeman sinulles seitsemän lepovuotta, niin että seitsemän vuotta pitää seitsemän kertaa luettaman: ja ne seitsemän lepovuoden aikaa tekee yhdeksän vuotta viidettäkymmentä."],[25,9,"Niin sinun pitää antaman soittaa basunalla ylitse koko teidän maakuntanne, kymmenentenä päivänä seitsemäntenä kuukautena: juuri sovintopäivänä pitää teidän antaman basunan käydä yli koko teidän maakuntanne.","Niin sinun pitää antaman soittaa basunalla ylitse koko teidän maakuntanne, kymmenentenä päivänä seitsemäntenä kuukautena: juuri sovintopäivänä pitää teidän antaman basunan käydä yli koko teidän maakuntanne."],[25,10,"Ja teidän pitää sen viidennenkymmenennen vuoden pyhittämän, ja pitää kuuluttaman vapauden maassa kaikille niille, jotka siinä asuvat; sillä se on teidän riemuvuotenne: silloin pitää itsekunkin pääsemän jälleen omaan saamaansa, itsekukin omaan sukuunsa.","Ja teidän pitää sen viidennenkymmenennen vuoden pyhittämän, ja pitää kuuluttaman vapauden maassa kaikille niille, jotka siinä asuvat; sillä se on teidän riemuvuotenne: silloin pitää itsekunkin pääsemän jälleen omaan saamaansa, itsekukin omaan sukuunsa."],[25,11,"Sillä viideskymmenes vuosi on teidän riemuvuotenne: ei teidän pidä kylvämän, eikä leikkaaman itsestänsä kasvanutta, eikä myös hakeman niitä, mitkä ilman työtä kasvaneet ovat.","Sillä viideskymmenes vuosi on teidän riemuvuotenne: ei teidän pidä kylvämän, eikä leikkaaman itsestänsä kasvanutta, eikä myös hakeman niitä, mitkä ilman työtä kasvaneet ovat."],[25,12,"Sillä se on riemuvuosi, se pitää pyhitettämän teiltä. Mutta teidän pitää syömän niitä kaikkia, mitä maa kantaa.","Sillä se on riemuvuosi, se pitää pyhitettämän teiltä. Mutta teidän pitää syömän niitä kaikkia, mitä maa kantaa."],[25,13,"Tämä on riemuvuosi, jona itsekunkin teistä pitää omaan saamaansa pääsemän jällensä.","Tämä on riemuvuosi, jona itsekunkin teistä pitää omaan saamaansa pääsemän jällensä."],[25,14,"Jos sinä jotakin myyt lähimmäiselles, taikka ostat jotakin häneltä, niin ei yhdenkään pidä pettämän veljeänsä.","Jos sinä jotakin myyt lähimmäiselles, taikka ostat jotakin häneltä, niin ei yhdenkään pidä pettämän veljeänsä."],[25,15,"Vaan riemuvuoden luvun jälkeen pitää sinun ostaman lähimmäiseltäs, ja vuoden tulon jälkeen pitää hänen sinulle myymän.","Vaan riemuvuoden luvun jälkeen pitää sinun ostaman lähimmäiseltäs, ja vuoden tulon jälkeen pitää hänen sinulle myymän."],[25,16,"Sitä usiammat kuin vuodet ovat, pitää sinun korottaman hinnan, ja sen harvemmat kuin vuodet ovat, pitää sinun alentaman hinnan; sillä vuoden tulon luvun jälkeen pitää hänen myymän sinulle.","Sitä usiammat kuin vuodet ovat, pitää sinun korottaman hinnan, ja sen harvemmat kuin vuodet ovat, pitää sinun alentaman hinnan; sillä vuoden tulon luvun jälkeen pitää hänen myymän sinulle."],[25,17,"Älkään kenkään pettäkö lähimmäistänsä, mutta pelkää sinun Jumalaas; sillä minä olen Herra teidän Jumalanne.","Älkään kenkään pettäkö lähimmäistänsä, mutta pelkää sinun Jumalaas; sillä minä olen Herra teidän Jumalanne."],[25,18,"Sentähden tehkäät minun säätyni ja pitäkäät minun oikeuteni, että te ne teette, ja turvallisesti asutte maassa.","Sentähden tehkäät minun säätyni ja pitäkäät minun oikeuteni, että te ne teette, ja turvallisesti asutte maassa."],[25,19,"Ja maan pitää antaman teille hedelmänsä, ja teillä pitää oleman kyllä syötävää, ja asuman pelkäämätä siinä.","Ja maan pitää antaman teille hedelmänsä, ja teillä pitää oleman kyllä syötävää, ja asuman pelkäämätä siinä."],[25,20,"Ja jos te sanotte: mitä meidän pitää syömän seitsemäntenä vuonna? katso, ei meidän pidä kylvämän, eikä vuoden tuloa kokooman.","Ja jos te sanotte: mitä meidän pitää syömän seitsemäntenä vuonna? katso, ei meidän pidä kylvämän, eikä vuoden tuloa kokooman."],[25,21,"Niin minä käsken minun siunaukseni tulla kuudentena vuotena teidän ylitsenne, niin että sen pitää tekemän teille kolmen vuoden tulon.","Niin minä käsken minun siunaukseni tulla kuudentena vuotena teidän ylitsenne, niin että sen pitää tekemän teille kolmen vuoden tulon."],[25,22,"Ja teidän pitää kylvämän kahdeksantena vuonna, ja vanhasta vuoden kasvusta syömän yhdeksänteen vuoteen asti, niin että te syötte vanhasta uutiseen asti.","Ja teidän pitää kylvämän kahdeksantena vuonna, ja vanhasta vuoden kasvusta syömän yhdeksänteen vuoteen asti, niin että te syötte vanhasta uutiseen asti."],[25,23,"Sentähden ei teidän pidä maata peräti myymän; sillä maan on minun, ja te olette muukalaiset ja vieraat minun edessäni.","Sentähden ei teidän pidä maata peräti myymän; sillä maan on minun, ja te olette muukalaiset ja vieraat minun edessäni."],[25,24,"Ja teidän pitää koko teidän omassa maassanne antaman maan lunastettaa.","Ja teidän pitää koko teidän omassa maassanne antaman maan lunastettaa."],[25,25,"Jos sinun veljes köyhtyy, ja myy sinulle omaisuudestansa, ja hänen lähimmäinen lankonsa tulee hänen tykönsä, ja tahtoo lunastaa, niin pitää hänen lunastaman sen, minkä hänen veljensä myynyt on.","Jos sinun veljes köyhtyy, ja myy sinulle omaisuudestansa, ja hänen lähimmäinen lankonsa tulee hänen tykönsä, ja tahtoo lunastaa, niin pitää hänen lunastaman sen, minkä hänen veljensä myynyt on."],[25,26,"Ja jos joku on, jolla ei yhtään lunastajaa ole, ja taitaa niin paljo matkaan saada, kuin sen lunastukseksi tarvitaan.","Ja jos joku on, jolla ei yhtään lunastajaa ole, ja taitaa niin paljo matkaan saada, kuin sen lunastukseksi tarvitaan."],[25,27,"Niin pitää luettaman vuosiluku sittenkuin hän myi, ja annettaman hänelle, joka myi, mitä liiaksi on, että hän tulis omaisuuteensa jälleen.","Niin pitää luettaman vuosiluku sittenkuin hän myi, ja annettaman hänelle, joka myi, mitä liiaksi on, että hän tulis omaisuuteensa jälleen."],[25,28,"Mutta jos ei hän takaansa löydä niin paljo että hän sais sen jälleen, niin pitää sen, minkä hän myynyt on, oleman ostajan kädessä riemuvuoteen asti; niin hänen pitää oleman vapaan ja saaman omansa jälleen.","Mutta jos ei hän takaansa löydä niin paljo että hän sais sen jälleen, niin pitää sen, minkä hän myynyt on, oleman ostajan kädessä riemuvuoteen asti; niin hänen pitää oleman vapaan ja saaman omansa jälleen."],[25,29,"Se joka myy asuttavan huoneen kaupungin muurin sisältä, hänellä on vapaa ehto ajastajassa, sitä lunastaa jällensä: ja sen pitää oleman ajan, jolla hän lunastaa sen.","Se joka myy asuttavan huoneen kaupungin muurin sisältä, hänellä on vapaa ehto ajastajassa, sitä lunastaa jällensä: ja sen pitää oleman ajan, jolla hän lunastaa sen."],[25,30,"Ja jos ei hän lunasta sitä koko ajastajassa, niin pitää ostajan sen huoneen kaupungin muurin sisältä pitämän ijankaikkisesti ja hänen sukunsa, ja ei pidä vapaaksi tuleman ilovuotena.","Ja jos ei hän lunasta sitä koko ajastajassa, niin pitää ostajan sen huoneen kaupungin muurin sisältä pitämän ijankaikkisesti ja hänen sukunsa, ja ei pidä vapaaksi tuleman ilovuotena."],[25,31,"Mutta jos huone on maan kylässä, kussa ei yhtään muuria ympärillä ole, niin se pitää luettaman peltomaaksi: se lunastetaan ja tulee ilovuotena vapaaksi.","Mutta jos huone on maan kylässä, kussa ei yhtään muuria ympärillä ole, niin se pitää luettaman peltomaaksi: se lunastetaan ja tulee ilovuotena vapaaksi."],[25,32,"Leviläisten kaupungit ja huoneet kaupungeissa, joissa heidän tavaransa ovat, saavat he aina lunastaa.","Leviläisten kaupungit ja huoneet kaupungeissa, joissa heidän tavaransa ovat, saavat he aina lunastaa."],[25,33,"Se joka jotakin lunastaa Leviläisiltä, hänen pitää siitä luopuman ilovuonna, olkoon se ostettu huone eli omaisuus kaupungissa, jossa hän asunut on; sillä huoneet Leviläisten kaupungeissa ovat heidän omaisuutensa Israelin lasten seassa.","Se joka jotakin lunastaa Leviläisiltä, hänen pitää siitä luopuman ilovuonna, olkoon se ostettu huone eli omaisuus kaupungissa, jossa hän asunut on; sillä huoneet Leviläisten kaupungeissa ovat heidän omaisuutensa Israelin lasten seassa."],[25,34,"Mutta maata heidän kaupunkeinsa ympäriltä ei pidä myytämän; sillä se on heidän saamansa ijankaikkisesti.","Mutta maata heidän kaupunkeinsa ympäriltä ei pidä myytämän; sillä se on heidän saamansa ijankaikkisesti."],[25,35,"Jos veljes köyhtyy ja tulee voimattomaksi tykönäs, niin sinun pitää pitämän hänen ylös, niinkuin muukalaisen, taikka huonekuntaisen, että hän eläis sinun kanssas.","Jos veljes köyhtyy ja tulee voimattomaksi tykönäs, niin sinun pitää pitämän hänen ylös, niinkuin muukalaisen, taikka huonekuntaisen, että hän eläis sinun kanssas."],[25,36,"Ja ei sinun pidä ottaman korkoa eli voittoa häneltä; vaan pelkää sinun Jumalaas, että sinun veljes sais elää sinun kanssas.","Ja ei sinun pidä ottaman korkoa eli voittoa häneltä; vaan pelkää sinun Jumalaas, että sinun veljes sais elää sinun kanssas."],[25,37,"Ei sinun pidä antaman rahaas hänelle korolle, eikä antaman viljaas kasvulle.","Ei sinun pidä antaman rahaas hänelle korolle, eikä antaman viljaas kasvulle."],[25,38,"Sillä minä olen Herra teidän Jumalanne, joka teidän johdatin Egyptin maalta, antaakseni teille Kanaanin maan, ja ollakseni teidän Jumalanne.","Sillä minä olen Herra teidän Jumalanne, joka teidän johdatin Egyptin maalta, antaakseni teille Kanaanin maan, ja ollakseni teidän Jumalanne."],[25,39,"Jos veljes köyhtyy sinun tykönäs, ja myy itsensä sinulle, niin ei sinun pidä häntä pitämän niinkuin orjaa.","Jos veljes köyhtyy sinun tykönäs, ja myy itsensä sinulle, niin ei sinun pidä häntä pitämän niinkuin orjaa."],[25,40,"Mutta hänen pitää oleman sinun tykönäs niinkuin päivämiehen, eli huonekuntaisen, palvellen sinua riemuvuoteen asti.","Mutta hänen pitää oleman sinun tykönäs niinkuin päivämiehen, eli huonekuntaisen, palvellen sinua riemuvuoteen asti."],[25,41,"Silloin pitää hänen käymän ulos vapaana sinun tyköäs lapsinensa, ja pitää tuleman sukunsa tykö jälleen, ja isäinsä saaman päälle.","Silloin pitää hänen käymän ulos vapaana sinun tyköäs lapsinensa, ja pitää tuleman sukunsa tykö jälleen, ja isäinsä saaman päälle."],[25,42,"Sillä he ovat minun palveliani, jotka minä Egyptin maalta johdattanut olen: sentähden ei pidä heitä orjan tavalla myytämän.","Sillä he ovat minun palveliani, jotka minä Egyptin maalta johdattanut olen: sentähden ei pidä heitä orjan tavalla myytämän."],[25,43,"Ei sinun pidä ankarasti heitä hallitseman, vaan pelkäämän sinun Jumalaas.","Ei sinun pidä ankarasti heitä hallitseman, vaan pelkäämän sinun Jumalaas."],[25,44,"Jos tahdot pitää orjaa ja piikaa, niin sinun pitää ostaman ne pakanoilta, jotka teidän ympärillänne ovat.","Jos tahdot pitää orjaa ja piikaa, niin sinun pitää ostaman ne pakanoilta, jotka teidän ympärillänne ovat."],[25,45,"Ja huonekuntalaisilta, jotka muukalaiset ovat teidän seassanne, pitää teidän ne ostaman, ja heidän suvuiltansa, jotka he teidän tykönänne teidän maassanne synnyttäneet ovat: ja ne pitää teidän omanne oleman.","Ja huonekuntalaisilta, jotka muukalaiset ovat teidän seassanne, pitää teidän ne ostaman, ja heidän suvuiltansa, jotka he teidän tykönänne teidän maassanne synnyttäneet ovat: ja ne pitää teidän omanne oleman."],[25,46,"Ja pitäkäät heitä omananne, ja teidän lapsillenne teidän jälkeenne ijankaikkiseksi perimiseksi, ja niiden pitää oleman teidän orjanne; mutta veljenne Israelin lapset ei pidä toinen toistansa ankarasti hallitseman.","Ja pitäkäät heitä omananne, ja teidän lapsillenne teidän jälkeenne ijankaikkiseksi perimiseksi, ja niiden pitää oleman teidän orjanne; mutta veljenne Israelin lapset ei pidä toinen toistansa ankarasti hallitseman."],[25,47,"Jos muukalainen eli huonekuntainen hyötyy sinun tykönäs, ja sinun veljes köyhtyy hänen tykönänsä, niin että hän myy itsensä muukalaiselle, joka huonekuntainen sinun tykönäs on, eli jollekulle muukalaisen suvusta,","Jos muukalainen eli huonekuntainen hyötyy sinun tykönäs, ja sinun veljes köyhtyy hänen tykönänsä, niin että hän myy itsensä muukalaiselle, joka huonekuntainen sinun tykönäs on, eli jollekulle muukalaisen suvusta,"],[25,48,"Niin pitää hänellä oikeus oleman lunastettaa jälleen sittekuin hän myyty on, että joku hänen veljistänsä pitäis hänen lunastaman jällensä;","Niin pitää hänellä oikeus oleman lunastettaa jälleen sittekuin hän myyty on, että joku hänen veljistänsä pitäis hänen lunastaman jällensä;"],[25,49,"Eli hänen setänsä eli setänsä poika lunastakaan hänen, taikka joku hänen lähimmäisestä suvustansa, eli jos hän itse taitaa niin paljo matkaan saada, niin pitää hänen lunastaman itsensä.","Eli hänen setänsä eli setänsä poika lunastakaan hänen, taikka joku hänen lähimmäisestä suvustansa, eli jos hän itse taitaa niin paljo matkaan saada, niin pitää hänen lunastaman itsensä."],[25,50,"Ja hänen pitää lukua laskeman ostajansa kanssa, siitä vuodesta kuin hän myi itsensä ilovuoteen asti, ja raha pitää luettaman vuoden luvun jälkeen, sittekuin hän myytiin, ja kaiken sen ajan palkka pitää siihen luettaman:","Ja hänen pitää lukua laskeman ostajansa kanssa, siitä vuodesta kuin hän myi itsensä ilovuoteen asti, ja raha pitää luettaman vuoden luvun jälkeen, sittekuin hän myytiin, ja kaiken sen ajan palkka pitää siihen luettaman:"],[25,51,"Ja jos vielä monta vuotta on ilovuoteen, niin hänen pitää sitä enemmän antaman lunastuksestansa, senjälkeen kuin hän ostettu on.","Ja jos vielä monta vuotta on ilovuoteen, niin hänen pitää sitä enemmän antaman lunastuksestansa, senjälkeen kuin hän ostettu on."],[25,52,"Mutta jos harvat vuodet ovat ilovuoteen, niin laskekaan lukua hänen kanssansa ja hänen pitää vuotten jälkeen antaman lunastuksensa.","Mutta jos harvat vuodet ovat ilovuoteen, niin laskekaan lukua hänen kanssansa ja hänen pitää vuotten jälkeen antaman lunastuksensa."],[25,53,"Ja pitää hänen palkkansa myös siihen luettaman vuosi vuodelta, ja ei hänen pidä ankaruudella häntä hallitseman sinun edessäs.","Ja pitää hänen palkkansa myös siihen luettaman vuosi vuodelta, ja ei hänen pidä ankaruudella häntä hallitseman sinun edessäs."],[25,54,"Jos ei hän näin lunasta itsiänsä, niin hänen pitää ilovuonna vapaana käymän ulos lapsinensa.","Jos ei hän näin lunasta itsiänsä, niin hänen pitää ilovuonna vapaana käymän ulos lapsinensa."],[25,55,"Sillä Israelin lapset ovat minun palveliani; he ovat minun palveliani, jotka minä olen Egyptin maalta johdattanut ulos: Minä olen Herra teidän Jumalanne.","Sillä Israelin lapset ovat minun palveliani; he ovat minun palveliani, jotka minä olen Egyptin maalta johdattanut ulos: Minä olen Herra teidän Jumalanne."],[26,1,"Ei teidän pidä tekemän teillenne epäjumalia, ei kuvia, eikä myös patsaita pystyttämän teillenne, eikä myös yhtään merkkikiveä paneman teidän maallanne, kumartaaksenne niitä; sillä minä olen Herra teidän Jumalanne.","Ei teidän pidä tekemän teillenne epäjumalia, ei kuvia, eikä myös patsaita pystyttämän teillenne, eikä myös yhtään merkkikiveä paneman teidän maallanne, kumartaaksenne niitä; sillä minä olen Herra teidän Jumalanne."],[26,2,"Pitäkäät minun sabbatini, ja peljätkäät minun pyhyyttäni: Minä olen Herra.","Pitäkäät minun sabbatini, ja peljätkäät minun pyhyyttäni: Minä olen Herra."],[26,3,"Jos te säädyissäni vaellatte, ja minun käskyni kätkette, ja teette ne,","Jos te säädyissäni vaellatte, ja minun käskyni kätkette, ja teette ne,"],[26,4,"Niin minä annan teille sateen ajallansa, ja maa antaa kasvunsa, ja kedon puut antavat hedelmänsä.","Niin minä annan teille sateen ajallansa, ja maa antaa kasvunsa, ja kedon puut antavat hedelmänsä."],[26,5,"Ja riihen aika ulottuu viinan uutiseen asti, ja viinan uutinen ulottuu toukoaikaan asti, ja teillä pitää oleman leipää viljalta, ja saatte asua levollisesti teidän maassanne.","Ja riihen aika ulottuu viinan uutiseen asti, ja viinan uutinen ulottuu toukoaikaan asti, ja teillä pitää oleman leipää viljalta, ja saatte asua levollisesti teidän maassanne."],[26,6,"Ja minä annan rauhan teidän maallenne, ja te saatte levätä, ja ei kenkään teitä peljätä, ja minä ajan pahat pedot teidän maaltanne pois, ja miekan ei pidä käymän teidän maanne lävitse.","Ja minä annan rauhan teidän maallenne, ja te saatte levätä, ja ei kenkään teitä peljätä, ja minä ajan pahat pedot teidän maaltanne pois, ja miekan ei pidä käymän teidän maanne lävitse."],[26,7,"Teidän pitää vihollisianne ajaman takaa, ja heidän pitää kaatuman miekkaan teidän edessänne.","Teidän pitää vihollisianne ajaman takaa, ja heidän pitää kaatuman miekkaan teidän edessänne."],[26,8,"Viisi teistä karkottaa sata, ja sata teistä karkottaa kymmenentuhatta, ja teidän vihollisenne pitää kaatuman teidän edessänne miekkaan.","Viisi teistä karkottaa sata, ja sata teistä karkottaa kymmenentuhatta, ja teidän vihollisenne pitää kaatuman teidän edessänne miekkaan."],[26,9,"Ja minä käännän minuni teidän puoleenne, ja teen teidät hedelmälliseksi ja lisään teitä, ja vahvistan minun liittoni teidän kanssanne.","Ja minä käännän minuni teidän puoleenne, ja teen teidät hedelmälliseksi ja lisään teitä, ja vahvistan minun liittoni teidän kanssanne."],[26,10,"Ja te saatte syödä sitä vanhaa, joka vanhenee, ja vanhat te hylkäätte uuden tähden.","Ja te saatte syödä sitä vanhaa, joka vanhenee, ja vanhat te hylkäätte uuden tähden."],[26,11,"Ja minä panen asumasiani teidän keskellenne, ja minun sieluni ei hyljää teitä.","Ja minä panen asumasiani teidän keskellenne, ja minun sieluni ei hyljää teitä."],[26,12,"Ja minä vaellan teidän keskellänne ja olen teidän Jumalanne, ja teidän pitää oleman minun kanssani.","Ja minä vaellan teidän keskellänne ja olen teidän Jumalanne, ja teidän pitää oleman minun kanssani."],[26,13,"Sillä minä olen Herra teidän Jumalanne, joka johdatin teidät ulos Egyptin maalta, ettei teidän pitänyt oleman heidän orjansa. Minä olen taittanut poikki ikeenne vehmerän, ja olen antanut tiedän käydä pystyällä.","Sillä minä olen Herra teidän Jumalanne, joka johdatin teidät ulos Egyptin maalta, ettei teidän pitänyt oleman heidän orjansa. Minä olen taittanut poikki ikeenne vehmerän, ja olen antanut tiedän käydä pystyällä."],[26,14,"Mutta jos ette kuule minua, ettekä tee kaikkia näitä käskyjä,","Mutta jos ette kuule minua, ettekä tee kaikkia näitä käskyjä,"],[26,15,"Vaan suututte säätyihini, ja teidän sielunne hyljää minun oikeuteni, ettekä tee kaikkia minun käskyjäni, ja rikotte minun liittoni,","Vaan suututte säätyihini, ja teidän sielunne hyljää minun oikeuteni, ettekä tee kaikkia minun käskyjäni, ja rikotte minun liittoni,"],[26,16,"Niin minä teen teille nämät: minä rankaisen teitä vavistuksella, kuivataudilla, ja poltetaudilla, josta kasvonne raukeevat ja ruumiinne nääntyvät: ja teidän pitää siemenenne kylvämän turhaan, ja teidän vihollistenne pitää syömän sen.","Niin minä teen teille nämät: minä rankaisen teitä vavistuksella, kuivataudilla, ja poltetaudilla, josta kasvonne raukeevat ja ruumiinne nääntyvät: ja teidän pitää siemenenne kylvämän turhaan, ja teidän vihollistenne pitää syömän sen."],[26,17,"Ja minä asetan kasvoni teitä vastaan, ja te lyödään vihamiehiltänne, ja ne pitää hallitseman teitä, jotka teitä vihaavat, teidän pitää myös pakeneman, koska ei kenkään teitä aja takaa.","Ja minä asetan kasvoni teitä vastaan, ja te lyödään vihamiehiltänne, ja ne pitää hallitseman teitä, jotka teitä vihaavat, teidän pitää myös pakeneman, koska ei kenkään teitä aja takaa."],[26,18,"Jollette vielä sittekään kuule minua, niin minä lisään sen seitsemän kertaa, rangaistakseni teitä synteinne tähden.","Jollette vielä sittekään kuule minua, niin minä lisään sen seitsemän kertaa, rangaistakseni teitä synteinne tähden."],[26,19,"Ja minä särjen teidän ylpeytenne uppiniskaisuuden, minä teen teidän toivonne niinkuin raudan, ja teidän maanne niinkuin vasken.","Ja minä särjen teidän ylpeytenne uppiniskaisuuden, minä teen teidän toivonne niinkuin raudan, ja teidän maanne niinkuin vasken."],[26,20,"Ja teidän voimanne pitää hukkaan kulutettaman, niin ettei teidän maanne kasvoansa anna, eikä puut maalla hedelmäänsä anna.","Ja teidän voimanne pitää hukkaan kulutettaman, niin ettei teidän maanne kasvoansa anna, eikä puut maalla hedelmäänsä anna."],[26,21,"Ja jos te vielä minua vastaan vaellatte, ettekä tahdo kuulla minua, niin minä vielä sitte lisään rangaistuksen teidän päällenne seitsemän kertaa, teidän synteinne tähden.","Ja jos te vielä minua vastaan vaellatte, ettekä tahdo kuulla minua, niin minä vielä sitte lisään rangaistuksen teidän päällenne seitsemän kertaa, teidän synteinne tähden."],[26,22,"Ja lähetän teidän sekaanne metsän pedot syömään lapsianne, ja karjaanne raatelemaan, ja vähentämään teitä, ja teidän tienne pitää autioksi tuleman.","Ja lähetän teidän sekaanne metsän pedot syömään lapsianne, ja karjaanne raatelemaan, ja vähentämään teitä, ja teidän tienne pitää autioksi tuleman."],[26,23,"Jollette vielä niillä anna kuritettaa teitänne, mutta käytte minua vastaan,","Jollette vielä niillä anna kuritettaa teitänne, mutta käytte minua vastaan,"],[26,24,"Niin minä myös käyn teitä vastaan, ja lyön teitä vielä seitsemän kertaa enemmin, teidän synteinne tähden.","Niin minä myös käyn teitä vastaan, ja lyön teitä vielä seitsemän kertaa enemmin, teidän synteinne tähden."],[26,25,"Ja saatan päällenne kostomiekan, joka minun liittoni pitää kostaman, että te kokootte teitänne teidän kaupunkeihinne: sitte minä lähetän teidän sekaanne ruttotaudin, ja annan teitä vihamiestenne käteen.","Ja saatan päällenne kostomiekan, joka minun liittoni pitää kostaman, että te kokootte teitänne teidän kaupunkeihinne: sitte minä lähetän teidän sekaanne ruttotaudin, ja annan teitä vihamiestenne käteen."],[26,26,"Ja minä hukutan teiltä leivän aineen, niin että yhdessä pätsissä kymmenen vaimoa leipänne kypsentävät, ja punnitsevat leipänne vaalla: ja syötyänne ette tule ravituksi.","Ja minä hukutan teiltä leivän aineen, niin että yhdessä pätsissä kymmenen vaimoa leipänne kypsentävät, ja punnitsevat leipänne vaalla: ja syötyänne ette tule ravituksi."],[26,27,"Ja jollette vielä sitte kuule minua, mutta vaellatte minua vastaan,","Ja jollette vielä sitte kuule minua, mutta vaellatte minua vastaan,"],[26,28,"Niin minä myös hirmuisuudessa vaellan teitä vastaan, ja minä rankaisen teitä seitsemän kertaa enemmin, teidän synteinne tähden,","Niin minä myös hirmuisuudessa vaellan teitä vastaan, ja minä rankaisen teitä seitsemän kertaa enemmin, teidän synteinne tähden,"],[26,29,"Että teidän pitää syömän poikainne ja tytärtenne lihaa,","Että teidän pitää syömän poikainne ja tytärtenne lihaa,"],[26,30,"Ja minä kukistan teidän kukkulanne ja hävitän teidän kuvanne, ja panen teidän raatonne epäjumalainne raatoin päälle, ja minun sieluni kuoittaa teitä.","Ja minä kukistan teidän kukkulanne ja hävitän teidän kuvanne, ja panen teidän raatonne epäjumalainne raatoin päälle, ja minun sieluni kuoittaa teitä."],[26,31,"Ja teen kaupunkinne autioiksi ja kirkkonne hävitän, enkä myös teidän lepytyshajuanne haista.","Ja teen kaupunkinne autioiksi ja kirkkonne hävitän, enkä myös teidän lepytyshajuanne haista."],[26,32,"Ja minä tahdon hävittää maan, niin että vihollisenne, jotka siinä asuvat, pitää siitä hämmästymän.","Ja minä tahdon hävittää maan, niin että vihollisenne, jotka siinä asuvat, pitää siitä hämmästymän."],[26,33,"Ja hajoitan teitä pakanain sekaan, ja vedän ulos miekan teidän jälkeenne, ja maanne pitää tuleman kylmille ja kaupunkinne kukistetuksi.","Ja hajoitan teitä pakanain sekaan, ja vedän ulos miekan teidän jälkeenne, ja maanne pitää tuleman kylmille ja kaupunkinne kukistetuksi."],[26,34,"Silloin kelpaa maalle hänen leponsa, niinkauvan kuin hän autiona on, ja te olette vihollisten maalla. Ja silloin vasta maa lepää ja pyhää pitää.","Silloin kelpaa maalle hänen leponsa, niinkauvan kuin hän autiona on, ja te olette vihollisten maalla. Ja silloin vasta maa lepää ja pyhää pitää."],[26,35,"Niinkauvan kuin se autiona on, saa hän levätä, ettei hän saanut pyhää pitää, silloin koska teidän piti hänen pyhäänsä antaman pitää, koska te asuitte siellä.","Niinkauvan kuin se autiona on, saa hän levätä, ettei hän saanut pyhää pitää, silloin koska teidän piti hänen pyhäänsä antaman pitää, koska te asuitte siellä."],[26,36,"Ja niille, jotka jäävät teistä, teen minä vapisevan sydämen heidän vihollistensa maalla, niin että kapisevan lehden ääni karkottaa heitä, ja pitää pakeneman sitä niinkuin miekkaa, ja pitää kaatuman siinä, kussa ei kenkään heitä aja takaa.","Ja niille, jotka jäävät teistä, teen minä vapisevan sydämen heidän vihollistensa maalla, niin että kapisevan lehden ääni karkottaa heitä, ja pitää pakeneman sitä niinkuin miekkaa, ja pitää kaatuman siinä, kussa ei kenkään heitä aja takaa."],[26,37,"Ja heidän pitää lankeeman toinen toisensa päälle, niinkuin miekan edestä, vaikka ei yksikään karkota heitä, ja ette tohdi nousta vihamiehiänne vastaan.","Ja heidän pitää lankeeman toinen toisensa päälle, niinkuin miekan edestä, vaikka ei yksikään karkota heitä, ja ette tohdi nousta vihamiehiänne vastaan."],[26,38,"Ja teidän pitää hukkuman pakanain seassa, ja vihollisten maa pitää teitä syömän.","Ja teidän pitää hukkuman pakanain seassa, ja vihollisten maa pitää teitä syömän."],[26,39,"Ne kuin jäävät teistä, pitää vaipuman pahuudessansa, teidän vihollistenne maalla. Ja isäinsä pahoissa teoissa pitää teidän vaipuman.","Ne kuin jäävät teistä, pitää vaipuman pahuudessansa, teidän vihollistenne maalla. Ja isäinsä pahoissa teoissa pitää teidän vaipuman."],[26,40,"Silloin pitää heidän tunnustaman pahat tekonsa ja isäinsä pahat teot, joilla he ovat minun mieleni rikkoneet, ja vaeltaneet minua vastaan.","Silloin pitää heidän tunnustaman pahat tekonsa ja isäinsä pahat teot, joilla he ovat minun mieleni rikkoneet, ja vaeltaneet minua vastaan."],[26,41,"Sentähden minä myös vaellan heitä vastaan ja vien heitä vihollistensa maalle, että edes silloin heidän ympärileikkaamatoin sydämensä nöyryyttäis itsensä; silloin myös heidän pahan tekonsa rangaistus heille kelpaa.","Sentähden minä myös vaellan heitä vastaan ja vien heitä vihollistensa maalle, että edes silloin heidän ympärileikkaamatoin sydämensä nöyryyttäis itsensä; silloin myös heidän pahan tekonsa rangaistus heille kelpaa."],[26,42,"Ja minä muistan minun liittoni Jakobin kanssa, niin myös minun liittoni Isaakin kanssa, ja myös minun liittoni Abrahamin kanssa muistan minä, muistan myös maan,","Ja minä muistan minun liittoni Jakobin kanssa, niin myös minun liittoni Isaakin kanssa, ja myös minun liittoni Abrahamin kanssa muistan minä, muistan myös maan,"],[26,43,"Joka heiltä jätetty on, ja sille kelpaa lepopäivänsä, niinkauvan kuin se autiona on heiltä, ja heidän pahan tekonsa rangaistus heille kelpaa, että he hylkäsivät minun oikeuteni, ja heidän sielunsa on kuoittanut minun säätyjäni.","Joka heiltä jätetty on, ja sille kelpaa lepopäivänsä, niinkauvan kuin se autiona on heiltä, ja heidän pahan tekonsa rangaistus heille kelpaa, että he hylkäsivät minun oikeuteni, ja heidän sielunsa on kuoittanut minun säätyjäni."],[26,44,"Ja vaikka he vielä vihollistensa maalla ovat, en minä kuitenkaan ole heitä hyljännyt, ja en heitä niin kurittanut, että minä olisin heidän peräti hukuttanut, ja minun liittoni heidän kanssansa tyhjäksi tehnyt; sillä minä olen Herra heidän Jumalansa.","Ja vaikka he vielä vihollistensa maalla ovat, en minä kuitenkaan ole heitä hyljännyt, ja en heitä niin kurittanut, että minä olisin heidän peräti hukuttanut, ja minun liittoni heidän kanssansa tyhjäksi tehnyt; sillä minä olen Herra heidän Jumalansa."],[26,45,"Ja minä muistan ensimäisen liittoni heistä, koska minä johdatin heidät Egyptin maalta pakanain silmäin edestä, ollakseni heidän Jumalansa: minä Herra.","Ja minä muistan ensimäisen liittoni heistä, koska minä johdatin heidät Egyptin maalta pakanain silmäin edestä, ollakseni heidän Jumalansa: minä Herra."],[26,46,"Nämät ovat ne säädyt ja oikeudet ja käskyt, jotka Herra antoi itsensä ja Israelin lasten vaiheelle, Sinain vuorella, Moseksen käden kautta.","Nämät ovat ne säädyt ja oikeudet ja käskyt, jotka Herra antoi itsensä ja Israelin lasten vaiheelle, Sinain vuorella, Moseksen käden kautta."],[27,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[27,2,"Puhu Israelin lapsille ja sano heille: Jos joku tekee jonkun erinomaisen lupauksen, niin pitää ne sinun arvios jälkeen oleman Herran omat.","Puhu Israelin lapsille ja sano heille: Jos joku tekee jonkun erinomaisen lupauksen, niin pitää ne sinun arvios jälkeen oleman Herran omat."],[27,3,"Niin pitää tämän oleman sinun arvios: Kahdenkymmenen vuotisen miehenpuolen kuuteenkymmeneen vuoteen asti, pitää sinun arvaaman viiteenkymmeneen hopeasikliin, pyhän siklin jälkeen.","Niin pitää tämän oleman sinun arvios: Kahdenkymmenen vuotisen miehenpuolen kuuteenkymmeneen vuoteen asti, pitää sinun arvaaman viiteenkymmeneen hopeasikliin, pyhän siklin jälkeen."],[27,4,"Mutta vaimonpuolen pitää sinun arvaaman kolmeenkymmeneen sikliin.","Mutta vaimonpuolen pitää sinun arvaaman kolmeenkymmeneen sikliin."],[27,5,"Mutta viiden vuotisesta kahdenkymmenen vuotiseen asti, jos se on miehenpuoli, niin pitää sinun arvaaman kahteenkymmeneen sikliin, vaan vaimonpuolen kymmeneen sikliin.","Mutta viiden vuotisesta kahdenkymmenen vuotiseen asti, jos se on miehenpuoli, niin pitää sinun arvaaman kahteenkymmeneen sikliin, vaan vaimonpuolen kymmeneen sikliin."],[27,6,"Jos se on kuukautinen viidenteen vuoteen asti, ja on miehenpuoli, pitää sinun sen arvaaman viiteen hopeasikliin, mutta vaimonpuolen kolmeen hopeasikliin.","Jos se on kuukautinen viidenteen vuoteen asti, ja on miehenpuoli, pitää sinun sen arvaaman viiteen hopeasikliin, mutta vaimonpuolen kolmeen hopeasikliin."],[27,7,"Mutta jos se on kuudenkymmenen vuotinen eli sen päälle, ja miehenpuoli, pitää sinun arvaaman hänen viiteentoistakymmeneen sikliin, mutta vaimonpuolen kymmeneen sikliin.","Mutta jos se on kuudenkymmenen vuotinen eli sen päälle, ja miehenpuoli, pitää sinun arvaaman hänen viiteentoistakymmeneen sikliin, mutta vaimonpuolen kymmeneen sikliin."],[27,8,"Ja jos hän on ylen köyhä senkaltaiseen arvioon, niin pitää hänen menemän papin eteen, ja papin pitää arvaaman hänen. Sen jälkeen, kuin se, joka lupauksen tehnyt on, voi matkaan saada, pitää papin hänen arvaaman.","Ja jos hän on ylen köyhä senkaltaiseen arvioon, niin pitää hänen menemän papin eteen, ja papin pitää arvaaman hänen. Sen jälkeen, kuin se, joka lupauksen tehnyt on, voi matkaan saada, pitää papin hänen arvaaman."],[27,9,"Jos se on karjasta, jota Herralle uhrataan, kaikki mitä Herralle annetaan, se on pyhä.","Jos se on karjasta, jota Herralle uhrataan, kaikki mitä Herralle annetaan, se on pyhä."],[27,10,"Ei pidä sitä vaihetettaman eli muutettaman hyvä pahaan, eli paha hyvään. Jos joku kumminkin vaihettaa yhden eläimen toiseen, niin pitää he molemmat oleman pyhät.","Ei pidä sitä vaihetettaman eli muutettaman hyvä pahaan, eli paha hyvään. Jos joku kumminkin vaihettaa yhden eläimen toiseen, niin pitää he molemmat oleman pyhät."],[27,11,"Jos se eläin on saastainen, jota ei saada uhrata Herralle, niin pitää se vietämän papin eteen,","Jos se eläin on saastainen, jota ei saada uhrata Herralle, niin pitää se vietämän papin eteen,"],[27,12,"Ja papin pitää arvaaman sen, jos se on hyvä eli paha: sen pitää pysymän sinun arviossas, joka pappi olet.","Ja papin pitää arvaaman sen, jos se on hyvä eli paha: sen pitää pysymän sinun arviossas, joka pappi olet."],[27,13,"Jos joku kuitenkin tahtoo lunastaa sen, hänen pitää antaman viidennen osan sinun arvios päälle.","Jos joku kuitenkin tahtoo lunastaa sen, hänen pitää antaman viidennen osan sinun arvios päälle."],[27,14,"Ja jos joku pyhittää huoneensa Herralle pyhäksi, niin pitää papin arvaaman sen, jos se on hyvä eli paha: ja papin arviossa pitää sen pysymän.","Ja jos joku pyhittää huoneensa Herralle pyhäksi, niin pitää papin arvaaman sen, jos se on hyvä eli paha: ja papin arviossa pitää sen pysymän."],[27,15,"Mutta jos pyhittänyt tahtoo lunastaa huoneensa, niin pitää hänen antaman viidennen osan enemmän rahaa, kuin sinun arvios on, ja niin pitää se hänen oleman.","Mutta jos pyhittänyt tahtoo lunastaa huoneensa, niin pitää hänen antaman viidennen osan enemmän rahaa, kuin sinun arvios on, ja niin pitää se hänen oleman."],[27,16,"Jos joku pyhittää Herralle kappaleen peltoa perintömaastansa, niin pitää sinun se arvaaman sen jälkeen, kuin siihen kylvetään; jos siihen kylvetään homer ohria, niin pitää sen maksaman viisikymmentä hopeasikliä.","Jos joku pyhittää Herralle kappaleen peltoa perintömaastansa, niin pitää sinun se arvaaman sen jälkeen, kuin siihen kylvetään; jos siihen kylvetään homer ohria, niin pitää sen maksaman viisikymmentä hopeasikliä."],[27,17,"Vaan jos hän pyhittää peltonsa ilovuodesta alkain, niin pitää sen maksaman sinun arvios jälkeen.","Vaan jos hän pyhittää peltonsa ilovuodesta alkain, niin pitää sen maksaman sinun arvios jälkeen."],[27,18,"Jos hän on pyhittänyt peltonsa ilovuoden jälkeen, niin papin pitää lukeman hänelle rahan vuoden luvun jälkeen, kuin takaperin on ilovuoteen asti, ja se pitää sinun arviostas vähennettämän.","Jos hän on pyhittänyt peltonsa ilovuoden jälkeen, niin papin pitää lukeman hänelle rahan vuoden luvun jälkeen, kuin takaperin on ilovuoteen asti, ja se pitää sinun arviostas vähennettämän."],[27,19,"Jos se joka pellon pyhittänyt on, tahtoo sen todella lunastaa jälleen, niin pitää hänen antaman viidettä osaa enemmän rahaa, kuin se sinulta arvattu on, ja niin pitää se hänen oleman.","Jos se joka pellon pyhittänyt on, tahtoo sen todella lunastaa jälleen, niin pitää hänen antaman viidettä osaa enemmän rahaa, kuin se sinulta arvattu on, ja niin pitää se hänen oleman."],[27,20,"Jos ei hän tahdo lunastaa peltoa, mutta myy sen toiselle, niin ei pidä sitä enää lunastettaman.","Jos ei hän tahdo lunastaa peltoa, mutta myy sen toiselle, niin ei pidä sitä enää lunastettaman."],[27,21,"Vaan se pelto, koska se ilovuonna tulee vapaaksi, pitää oleman pyhä Herralle, niinkuin valallisella lupauksella eroitettu pelto, ja pitää oleman papin perintösaama.","Vaan se pelto, koska se ilovuonna tulee vapaaksi, pitää oleman pyhä Herralle, niinkuin valallisella lupauksella eroitettu pelto, ja pitää oleman papin perintösaama."],[27,22,"Jos joku sen pellon, jonka hän ostanut on, joka ei ole hänen perintömaansa, pyhittää Herralle,","Jos joku sen pellon, jonka hän ostanut on, joka ei ole hänen perintömaansa, pyhittää Herralle,"],[27,23,"Niin pitää papin laskeman hänen edessänsä sen hinnan sinun arvios jälkeen, ilovuoteen asti, ja hänen pitää sen samana päivänä antaman ulos, sinun arvios jälkeen, että se Herralle pyhä olis;","Niin pitää papin laskeman hänen edessänsä sen hinnan sinun arvios jälkeen, ilovuoteen asti, ja hänen pitää sen samana päivänä antaman ulos, sinun arvios jälkeen, että se Herralle pyhä olis;"],[27,24,"Mutta ilovuonna pitää sen tuleman hänen omaksensa jälleen, jolta hän sen ostanut on, että se oli hänen perintösaamansa maalla.","Mutta ilovuonna pitää sen tuleman hänen omaksensa jälleen, jolta hän sen ostanut on, että se oli hänen perintösaamansa maalla."],[27,25,"Kaikki sinun arvios pitää tapahtuman pyhän siklin jälkeen; mutta sikli tekee kaksikymmentä geraa.","Kaikki sinun arvios pitää tapahtuman pyhän siklin jälkeen; mutta sikli tekee kaksikymmentä geraa."],[27,26,"Mutta eläinten esikoista, joka esikko-oikeuden jälkeen Herran oma muutoinkin on, ei pidä kenenkään pyhittämän, olkoon härkä eli lammas; sillä se on Herran.","Mutta eläinten esikoista, joka esikko-oikeuden jälkeen Herran oma muutoinkin on, ei pidä kenenkään pyhittämän, olkoon härkä eli lammas; sillä se on Herran."],[27,27,"Jos jotakin saastaista on eläinten seassa, niin se pitää lunastettaman sinun arvios jälkeen, ja siihen lisäksi annettaman viides osa; jos ei sitä lunasteta, niin se myytäkään sinun arvios jälkeen.","Jos jotakin saastaista on eläinten seassa, niin se pitää lunastettaman sinun arvios jälkeen, ja siihen lisäksi annettaman viides osa; jos ei sitä lunasteta, niin se myytäkään sinun arvios jälkeen."],[27,28,"Kuitenkin kaikkea valallisella lupauksella eroitettua, jota joku valallisesti lupaa Herralle kaikesta mitä hänellä on, joko se olis ihminen, eläin eli perintöpelto, ei sitä pidä myytämän eli lunastettaman; sillä kaikki valallisellla lupauksella eroitettu on kaikkein pyhin Herralle.","Kuitenkin kaikkea valallisella lupauksella eroitettua, jota joku valallisesti lupaa Herralle kaikesta mitä hänellä on, joko se olis ihminen, eläin eli perintöpelto, ei sitä pidä myytämän eli lunastettaman; sillä kaikki valallisellla lupauksella eroitettu on kaikkein pyhin Herralle."],[27,29,"Kaikkea kirottua, joka kiroukseen annetaan ihmisistä, ei pidä lunastettaman, vaan hän pitää totisesti kuoletettaman.","Kaikkea kirottua, joka kiroukseen annetaan ihmisistä, ei pidä lunastettaman, vaan hän pitää totisesti kuoletettaman."],[27,30,"Kaikki maan kymmenykset, sekä maan siemenestä että puiden hedelmistä, ovat Herran, ja pitää oleman pyhät Herralle.","Kaikki maan kymmenykset, sekä maan siemenestä että puiden hedelmistä, ovat Herran, ja pitää oleman pyhät Herralle."],[27,31,"Jos joku tahtoo lunastaa kymmenyksensä, hänen pitää antaman viidennen osan lisäksi.","Jos joku tahtoo lunastaa kymmenyksensä, hänen pitää antaman viidennen osan lisäksi."],[27,32,"Ja kaikki kymmenykset karjasta, ja lampaista, ja kaikista kuin vitsan alla käy, ne ovat pyhät kymmenykset Herralle.","Ja kaikki kymmenykset karjasta, ja lampaista, ja kaikista kuin vitsan alla käy, ne ovat pyhät kymmenykset Herralle."],[27,33,"Ei pidä kysyttämän, jos se on hyvä eli paha, eikä myös pidä sitä vaihetettaman. Jos joku vaihettaa sen, niin pitää ne molemmat oleman pyhät, ja ei lunastettaman.","Ei pidä kysyttämän, jos se on hyvä eli paha, eikä myös pidä sitä vaihetettaman. Jos joku vaihettaa sen, niin pitää ne molemmat oleman pyhät, ja ei lunastettaman."],[27,34,"Nämät ovat ne käskyt, jotka Herra antoi Moseksen kautta Israelin lapsille, Sinain vuorella.","Nämät ovat ne käskyt, jotka Herra antoi Moseksen kautta Israelin lapsille, Sinain vuorella."]]}};